/**
 * Admin live-chat inbox. Two-pane layout: a conversation list (unread + newest
 * first) and a thread view with a reply box. Polls `listConversations` every
 * few seconds so new visitor messages appear without a manual refresh.
 */

type Attachment = { id: string; mime: string; sizeBytes: number };
type Msg = {
  id: string;
  sender: string;
  body: string;
  createdAt: string;
  attachment?: Attachment | null;
};
type Convo = {
  id: string;
  visitorId: string;
  userId: string | null;
  name: string | null;
  email: string | null;
  status: string;
  assignedToId: string | null;
  assignedToName: string | null;
  unreadForAgent: boolean;
  lastMessageAt: string;
  createdAt: string;
  visitorTyping: boolean;
  aiPaused: boolean;
  /** Server count for a registered customer (userId set); null for an anonymous visitor. */
  serverCount: number | null;
  /** The linked account is a creator partner (ReferralPartner.userId) — name renders magenta + chip. */
  isCreator?: boolean;
  messages: Msg[];
};

/** Three-dot "typing…" pulse, matching the widget's indicator. */
function TypingDots() {
  return (
    <span className="flex items-center gap-1" aria-hidden="true">
      {[0, 150, 300].map((delay) => (
        <span
          key={delay}
          className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-300"
          style={{ animationDelay: `${delay}ms`, animationDuration: "1s" }}
        />
      ))}
    </span>
  );
}

/** Small robot glyph used to mark AI-assistant messages, matching the widget. */
function BotIcon({ className = "" }: { className?: string }) {
  return (
    <svg
      width="11"
      height="11"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
      aria-hidden
    >
      <path d="M12 2v3M5 8h14a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1zM9 13h.01M15 13h.01" />
    </svg>
  );
}

const POLL_MS = 5000;

// Client-side pre-checks only; replyWithAttachment re-validates by signature.
const ACCEPT_IMAGES = "image/png,image/jpeg,image/gif,image/webp";
const ALLOWED_IMAGE_TYPES = new Set(["image/png", "image/jpeg", "image/gif", "image/webp"]);
const MAX_IMAGE_BYTES = 5 * 1024 * 1024;

function imageError(file: File): string | null {
  if (!ALLOWED_IMAGE_TYPES.has(file.type)) return "Only PNG, JPEG, GIF, or WEBP images.";
  if (file.size > MAX_IMAGE_BYTES) return "Image must be 5 MB or smaller.";
  return null;
}

function timeAgo(iso: string): string {
  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

export default function ChatInbox({ initial }: { initial: Convo[] }) {
  const [convos, setConvos] = useState<Convo[]>(initial);
  const [selectedId, setSelectedId] = useState<string | null>(initial[0]?.id ?? null);
  const [draft, setDraft] = useState("");
  const [query, setQuery] = useState("");
  const [error, setError] = useState("");
  const [pendingImage, setPendingImage] = useState<{ file: File; url: string } | null>(null);
  const [pending, start] = useTransition();
  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const lastTypingPingRef = useRef(0); // throttle "agent is typing" pings
  // Mic-to-text for the reply box — same Web Speech hook the Kodely build
  // console uses (components/customer/claude-code/voice.tsx); feature-detects
  // and the button below simply doesn't render when unsupported (e.g. Firefox).
  const voice = useVoiceDictation(setDraft);

  useEffect(() => {
    return () => {
      if (pendingImage) URL.revokeObjectURL(pendingImage.url);
    };
  }, [pendingImage]);

  useEffect(() => {
    if (voice.error) setError(voice.error);
  }, [voice.error]);

  function pickImage(file: File | null | undefined) {
    if (!file) return;
    const err = imageError(file);
    if (err) {
      setError(err);
      return;
    }
    setError("");
    setPendingImage((prev) => {
      if (prev) URL.revokeObjectURL(prev.url);
      return { file, url: URL.createObjectURL(file) };
    });
  }

  function clearImage() {
    setPendingImage((prev) => {
      if (prev) URL.revokeObjectURL(prev.url);
      return null;
    });
    if (fileInputRef.current) fileInputRef.current.value = "";
  }

  function onPaste(e: ClipboardEvent) {
    const item = Array.from(e.clipboardData?.items ?? []).find((i) =>
      i.type.startsWith("image/")
    );
    if (item) {
      const file = item.getAsFile();
      if (file) {
        e.preventDefault();
        pickImage(file);
      }
    }
  }

  const refresh = useCallback(async () => {
    try {
      const rows = await listConversations();
      setConvos(rows);
    } catch {
      /* transient — next poll retries */
    }
  }, []);

  useEffect(() => {
    const t = setInterval(refresh, POLL_MS);
    return () => clearInterval(t);
  }, [refresh]);

  const selected = convos.find((c) => c.id === selectedId) ?? null;

  // Tell the visitor's widget this agent is composing, throttled to ~once/2.5s.
  function pingTyping() {
    if (!selectedId) return;
    const now = Date.now();
    if (now - lastTypingPingRef.current < 2500) return;
    lastTypingPingRef.current = now;
    void signalAgentTyping(selectedId);
  }

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
  }, [selected?.messages.length, selectedId]);

  function doReply() {
    if (!selected || pending) return;
    if (!draft.trim() && !pendingImage) return;
    const body = draft;
    setError("");

    if (pendingImage) {
      const fd = new FormData();
      fd.append("conversationId", selected.id);
      fd.append("file", pendingImage.file);
      if (body.trim()) fd.append("body", body.trim());
      start(async () => {
        const res = await replyWithAttachment(fd);
        if (res.error) {
          setError(res.error);
          return;
        }
        setDraft("");
        clearImage();
        await refresh();
      });
      return;
    }

    start(async () => {
      const res = await replyToConversation(selected.id, body);
      if (res.error) {
        setError(res.error);
        return;
      }
      setDraft("");
      await refresh();
    });
  }

  function doClose() {
    if (!selected) return;
    start(async () => {
      await closeConversation(selected.id);
      await refresh();
    });
  }

  function doCloseAll() {
    const openCount = convos.filter((c) => c.status !== "CLOSED").length;
    if (openCount === 0 || pending) return;
    if (
      typeof window !== "undefined" &&
      !window.confirm(`Close all ${openCount} open conversation${openCount === 1 ? "" : "s"}?`)
    ) {
      return;
    }
    start(async () => {
      await closeAllConversations();
      await refresh();
    });
  }

  function doAssign() {
    if (!selected) return;
    start(async () => {
      await assignConversation(selected.id);
      await refresh();
    });
  }

  function doToggleAi() {
    if (!selected || pending) return;
    start(async () => {
      const res = await toggleAiPaused(selected.id);
      if (res.error) {
        setError(res.error);
        return;
      }
      await refresh();
    });
  }

  function doTransfer() {
    if (!selected || pending) return;
    if (
      typeof window !== "undefined" &&
      !window.confirm("Transfer this conversation to a support ticket? The chat will be closed.")
    ) {
      return;
    }
    setError("");
    start(async () => {
      const res = await transferChatToTicket(selected.id);
      // A successful transfer redirects server-side and never returns here —
      // reaching this line means it was refused (e.g. no linked customer account).
      if (res?.error) setError(res.error);
    });
  }

  function label(c: Convo): string {
    return c.name || c.email || `Visitor ${c.visitorId.slice(0, 8)}`;
  }

  // Who authored a given message, from the staff perspective. The bot ("bot") is
  // always the AI assistant; a human reply ("agent") is attributed to the agent
  // handling the thread (assignedToName), or a generic "Support agent" fallback.
  function messageAuthor(c: Convo, m: Msg): string {
    if (m.sender === "bot") return "Nxeon Assistant · AI";
    if (m.sender === "agent") return c.assignedToName || "Support agent";
    return label(c);
  }

  // One-line preview of the last message for the list, prefixed by who sent it.
  function lastPreview(c: Convo): string {
    const last = c.messages[c.messages.length - 1];
    if (!last) return "…";
    const body = last.body || (last.attachment ? "📎 image" : "");
    if (last.sender === "agent") return `You: ${body}`;
    if (last.sender === "bot") return `AI: ${body}`;
    return body;
  }

  const q = query.trim().toLowerCase();
  const filtered = q
    ? convos.filter((c) => {
        const haystack = [
          c.name,
          c.email,
          c.visitorId,
          c.assignedToName,
          ...c.messages.map((m) => m.body),
        ]
          .filter(Boolean)
          .join(" ")
          .toLowerCase();
        return haystack.includes(q);
      })
    : convos;

  const openCount = convos.filter((c) => c.status !== "CLOSED").length;

  return (
    <div className="grid gap-4 lg:grid-cols-[20rem_1fr]">
      {/* Conversation list */}
      <div className="card flex max-h-[70vh] flex-col p-0">
        {/* Toolbar: search + bulk close */}
        <div className="space-y-2 border-b border-white/10 p-2.5">
          <div className="relative">
            <svg
              width="15"
              height="15"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500"
              aria-hidden
            >
              <circle cx="11" cy="11" r="7" />
              <path d="m21 21-4.3-4.3" />
            </svg>
            <input
              type="search"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search name, email or message…"
              aria-label="Search conversations"
              className="input w-full py-1.5 pl-8 pr-2 text-xs"
            />
          </div>
          <div className="flex items-center justify-between gap-2 px-0.5">
            <span className="text-[11px] text-slate-500">
              {filtered.length === convos.length
                ? `${convos.length} conversation${convos.length === 1 ? "" : "s"}`
                : `${filtered.length} of ${convos.length}`}
            </span>
            <button
              type="button"
              onClick={doCloseAll}
              disabled={pending || openCount === 0}
              className="rounded-lg border border-white/10 px-2 py-0.5 text-[11px] text-slate-300 transition hover:bg-white/[0.06] disabled:opacity-40"
            >
              Close all{openCount > 0 ? ` (${openCount})` : ""}
            </button>
          </div>
        </div>

        <div className="flex-1 space-y-1 overflow-y-auto p-2">
          {convos.length === 0 && (
            <p className="p-4 text-center text-sm text-slate-500">No conversations yet.</p>
          )}
          {convos.length > 0 && filtered.length === 0 && (
            <p className="p-4 text-center text-sm text-slate-500">No matches for “{query}”.</p>
          )}
          {filtered.map((c) => {
            const active = c.id === selectedId;
            const closed = c.status === "CLOSED";
            return (
              <button
                key={c.id}
                onClick={() => setSelectedId(c.id)}
                className={`w-full rounded-xl border px-3 py-2.5 text-left transition ${
                  active
                    ? "border-brand-500/50 bg-brand-500/10"
                    : "border-transparent hover:bg-white/[0.04]"
                }`}
              >
                <div className="flex items-center justify-between gap-2">
                  <span
                    className={`truncate text-sm font-medium ${
                      closed ? "text-slate-400" : "text-slate-100"
                    }`}
                  >
                    <UserName name={label(c)} creator={!!c.isCreator} />
                  </span>
                  <div className="flex shrink-0 items-center gap-1.5">
                    {c.unreadForAgent && !closed && (
                      <span
                        className="h-2 w-2 rounded-full bg-amber-400"
                        title="Needs a reply"
                      />
                    )}
                    {closed && (
                      <span className="rounded bg-white/[0.06] px-1.5 py-0.5 text-[9px] font-medium uppercase tracking-wide text-slate-500">
                        closed
                      </span>
                    )}
                  </div>
                </div>
                <div className="mt-0.5 flex items-center justify-between gap-2">
                  <span className="truncate text-xs text-slate-400">{lastPreview(c)}</span>
                  <span className="shrink-0 text-[10px] text-slate-500">
                    {timeAgo(c.lastMessageAt)}
                  </span>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* Thread view */}
      <div className="card flex max-h-[70vh] flex-col p-0">
        {!selected ? (
          <div className="flex flex-1 items-center justify-center p-10 text-sm text-slate-500">
            Select a conversation to view it.
          </div>
        ) : (
          <>
            <div className="flex flex-wrap items-center justify-between gap-2 border-b border-white/10 px-4 py-3">
              <div>
                <p className="text-sm font-semibold text-slate-100">
                  {selected.userId ? (
                    <Link href={`/admin/users/${selected.userId}`} className="hover:text-brand-300">
                      <UserName name={label(selected)} creator={!!selected.isCreator} />
                    </Link>
                  ) : (
                    label(selected)
                  )}
                </p>
                <p className="text-xs text-slate-400">
                  {selected.email || "no email"}
                  {selected.userId
                    ? ` · registered customer · ${selected.serverCount ?? 0} server${selected.serverCount === 1 ? "" : "s"}`
                    : " · guest"}{" "}
                  · {selected.status.toLowerCase()}
                  {selected.assignedToName ? ` · assigned to ${selected.assignedToName}` : ""}
                </p>
              </div>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={doToggleAi}
                  disabled={pending}
                  title={
                    selected.aiPaused
                      ? "The AI assistant is paused on this thread — click to resume it."
                      : "The AI assistant may answer this thread — click to pause it."
                  }
                  className={`rounded-lg border px-2.5 py-1 text-xs font-medium transition disabled:opacity-50 ${
                    selected.aiPaused
                      ? "border-amber-400/30 bg-amber-500/10 text-amber-300 hover:bg-amber-500/20"
                      : "border-brand-400/30 bg-brand-500/10 text-brand-200 hover:bg-brand-500/20"
                  }`}
                >
                  {selected.aiPaused ? "AI: Paused" : "AI: On"}
                </button>
                <button
                  className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
                  onClick={doAssign}
                  disabled={pending}
                >
                  Assign to me
                </button>
                {selected.status !== "CLOSED" && (
                  <button
                    className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
                    onClick={doClose}
                    disabled={pending}
                  >
                    Close
                  </button>
                )}
                <button
                  className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
                  onClick={doTransfer}
                  disabled={pending}
                  title="Copy this conversation into a new support ticket and close the chat."
                >
                  Transfer to ticket
                </button>
              </div>
            </div>

            <div ref={scrollRef} className="flex-1 space-y-3 overflow-y-auto px-4 py-4">
              {selected.messages.map((m) => {
                const isCustomer = m.sender === "visitor";
                const isBot = m.sender === "bot";
                // Staff (human agent + AI bot) sit on the right, opposite the
                // customer, each with a distinct bubble and an author label.
                return (
                  <div
                    key={m.id}
                    className={`flex flex-col ${isCustomer ? "items-start" : "items-end"}`}
                  >
                    <span
                      className={`mb-0.5 flex items-center gap-1 px-1 text-[11px] font-medium ${
                        isBot ? "text-brand-300" : isCustomer ? "text-slate-400" : "text-brand-200"
                      }`}
                    >
                      {isBot && <BotIcon />}
                      {messageAuthor(selected, m)}
                    </span>
                    <div
                      className={`max-w-[75%] space-y-1.5 whitespace-pre-wrap rounded-2xl px-3.5 py-2 text-sm ${
                        isCustomer
                          ? "border border-white/10 bg-white/[0.06] text-slate-200"
                          : isBot
                            ? "border border-brand-400/30 bg-brand-500/10 text-slate-100"
                            : "bg-brand-500 text-white"
                      }`}
                    >
                      {m.attachment && (
                        <LightboxImage
                          src={`/api/chat/attachment/${m.attachment.id}`}
                          alt="attachment"
                          className="max-h-48 max-w-full rounded-lg border border-white/10 object-contain"
                        />
                      )}
                      {m.body && <div>{m.body}</div>}
                      <div
                        className={`mt-1 text-[10px] ${
                          isCustomer || isBot ? "text-slate-500" : "text-white/60"
                        }`}
                      >
                        {timeAgo(m.createdAt)}
                      </div>
                    </div>
                  </div>
                );
              })}
              {selected.visitorTyping && (
                <div className="flex justify-start" aria-live="polite">
                  <div className="flex items-center gap-2 rounded-2xl border border-white/10 bg-white/[0.06] px-3.5 py-2.5">
                    <TypingDots />
                    <span className="text-[11px] text-slate-400">{label(selected)} is typing…</span>
                  </div>
                </div>
              )}
            </div>

            <div className="border-t border-white/10 px-4 py-3">
              {error && <p className="mb-2 text-xs text-red-400">{error}</p>}
              <div className="mb-2 flex justify-end">
                <CannedReplyPicker
                  disabled={pending}
                  onInsert={(snippet) => setDraft((prev) => (prev.trim() ? `${prev}\n\n${snippet}` : snippet))}
                />
              </div>
              {pendingImage && (
                <div className="mb-2 flex items-center gap-2">
                  <div className="relative">
                    {/* eslint-disable-next-line @next/next/no-img-element */}
                    <img
                      src={pendingImage.url}
                      alt="preview"
                      className="h-14 w-14 rounded-lg border border-white/10 object-cover"
                    />
                    <button
                      type="button"
                      aria-label="Remove image"
                      onClick={clearImage}
                      className="absolute -right-1.5 -top-1.5 flex h-5 w-5 items-center justify-center rounded-full bg-slate-800 text-slate-200 ring-1 ring-white/20 hover:bg-slate-700"
                    >
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
                        <path d="M18 6 6 18M6 6l12 12" />
                      </svg>
                    </button>
                  </div>
                  <span className="truncate text-xs text-slate-400">{pendingImage.file.name}</span>
                </div>
              )}
              <input
                ref={fileInputRef}
                type="file"
                accept={ACCEPT_IMAGES}
                className="hidden"
                onChange={(e) => pickImage(e.target.files?.[0])}
              />
              <div className="flex items-end gap-2">
                <button
                  type="button"
                  aria-label="Attach image"
                  onClick={() => fileInputRef.current?.click()}
                  disabled={pending}
                  className="shrink-0 rounded-lg p-2 text-slate-400 hover:bg-white/10 hover:text-slate-200 disabled:opacity-50"
                >
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <path d="M21.44 11.05 12.25 20.24a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48" />
                  </svg>
                </button>
                {voice.supported && (
                  <button
                    type="button"
                    aria-label={voice.listening ? "Stop voice input" : "Start voice input"}
                    title={voice.listening ? "Stop voice input" : "Dictate your reply"}
                    onClick={() => voice.toggle(draft)}
                    disabled={pending}
                    className={`shrink-0 rounded-lg p-2 transition disabled:opacity-50 ${
                      voice.listening
                        ? "animate-pulse bg-red-500/20 text-red-400"
                        : "text-slate-400 hover:bg-white/10 hover:text-slate-200"
                    }`}
                  >
                    <svg
                      width="20"
                      height="20"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z" />
                      <path d="M19 10v2a7 7 0 0 1-14 0v-2M12 19v4M8 23h8" />
                    </svg>
                  </button>
                )}
                <textarea
                  className="input min-h-[2.5rem] flex-1 resize-none py-2 text-sm"
                  placeholder="Type your reply…"
                  value={draft}
                  maxLength={5000}
                  rows={1}
                  onChange={(e) => {
                    setDraft(e.target.value);
                    if (e.target.value.trim()) pingTyping();
                  }}
                  onPaste={onPaste}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && !e.shiftKey) {
                      e.preventDefault();
                      doReply();
                    }
                  }}
                  disabled={pending}
                />
                <button
                  className="btn-primary shrink-0 px-4 py-2 text-sm"
                  onClick={doReply}
                  disabled={pending || (!draft.trim() && !pendingImage)}
                >
                  {pending ? "…" : "Reply"}
                </button>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
import { readTyping } from "@/lib/chat-typing";
import { readBotStep } from "@/lib/chat-bot-step";
import { mirrorChatMessageToDiscord } from "@/lib/discord-bridge";

export const runtime = "nodejs";

/**
 * Public live-chat endpoint used by <ChatWidget/>.
 *
 * POST /api/chat  — start or continue a conversation for a visitorId.
 * GET  /api/chat?visitorId=…  — poll the visitor's open conversation.
 *
 * Everything is scoped strictly by the client-supplied `visitorId`; we never
 * return another visitor's data. Signed-in customers additionally get their
 * `userId` stamped on the conversation. Unauthenticated + write-heavy, so the
 * POST path is rate-limited per IP.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

type AttachmentRow = { id: string; mime: string; sizeBytes: number } | null;

function serialize(convo: {
  id: string;
  status: string;
  name: string | null;
  email: string | null;
  messages: {
    id: string;
    sender: string;
    body: string;
    cardsJson?: string | null;
    createdAt: Date;
    attachment?: AttachmentRow;
  }[];
}) {
  return {
    conversation: {
      id: convo.id,
      status: convo.status,
      name: convo.name,
      email: convo.email,
    },
    messages: convo.messages.map((m) => {
      let cards: unknown = null;
      if (m.cardsJson) {
        try {
          cards = JSON.parse(m.cardsJson);
        } catch {
          cards = null;
        }
      }
      return {
        id: m.id,
        sender: m.sender,
        body: m.body,
        createdAt: m.createdAt.toISOString(),
        cards,
        attachment: m.attachment
          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
          : null,
      };
    }),
  };
}

export async function POST(req: Request) {
  const rl = checkRateLimit(`chat:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "Too many messages. Please slow down." },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const visitorId = clip(raw.visitorId, 100);
  const conversationId = clip(raw.conversationId, 40);
  const body = clip(raw.body, 5000);
  const name = clip(raw.name, 120);
  const email = clip(raw.email, 200);

  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
  if (!body) return NextResponse.json({ error: "Message cannot be empty." }, { status: 400 });

  const user = await currentUser();
  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
    user?.id ? [{ userId: user.id }] : [],
  );

  // If the client names a conversation it owns, continue it (resuming past
  // history, reopening if it was closed). Otherwise start a brand-new one — we
  // no longer auto-resume the latest, so returning gives a fresh chat while old
  // threads stay available in the history list.
  let convo = conversationId
    ? await db.chatConversation.findFirst({
        where: { id: conversationId, OR: ownedBy },
        select: { id: true, name: true, email: true },
      })
    : null;

  if (!convo) {
    // Anonymous (not signed in) visitors must give a name + valid email before
    // starting. Signed-in customers already have both, so they're never asked.
    if (!user) {
      const nm = name ?? null;
      const em = email ?? null;
      if (!nm || !em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) {
        return NextResponse.json(
          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
          { status: 400 },
        );
      }
    }
    convo = await db.chatConversation.create({
      data: {
        visitorId,
        userId: user?.id ?? null,
        name: name ?? user?.name ?? null,
        email: email ?? user?.email ?? null,
      },
      select: { id: true, name: true, email: true },
    });
  }

  await db.$transaction([
    db.chatMessage.create({
      data: { conversationId: convo.id, sender: "visitor", body },
    }),
    db.chatConversation.update({
      where: { id: convo.id },
      data: {
        status: "OPEN", // reopen if the visitor is resuming a closed thread
        unreadForAgent: true,
        lastMessageAt: new Date(),
        // Backfill identity / link account if it arrives after creation.
        ...(user?.id ? { userId: user.id } : {}),
        ...(name && !convo.name ? { name } : {}),
        ...(email && !convo.email ? { email } : {}),
      },
    }),
  ]);

  // Discord bridge (Phase 1 mirror): best-effort, never blocks the visitor's
  // message — creates the guild channel on the visitor's FIRST message, posts
  // into the existing channel on every message after — see
  // lib/discord-bridge.ts's mirrorChatMessageToDiscord.
  await mirrorChatMessageToDiscord(convo.id, body, "visitor");

  // AI assistant + human-handoff orchestration (see lib/kb-run.ts). Best-effort
  // and fully wrapped: it must NEVER break live chat, and it stays silent once a
  // human has engaged.
  try {
    const { runAssistant } = await import("@/lib/kb-run");
    await runAssistant({ conversationId: convo.id, visitorId, currentBody: body });
  } catch {
    /* assistant is non-essential — never fail the visitor's message on it */
  }

  const full = await db.chatConversation.findUnique({
    where: { id: convo.id },
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });
  return NextResponse.json(serialize(full!), { headers: NO_STORE_HEADERS });
}

export async function GET(req: Request) {
  const url = new URL(req.url);
  const visitorId = clip(url.searchParams.get("visitorId"), 100);
  const conversationId = clip(url.searchParams.get("conversationId"), 40);
  if (!visitorId) {
    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
  }

  const user = await currentUser();
  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
    user?.id ? [{ userId: user.id }] : [],
  );

  // Poll a specific conversation when named (scoped to the visitor/user), else
  // the most recent open thread for back-compat.
  let convo = conversationId
    ? await db.chatConversation.findFirst({
        where: { id: conversationId, OR: ownedBy },
        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
      })
    : await db.chatConversation.findFirst({
        where: { visitorId, status: "OPEN" },
        orderBy: { lastMessageAt: "desc" },
        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
      });

  if (!convo) {
    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
  }

  // If the bot is waiting on a live agent, let the poll drive the handoff window:
  // post the "no agents available" fallback once it elapses, then refresh so the
  // visitor sees it on this same poll rather than the next one.
  if (convo.botEscalatedAt) {
    try {
      const { checkEscalationTimeout } = await import("@/lib/kb-run");
      await checkEscalationTimeout(convo.id);
      const refreshed = await db.chatConversation.findFirst({
        where: { id: convo.id },
        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
      });
      if (refreshed) convo = refreshed;
    } catch {
      /* non-essential */
    }
  }

  // Reading the thread clears the visitor-facing unread flag.
  if (convo.unreadForUser) {
    await db.chatConversation
      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
      .catch(() => {});
  }

  // The whole support transcript, plus the name/email the visitor gave. The
  // `?visitorId=` in the URL is the ONLY thing scoping it, which makes the URL
  // itself the secret — precisely the shape a shared cache must never store.
  //
  // `typing.agent` tells the widget whether a support agent is composing a reply
  // right now; it self-expires, so a stale poll can only ever under-report.
  // `botStep` is the AI agent's current live "thinking" step (e.g. "Checking
  // your billing…"), sourced from lib/chat-bot-step.ts; it self-expires too, so
  // a stalled/crashed model call can never leave a stuck label on screen.
  return NextResponse.json(
    { ...serialize(convo), typing: { agent: readTyping(convo.id).agent }, botStep: readBotStep(convo.id) },
    { headers: NO_STORE_HEADERS },
  );
}
