import { realUser, currentUser } from "@/lib/auth";
import { isStaff } from "@/lib/rbac";
import { isAllowedImageMime } from "@/lib/chat-attachment";

export const runtime = "nodejs";

/**
 * GET /api/chat/attachment/[id]?visitorId=…  — stream a chat image ONLY to an
 * authorized viewer:
 *   • any staff member (SUPPORT / ADMIN), OR
 *   • the visitor who owns the conversation (visitorId query param matches), OR
 *   • the signed-in customer the conversation is linked to (userId matches).
 *
 * `id` is a database id, never a filename, so there is no path traversal. The
 * response is locked down: the real stored MIME (always an allow-listed image),
 * `nosniff`, an inline disposition with a fixed filename, and a `default-src
 * 'none'` CSP so it can never execute as a document even if a browser is coaxed
 * into treating it as one.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

export async function GET(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  if (typeof id !== "string" || !id) return new Response("Not found", { status: 404 });

  const attachment = await db.chatAttachment.findUnique({
    where: { id },
    include: { message: { include: { conversation: true } } },
  });
  if (!attachment) return new Response("Not found", { status: 404 });

  const convo = attachment.message.conversation;

  // --- Authorization: same model as upload (participant or staff) ---
  let authorized = false;

  const staff = await realUser();
  if (staff && isStaff(staff.role)) {
    authorized = true;
  } else {
    const url = new URL(req.url);
    const visitorId = clip(url.searchParams.get("visitorId"), 100);
    if (visitorId && visitorId === convo.visitorId) {
      authorized = true;
    } else if (convo.userId) {
      const user = await currentUser();
      if (user && user.id === convo.userId) authorized = true;
    }
  }

  if (!authorized) return new Response("Forbidden", { status: 403 });

  // Defense in depth: never serve anything that isn't an allow-listed image.
  const mime = isAllowedImageMime(attachment.mime) ? attachment.mime : "application/octet-stream";

  const data: Buffer = Buffer.isBuffer(attachment.data)
    ? attachment.data
    : Buffer.from(attachment.data as Uint8Array);

  return new Response(new Uint8Array(data), {
    status: 200,
    headers: {
      "Content-Type": mime,
      "Content-Length": String(data.length),
      "Content-Disposition": 'inline; filename="image"',
      "X-Content-Type-Options": "nosniff",
      "Content-Security-Policy": "default-src 'none'; sandbox",
      "Cache-Control": "private, max-age=86400, no-transform",
    },
  });
}
import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { validateImageBytes, MAX_ATTACHMENT_BYTES } from "@/lib/chat-attachment";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
import { mirrorChatMessageToDiscord } from "@/lib/discord-bridge";

export const runtime = "nodejs";

/**
 * Image upload for <ChatWidget/>.
 *
 * POST /api/chat/upload  (multipart/form-data: visitorId, file, optional body,
 * optional name/email) — attaches an image to the visitor's OPEN conversation
 * (created if none), exactly like POST /api/chat but carrying an image.
 *
 * Authorization mirrors POST /api/chat: the conversation is scoped strictly by
 * the client-supplied `visitorId`, so a visitor can only ever attach to their
 * own thread. The image is validated by signature (not the client-declared
 * type) in lib/chat-attachment — SVG and non-images are rejected. Bytes live in
 * Postgres. Per-IP rate limited.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

export async function POST(req: Request) {
  const rl = checkRateLimit(`chat-upload:${trustedClientIp(req)}`, { max: 15, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "Too many uploads. Please slow down." },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "Invalid upload." }, { status: 400 });
  }

  const visitorId = clip(form.get("visitorId"), 100);
  const body = clip(form.get("body"), 5000) ?? "";
  const name = clip(form.get("name"), 120);
  const email = clip(form.get("email"), 200);
  const conversationId = clip(form.get("conversationId"), 40);
  const file = form.get("file");

  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
  if (!(file instanceof File)) return NextResponse.json({ error: "No image provided." }, { status: 400 });
  // Cheap guard before buffering the whole body into memory.
  if (file.size > MAX_ATTACHMENT_BYTES) {
    return NextResponse.json({ error: "Image is larger than 5 MB." }, { status: 413 });
  }

  const bytes = Buffer.from(await file.arrayBuffer());
  const check = validateImageBytes(bytes, file.type);
  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });

  const user = await currentUser();
  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
    user?.id ? [{ userId: user.id }] : [],
  );

  // Continue the named conversation (if owned), else start a new one — mirrors
  // POST /api/chat.
  let convo = conversationId
    ? await db.chatConversation.findFirst({
        where: { id: conversationId, OR: ownedBy },
        select: { id: true, name: true, email: true },
      })
    : null;

  if (!convo) {
    // Anonymous visitors must identify before starting (mirrors POST /api/chat).
    if (!user) {
      const nm = name ?? null;
      const em = email ?? null;
      if (!nm || !em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) {
        return NextResponse.json(
          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
          { status: 400 },
        );
      }
    }
    convo = await db.chatConversation.create({
      data: {
        visitorId,
        userId: user?.id ?? null,
        name: name ?? user?.name ?? null,
        email: email ?? user?.email ?? null,
      },
      select: { id: true, name: true, email: true },
    });
  }

  const convoId = convo.id;
  await db.$transaction(async (tx) => {
    const msg = await tx.chatMessage.create({
      data: { conversationId: convoId, sender: "visitor", body },
    });
    await tx.chatAttachment.create({
      data: {
        messageId: msg.id,
        mime: check.mime,
        sizeBytes: check.bytes.length,
        data: new Uint8Array(check.bytes),
      },
    });
    await tx.chatConversation.update({
      where: { id: convoId },
      data: {
        status: "OPEN",
        unreadForAgent: true,
        lastMessageAt: new Date(),
        ...(user?.id ? { userId: user.id } : {}),
        ...(name && !convo!.name ? { name } : {}),
        ...(email && !convo!.email ? { email } : {}),
      },
    });
  });

  // Discord bridge (Phase 1 mirror): best-effort, never blocks the upload —
  // no image bytes are forwarded (see lib/discord-bridge.ts), just a
  // placeholder plus any caption.
  await mirrorChatMessageToDiscord(convoId, body ? `📎 ${body}` : "📎 (image attachment — view in the chat widget/admin)", "visitor");

  // Let the assistant look at the image (Claude vision) and reply, before we
  // return — so the bot's answer rides back on this response. Best-effort.
  try {
    const { runAssistant } = await import("@/lib/kb-run");
    await runAssistant({
      conversationId: convoId,
      visitorId,
      currentBody: body,
      images: [{ mediaType: check.mime, dataB64: Buffer.from(check.bytes).toString("base64") }],
    });
  } catch {
    /* assistant is non-essential */
  }

  const full = await db.chatConversation.findUnique({
    where: { id: convoId },
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });

  return NextResponse.json(
    {
      conversation: full
        ? { id: full.id, status: full.status, name: full.name, email: full.email }
        : null,
      messages: (full?.messages ?? []).map((m) => ({
        id: m.id,
        sender: m.sender,
        body: m.body,
        createdAt: m.createdAt.toISOString(),
        attachment: m.attachment
          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
          : null,
      })),
    },
    { headers: NO_STORE_HEADERS },
  );
}
/**
 * Security core for live-chat image attachments.
 *
 * Everything the upload paths (customer widget route + admin server action) and
 * the serving route agree on lives here: the allow-list, the size cap, and —
 * critically — the magic-number sniffer that validates the *real bytes* rather
 * than trusting the client-declared Content-Type. SVG is intentionally absent
 * from the allow-list AND has no binary signature, so it is rejected twice over
 * (SVG can carry <script> and would enable stored XSS if ever served).
 */

/** The only image types we accept. `image/svg+xml` is deliberately excluded. */
export const ALLOWED_IMAGE_MIME = [
  "image/png",
  "image/jpeg",
  "image/gif",
  "image/webp",
] as const;

export type AllowedImageMime = (typeof ALLOWED_IMAGE_MIME)[number];

/** Hard cap: 5 MB. Enforced server-side regardless of any client check. */
export const MAX_ATTACHMENT_BYTES = 5 * 1024 * 1024;

/** `accept` attribute value shared by the file inputs. */
export const ACCEPT_ATTR = ALLOWED_IMAGE_MIME.join(",");

export function isAllowedImageMime(mime: string): mime is AllowedImageMime {
  return (ALLOWED_IMAGE_MIME as readonly string[]).includes(mime);
}

/**
 * Detect the true image type from the leading bytes (file signature). Returns
 * the canonical MIME for a recognised, allowed image, or `null` for anything
 * else — including SVG, HTML, scripts, or a JPEG renamed to .png. Callers must
 * treat `null` as "reject".
 */
export function sniffImageMime(buf: Uint8Array): AllowedImageMime | null {
  if (buf.length < 12) return null;
  const b = buf;

  // PNG: 89 50 4E 47 0D 0A 1A 0A
  if (
    b[0] === 0x89 &&
    b[1] === 0x50 &&
    b[2] === 0x4e &&
    b[3] === 0x47 &&
    b[4] === 0x0d &&
    b[5] === 0x0a &&
    b[6] === 0x1a &&
    b[7] === 0x0a
  ) {
    return "image/png";
  }

  // JPEG: FF D8 FF
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) {
    return "image/jpeg";
  }

  // GIF: "GIF87a" / "GIF89a" — check "GIF8"
  if (b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x38) {
    return "image/gif";
  }

  // WEBP: "RIFF" .... "WEBP"
  if (
    b[0] === 0x52 &&
    b[1] === 0x49 &&
    b[2] === 0x46 &&
    b[3] === 0x46 &&
    b[8] === 0x57 &&
    b[9] === 0x45 &&
    b[10] === 0x42 &&
    b[11] === 0x50
  ) {
    return "image/webp";
  }

  return null;
}

export type AttachmentValidation =
  | { ok: true; mime: AllowedImageMime; bytes: Buffer }
  | { ok: false; error: string };

/**
 * Full server-side validation of an uploaded image. Enforces, in order:
 *  1. non-empty,
 *  2. size ≤ 5 MB,
 *  3. declared MIME (if provided) is in the allow-list and is not SVG,
 *  4. the real bytes match an allowed signature AND agree with the declared
 *     type — the authoritative check; the stored MIME is the *sniffed* one.
 */
export function validateImageBytes(
  bytes: Buffer | Uint8Array,
  declaredMime?: string | null
): AttachmentValidation {
  const buf = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes);

  if (buf.length === 0) return { ok: false, error: "Empty file." };
  if (buf.length > MAX_ATTACHMENT_BYTES) {
    return { ok: false, error: "Image is larger than 5 MB." };
  }

  const declared = (declaredMime ?? "").split(";")[0]?.trim().toLowerCase() || null;
  if (declared) {
    if (declared === "image/svg+xml") {
      return { ok: false, error: "SVG images are not allowed." };
    }
    if (!isAllowedImageMime(declared)) {
      return { ok: false, error: "Unsupported image type." };
    }
  }

  const sniffed = sniffImageMime(buf);
  if (!sniffed) {
    return { ok: false, error: "File is not a supported image (PNG, JPEG, GIF, or WEBP)." };
  }
  if (declared && declared !== sniffed) {
    return { ok: false, error: "Image contents do not match its declared type." };
  }

  return { ok: true, mime: sniffed, bytes: buf };
}

