/** Sender label to go with the avatar above — "Nxeon Assistant" for the AI,
 *  "Nxeon Support" for a real staff reply. */
function senderName(role: "bot" | "agent"): string {
  return role === "bot" ? "Nxeon Assistant" : "Nxeon Support";
}

/** Three-dot "typing…" pulse. Uses Tailwind's built-in `animate-pulse` with
 *  staggered delays so it reads as a wave without any new global keyframes. */
function TypingDots() {
  return (
    <span className="flex items-center gap-1">
      {[0, 150, 300].map((delay) => (
        <span
          key={delay}
          className="h-1.5 w-1.5 motion-safe:animate-pulse rounded-full bg-brand-300"
          style={{ animationDelay: `${delay}ms`, animationDuration: "1s" }}
        />
      ))}
    </span>
  );
}

