# Nxeon primary domain — nxeon.cloud (added during the revsports.ca → nxeon.cloud migration).
# Additive to the generated `nxeon` vhost so the cutover is reversible. The admin
# ops portal stays on its existing secret subdomain until its DNS is moved.

# HTTP -> HTTPS (ACME challenge still served)
server {
    listen 80;
    listen [::]:80;
    server_name nxeon.cloud www.nxeon.cloud;
    location /.well-known/acme-challenge/ { root /var/www/certbot; }
    location / { return 301 https://$host$request_uri; }
}

# Customer portal — https://nxeon.cloud
server {
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    server_name nxeon.cloud www.nxeon.cloud;
    ssl_certificate /etc/letsencrypt/live/nxeon.cloud/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/nxeon.cloud/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    # Matches app/api/files/[serverId]/route.ts's own MAX_UPLOAD_BYTES (250MB) +
    # a small margin for multipart overhead. Was 20m — nginx silently rejected
    # (413, never reaching the app) any file manager upload over 20MB that the
    # app itself would have accepted, with no error surfaced to the customer
    # since the request never got past this layer. Found live 2026-09-06 via a
    # customer support ticket (large Minecraft mod JARs failing to upload with
    # no error message); raised to 250MB (owner's explicit choice) rather than
    # just matching the app's then-current 100MB, and the app's own limit was
    # raised to match.
    client_max_body_size 260m;
    # Separate from proxy_read_timeout/proxy_send_timeout below (which only
    # govern the nginx<->app leg) — this governs nginx<->CLIENT, and defaults
    # to nginx's built-in 60s if unset. A large File Manager upload (e.g. a
    # 130MB mod JAR) can easily take longer than 60s to arrive from an
    # ordinary home connection, so nginx was silently resetting the
    # connection mid-transfer before the body ever fully arrived — the actual
    # remaining cause of "Uploading... then disappears, no error" even after
    # the client_max_body_size fix above. Matches the existing 600s already
    # used for the nginx<->app leg on this same customer-facing location.
    client_body_timeout 600s;
    # See $nx_blocked_ua's own comment in conf.d/nxeon-security.conf. Site-wide
    # (this scraper hits every path, not one route), so it sits before every
    # location -- a plain if...return at server level, not inside a location
    # block, which is the standard, safe use of nginx's if.
    if ($nx_blocked_ua) { return 403; }
    error_page 502 503 504 /maintenance.html;
    location = /maintenance.html {
        root /opt/nxeon/public;
        internal;
    }
    location /admin { return 404; }
    location ~ ^/(login|register|forgot-password|reset-password)$ {
        limit_req zone=nxeon_auth burst=15 nodelay;
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
    location ~ ^/mods/games/ {
        # See nxeon_mods_games's own comment in conf.d/nxeon-security.conf.
        # 429, not the zone's default 503 — this server block's error_page
        # rule turns any 503 into the site-wide maintenance page, which is
        # right for a real outage but wrong for "one IP is over its limit":
        # a scraper (or a real visitor who trips this) should see "slow
        # down", not "the whole site is down".
        limit_req zone=nxeon_mods_games burst=10 nodelay;
        limit_req_status 429;
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
    location /console-ws {
        proxy_pass http://127.0.0.1:8899/console;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_read_timeout 3600s;
    }
    location /terminal-ws {
        proxy_pass http://127.0.0.1:8901;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;
        proxy_set_header Host $host;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
        proxy_buffering off;
    }
    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        # Several Server Actions do real SSH/provisioning work and can
        # legitimately run well past nginx's 60s default (free-mc create:
        # up to 180s for plugin-heavy presets). Without this, nginx gives up
        # on the upstream, serves maintenance.html via the error_page 502/
        # 503/504 rule below, and the browser's RSC client can't parse that
        # HTML as the expected Server Action response — "Something went
        # wrong" even though the backend was often still finishing.
        # Confirmed live 2026-09-02.
        proxy_read_timeout 600s;
        proxy_send_timeout 600s;
    }
}
