/**
 * The whole "who is this Discord reply attributed to" decision, as a pure
 * function of the linked-user lookup — kept separate from the DB call itself
 * so it's trivially unit-testable (see test/discord-reply-attribution.test.ts)
 * without needing a live database.
 *
 * `linkedUser` is the result of `User.findUnique({ where: { discordUserId } })`
 * (or `null` if there's no `discordUserId` to look up at all — e.g. the
 * interaction payload had no resolvable Discord user id). Rejects — rather
 * than falling back to anyone — when there's no link OR the linked account no
 * longer has support access (e.g. demoted after linking). See this file's
 * top-of-file comment for why no fallback exists.
 */
export function resolveDiscordReplyActor(
  linkedUser: { id: string; role: Role } | null,
): { actorId: string } | { error: string } {
  if (!linkedUser) return { error: NOT_LINKED_MSG };
  if (!canAccess(linkedUser.role, "support")) return { error: NOT_LINKED_MSG };
  return { actorId: linkedUser.id };
}

/**
 * @param discordUserId The REAL Discord user id of whoever submitted the
 *   reply modal (from `extractInteractionUserId` on the verified interaction
 *   payload — see app/api/webhooks/discord/route.ts). `null` if it couldn't
 *   be extracted, which resolves the same as "not linked".
 */
export async function submitDiscordReply(
  kind: BridgeKind,
  id: string,
  replyText: string,
  discordUserId: string | null,
): Promise<string> {
  const text = replyText.trim();
  if (!text) return "⚠️ Empty reply — nothing sent.";

  try {
    const linkedUser = discordUserId
      ? await db.user.findUnique({ where: { discordUserId } as any, select: { id: true, role: true } })
      : null;
    const resolved = resolveDiscordReplyActor(linkedUser);
    if ("error" in resolved) {
      console.error("[discord-bridge] reply rejected — no linked staff account", { kind, id, discordUserId });
      return resolved.error;
    }
    const replyAsUserId = resolved.actorId;

    if (kind === "ticket") {
      const result = await writeTicketReply({
        actorId: replyAsUserId,
        actorIsSupportStaff: true,
        ticketId: id,
        body: text,
      });
      if (result.error) return `⚠️ ${result.error}`;
      return "✅ Reply sent to the customer.";
    }

    const result = await writeChatReply({ conversationId: id, body: text, staffId: replyAsUserId });
    if (result.error) return `⚠️ ${result.error}`;
    return "✅ Reply sent to the customer.";
  } catch (e) {
    console.error("[discord-bridge] submitDiscordReply failed", kind, id, e);
    return "⚠️ Something went wrong sending that reply — check the admin panel.";
  }
}
import "server-only";
import { db } from "@/lib/db";
import { getSetting, getSettingInt } from "@/lib/settings";
import { kbAnswer } from "@/lib/kb";
import { getPlanCards, type PlanCard } from "@/lib/kb-plans";
import { resolveActionCard, type AccountActionCard } from "@/lib/kb-tools";
import type { LlmImage } from "@/lib/kb-llm";
import type { ClaudeMessage } from "@/lib/anthropic";
import { sendMail, mailConfigured, layout, button } from "@/lib/mailer";
import { mirrorChatMessageToDiscord } from "@/lib/discord-bridge";

/**
 * Assistant orchestrator shared by POST /api/chat and /api/chat/upload.
 *
 * Owns the "should the bot speak, and how" policy so both entry points behave
 * identically: enablement + human-present gating, the per-conversation and
 * daily guardrails, the Claude answer, and the live-agent HANDOFF flow —
 * escalate → email an agent → open a window → if no agent joins in time, post
 * the "no agents available" fallback (checkEscalationTimeout, also called from
 * the GET poll so it fires even when the visitor sends nothing more).
 *
 * Everything here is best-effort: a throw must never break the visitor's message.
 */

const APP_URL = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
const ADMIN_CHAT_URL = `${APP_URL}/admin/chat`;

const WAIT_MSG =
  "Let me get a teammate for you — one moment while I see who's available. 👋";
const NO_AGENT_MSG =
  "Sorry — none of our team are free to jump in this second. I'm happy to keep helping you right here, or I can have someone personally reach out (usually within one business day). If you'd like a callback, just drop your email and a note and I'll pass it along.";

function esc(s: string): string {
  return s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c] as string);
}

function firstName(name: string | null): string | null {
  const n = (name ?? "").trim();
  if (!n) return null;
  return n.split(/\s+/)[0].slice(0, 40);
}

/** Extract a hidden `[[cards: key1, key2]]` directive from a bot reply, returning
 *  the visible body (directive stripped) and the card keys. */
function parseCardDirective(reply: string): { body: string; keys: string[] } {
  const m = reply.match(/\[\[\s*cards?\s*:\s*([^\]]+)\]\]/i);
  if (!m) return { body: reply, keys: [] };
  const keys = m[1]
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  const body = reply.replace(m[0], "").replace(/\n{3,}/g, "\n\n").trim();
  return { body, keys };
}

/** One parsed (not-yet-resolved) `[[action: type=…, id=…, label="…"]]` spec. */
type ActionSpec = { kind: string; id: string; label?: string };

/** Extract every hidden `[[action: ...]]` directive from a bot reply — the
 *  account-action-card sibling of `[[cards: ...]]` (see lib/kb-tools.ts's
 *  resolveActionCard for what these become). Attribute order doesn't matter;
 *  unrecognized attributes are ignored. Directives are stripped from the
 *  visible body regardless of whether they end up resolving to a real card. */
function parseActionDirectives(reply: string): { body: string; specs: ActionSpec[] } {
  const specs: ActionSpec[] = [];
  const re = /\[\[\s*action\s*:\s*([^\]]+)\]\]/gi;
  const body = reply
    .replace(re, (_full, attrsRaw: string) => {
      const attrs: Record<string, string> = {};
      // key=value pairs, comma-separated; value optionally double-quoted.
      const attrRe = /(\w+)\s*=\s*(?:"([^"]*)"|([^,]+))/g;
      let am: RegExpExecArray | null;
      while ((am = attrRe.exec(attrsRaw)) !== null) {
        attrs[am[1].toLowerCase()] = (am[2] ?? am[3] ?? "").trim();
      }
      if (attrs.type && attrs.id) {
        specs.push({ kind: attrs.type.toLowerCase(), id: attrs.id, label: attrs.label });
      }
      return "";
    })
    .replace(/\n{3,}/g, "\n\n")
    .trim();
  return { body, specs };
}

type ChatCard = (PlanCard & { type: "plan" }) | AccountActionCard;

function toHistory(rows: { sender: string; body: string }[]): ClaudeMessage[] {
  return rows
    .filter((m) => m.body && m.body.trim())
    .map((m) => ({
      role: (m.sender === "visitor" ? "user" : "assistant") as "user" | "assistant",
      content: m.body,
    }));
}

type ConvoLite = {
  id: string;
  visitorId: string;
  name: string | null;
  email: string | null;
};

/** Atomically move the conversation into the "waiting for a live agent" state,
 *  post the holding message, and email an agent. No-op if already escalated. */
async function escalate(convo: ConvoLite, lastBody: string): Promise<void> {
  const claim = await db.chatConversation.updateMany({
    where: { id: convo.id, botEscalatedAt: null },
    data: { botEscalatedAt: new Date(), unreadForAgent: true },
  });
  if (claim.count !== 1) return; // someone/something already escalated

  await db.chatMessage.create({
    data: { conversationId: convo.id, sender: "bot", body: WAIT_MSG },
  });
  await mirrorChatMessageToDiscord(convo.id, WAIT_MSG, "bot");

  // Email an available agent (best-effort). They have the window to jump in.
  try {
    if (await mailConfigured()) {
      const to = (await getSetting("kb_bot_agent_email", "")) || (await getSetting("support_email", ""));
      if (to) {
        const who = convo.name
          ? `${convo.name}${convo.email ? ` (${convo.email})` : ""}`
          : convo.email || "A website visitor";
        const html = layout(
          "A visitor wants to talk to a human",
          `<p><strong>${esc(who)}</strong> is asking for a live agent in the website chat.</p>
           <p style="color:#64748b">Latest message: “${esc(lastBody.slice(0, 300))}”</p>
           <p>Hop in within the next few minutes to take over — after that they'll be offered a callback instead.</p>
           ${button(ADMIN_CHAT_URL, "Open the live chat inbox")}`,
        );
        await sendMail({
          to,
          subject: "🔔 Live chat — a visitor wants a human",
          html,
          replyTo: convo.email || undefined,
        });
      }
    }
  } catch {
    /* email is best-effort; the conversation is already flagged in the inbox */
  }
}

/**
 * If a conversation is waiting on a human and the window has elapsed with no
 * agent, post the "no agents available" fallback and clear the waiting state.
 * Atomic (updateMany claim) so concurrent polls can't double-post. Safe to call
 * on every message and every GET poll.
 */
export async function checkEscalationTimeout(conversationId: string): Promise<void> {
  try {
    const convo = await db.chatConversation.findUnique({
      where: { id: conversationId },
      select: { id: true, botEscalatedAt: true, assignedToId: true },
    });
    if (!convo?.botEscalatedAt) return;

    // An agent joined (assigned or replied) — drop the waiting state, no fallback.
    const agentReplies = await db.chatMessage.count({
      where: { conversationId, sender: "agent" },
    });
    if (agentReplies > 0 || convo.assignedToId) {
      await db.chatConversation.updateMany({
        where: { id: conversationId, botEscalatedAt: { not: null } },
        data: { botEscalatedAt: null },
      });
      return;
    }

    const windowSec = await getSettingInt("kb_bot_window_sec", 180);
    const threshold = new Date(Date.now() - windowSec * 1000);
    // Claim the timeout: only one caller wins, and only once the window passed.
    const claim = await db.chatConversation.updateMany({
      where: { id: conversationId, botEscalatedAt: { not: null, lte: threshold }, assignedToId: null },
      data: { botEscalatedAt: null },
    });
    if (claim.count !== 1) return;

    await db.chatMessage.create({
      data: { conversationId, sender: "bot", body: NO_AGENT_MSG },
    });
    await mirrorChatMessageToDiscord(conversationId, NO_AGENT_MSG, "bot");
  } catch {
    /* non-essential */
  }
}

/**
 * Evaluate the assistant for a just-received visitor message. Creates a bot
 * reply (or runs the handoff flow) when appropriate. `images` are the base64
 * blocks for an image the visitor just sent (upload path), if any.
 */
export async function runAssistant(args: {
  conversationId: string;
  visitorId: string;
  currentBody: string;
  images?: LlmImage[];
}): Promise<void> {
  try {
    if ((await getSetting("kb_bot_enabled", "false")) !== "true") return;

    const convo = await db.chatConversation.findUnique({
      where: { id: args.conversationId },
      select: {
        id: true,
        visitorId: true,
        userId: true,
        name: true,
        email: true,
        assignedToId: true,
        botEscalatedAt: true,
        aiPaused: true,
        messages: { orderBy: { createdAt: "asc" }, select: { sender: true, body: true } },
      },
    });
    if (!convo) return;

    // Staff paused the AI for this thread (admin inbox toggle) — stay silent,
    // exactly like the "a human already engaged" case below. The visitor's
    // message is already saved and flagged unreadForAgent by the caller
    // (POST /api/chat / the upload route), so nothing else to do here.
    if (convo.aiPaused) return;

    // Never talk over a human: silent once an agent replied or was assigned.
    const agentReplied = convo.messages.some((m) => m.sender === "agent");
    if (agentReplied || convo.assignedToId) return;

    // Already waiting on a live agent — stay quiet; just check the timeout.
    if (convo.botEscalatedAt) {
      await checkEscalationTimeout(convo.id);
      return;
    }

    // Guardrail: per-conversation reply cap → escalate instead of looping.
    const botCount = convo.messages.filter((m) => m.sender === "bot").length;
    const maxReplies = await getSettingInt("kb_bot_max_replies", 16);
    if (maxReplies > 0 && botCount >= maxReplies) {
      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
      return;
    }

    // Guardrail: platform-wide daily reply cap (soft cost ceiling). Over it, we
    // still answer — just from the token-free retrieval path (no paid call).
    let overDaily = false;
    const dailyCap = await getSettingInt("kb_bot_daily_cap", 1000);
    if (dailyCap > 0) {
      const since = new Date();
      since.setHours(0, 0, 0, 0);
      const used = await db.kbBotLog.count({
        where: { createdAt: { gte: since }, kind: { in: ["answer", "offer"] } },
      });
      overDaily = used >= dailyCap;
    }

    const history = toHistory(convo.messages.slice(0, -1));
    const result = await kbAnswer(args.currentBody, {
      history,
      images: args.images,
      visitorName: firstName(convo.name),
      userId: convo.userId,
      noLlm: overDaily,
      conversationId: convo.id,
    });

    // A live agent is ONLY brought in when the visitor explicitly asks for one
    // (humanIntent → kind "handoff"). The bot never offers or escalates on its own.
    if (result.kind === "handoff") {
      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
      return;
    }

    if (result.reply) {
      // Resolve any plan cards to render with this reply: the LLM signals them
      // with a hidden [[cards: key1, key2]] directive; the retrieval fallback
      // supplies result.cardKeys. Cards are looked up from the real catalog, so
      // the model can only ever pick keys — prices/features are never invented.
      const parsedCards = parseCardDirective(result.reply);
      // Account-action cards are the same mechanism's sibling: [[action: ...]]
      // directives, resolved against THIS customer's own data (never invented —
      // see resolveActionCard's ownership checks). Parsed from whatever text
      // parseCardDirective left behind, so both directives can coexist.
      const parsedActions = parseActionDirectives(parsedCards.body);
      const keys = [...(result.cardKeys ?? []), ...parsedCards.keys];
      const planCards: ChatCard[] = keys.length
        ? (await getPlanCards(keys)).map((c) => ({ ...c, type: "plan" as const }))
        : [];
      const actionCards = (
        await Promise.all(
          parsedActions.specs
            .slice(0, 3) // never render a wall of cards
            .map((spec) => resolveActionCard(convo.userId, spec.kind, spec.id, spec.label)),
        )
      ).filter((c): c is AccountActionCard => c !== null);
      const cards: ChatCard[] = [...planCards, ...actionCards];
      await db.chatMessage.create({
        data: {
          conversationId: convo.id,
          sender: "bot",
          body: parsedActions.body,
          cardsJson: cards.length ? JSON.stringify(cards) : null,
        },
      });
      await mirrorChatMessageToDiscord(convo.id, parsedActions.body, "bot");
    }
    // Log coverage. A HARD model failure (bad/unfunded key, API outage) is logged
    // as "llm_error" — distinct from an expected "degraded"/over-cap — so the
    // admin KB dashboard shows the bot is broken instead of it failing silently.
    await db.kbBotLog
      .create({
        data: {
          visitorId: args.visitorId,
          conversationId: convo.id,
          question: args.currentBody.slice(0, 500),
          kind: result.llmFailure === "error" ? "llm_error" : result.kind,
          matchedTitle: result.matchedTitle ?? null,
        },
      })
      .catch(() => {});
  } catch {
    /* assistant is non-essential — never fail the visitor's message on it */
  }
}

