"use client";

import { useEffect, useState } from "react";
import { createPortal } from "react-dom";

/**
 * A chat/ticket image that opens full-screen in place on click, instead of a
 * new browser tab — used by ticket messages (MessageAttachment), the
 * customer live-chat widget (ChatWidget) and the admin chat inbox
 * (ChatInbox), so all three surfaces share one lightbox behavior rather than
 * three slightly different `target="_blank"` links.
 */
export function LightboxImage({
  src,
  alt,
  className,
  wrapperClassName = "",
}: {
  src: string;
  alt: string;
  className?: string;
  /** Extra classes (spacing, etc.) for the clickable wrapper around the thumbnail. */
  wrapperClassName?: string;
}) {
  const [open, setOpen] = useState(false);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open]);

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen(true)}
        className={`block cursor-zoom-in ${wrapperClassName}`}
        aria-label={`View ${alt} full size`}
      >
        {/* eslint-disable-next-line @next/next/no-img-element -- authorization-checked API routes, not optimizable assets. */}
        <img src={src} alt={alt} className={className} />
      </button>

      {/* Portaled to <body>: a `position: fixed` element is positioned
          relative to the nearest ancestor with a transform/filter/
          backdrop-filter, not the viewport, if one exists between here and
          the root — and the glass ticket card this renders inside sets
          backdrop-filter for its blur. Without the portal the "full-screen"
          lightbox was really only full-screen *within that card*. */}
      {open && typeof document !== "undefined" && createPortal(
        <div
          role="dialog"
          aria-modal="true"
          aria-label={alt}
          onClick={() => setOpen(false)}
          className="fixed inset-0 z-[200] flex items-center justify-center bg-black/85 p-6 backdrop-blur-sm motion-safe:animate-fade-up"
"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { listCannedReplies, type CannedReplyItem } from "@/lib/actions-canned-replies";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";

/**
 * Quick-replies snippet picker, shared between the ticket reply form
 * (components/admin/TicketControls.tsx) and the live-chat reply box
 * (components/admin/ChatInbox.tsx).
 *
 * v2 (2026-09-12): the library grew past what a flat `<select>` can browse —
 * a search box (title + body) plus service-type and game filters, all
 * client-side over the one `listCannedReplies()` fetch (the whole library is
 * a few hundred short rows at most; a search-as-you-type action round-trip
 * would just be slower). The list loads once per mount; already gated
 * requireAnyGrant(["supportTickets","liveChat"]) in
 * lib/actions-canned-replies.ts, so this renders nothing for a caller who
 * somehow reaches it without either grant — the action call simply throws
 * and the catch below leaves the picker empty rather than crashing the
 * reply box around it.
 */
export function CannedReplyPicker({
  onInsert,
  disabled,
}: {
  onInsert: (body: string) => void;
  disabled?: boolean;
}) {
  const [replies, setReplies] = useState<CannedReplyItem[]>([]);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("");
  const [game, setGame] = useState("");
  const rootRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    let alive = true;
    listCannedReplies()
      .then((rows) => alive && setReplies(rows))
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, []);

  // Click-outside + Escape to close, same pattern as the other dropdown
  // popovers in this codebase (no shared primitive for it yet).
  useEffect(() => {
    if (!open) return;
    function onDocClick(e: MouseEvent) {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) setOpen(false);
    }
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") setOpen(false);
    }
    document.addEventListener("mousedown", onDocClick);
    document.addEventListener("keydown", onKey);
