 *
 * Two DIFFERENT message shapes exist on purpose:
 *   - `StaffChatMessage`  — what staff surfaces receive (admin inbox, dock).
 *     Carries `internal` notes and the authoring staff member's full name.
 *   - `CustomerChatMessage` — what the customer widget receives. Has NO
 *     `internal` field at all and NO author id; internal notes are filtered out
 *     before this shape is ever built (lib/chat/visibility.ts). Keeping the
 *     customer type structurally unable to carry staff-only data is the point.
 *
 * Pure module: no server-only imports, safe for client components and tests.
 */

export type ChatSender = "visitor" | "agent" | "bot";

export type ChatAttachmentMeta = {
  id: string;
  mime: string;
  sizeBytes: number;
  width: number | null;
  height: number | null;
};

/** A structured card riding on a message (`ChatMessage.cardsJson`). Rendered by
 *  `type` through components/chat/cards/registry.tsx. Unknown types render a
 *  safe placeholder, never raw JSON. */
export type ChatCard = { type?: string; key?: string; [k: string]: unknown };

export type CustomerChatMessage = {
  id: string;
  sender: ChatSender;
  body: string;
  createdAt: string;
  cards: ChatCard[] | null;
  attachment: ChatAttachmentMeta | null;
  /** First name of the human agent for `sender: "agent"`, else null. */
  agentName: string | null;
  clientId: string | null;
};

export type StaffChatMessage = {
  id: string;
  conversationId: string;
  sender: ChatSender;
  body: string;
  createdAt: string;
  cards: ChatCard[] | null;
  attachment: ChatAttachmentMeta | null;
  internal: boolean;
  authorId: string | null;
  authorName: string | null;
  clientId: string | null;
};

export type InboxTab = "unassigned" | "mine" | "waiting" | "all" | "snoozed" | "closed";

