export type HubEvent =
  | { kind: "message"; conversationId: string; message: StaffChatMessage }
  | { kind: "convo"; conversation: InboxRow }
  | { kind: "typing"; conversationId: string; who: "visitor" | "agent"; name: string | null; active: boolean }
  | { kind: "read"; conversationId: string; who: "visitor" | "agent"; at: string }
  | { kind: "botStep"; conversationId: string; step: string | null }
  | { kind: "viewing"; conversationId: string; staffId: string; name: string; on: boolean }
  | { kind: "visitorPresence"; conversationId: string; online: boolean }
  | { kind: "agentsOnline"; count: number };

export type SeqEvent = HubEvent & { seq: number };

