import type {
  ChatAttachmentMeta,
  ChatCard,
  ChatSender,
  CustomerChatMessage,
  StaffChatMessage,
} from "./types";

/**
 * The ONE place that decides what a customer may see of a chat message.
 *
 * Rules (each one is asserted in test/livechat-visibility.test.ts):
 *   1. An `internal` note is never customer-visible — not its body, not its
 *      existence, not its attachment.
 *   2. The customer shape never carries `internal`, `authorId`, or the staff
 *      member's full name — only the agent's FIRST name (what a support agent
 *      would introduce themselves as anyway).
 *   3. Cards are passed through as parsed JSON; rendering is by `type` through
 *      a registry that falls back to a neutral placeholder.
 *
 * Pure: no DB, no server-only imports — used by API routes, the SSE hub
 * filter, and tests alike.
 */

/** The Prisma `where` fragment every customer-facing message query must AND in. */
export const CUSTOMER_VISIBLE_WHERE = { internal: false } as const;

/** Columns to select for a message — deliberately excludes attachment bytes. */
export const MESSAGE_SELECT = {
  id: true,
  conversationId: true,
  sender: true,
  body: true,
  cardsJson: true,
  createdAt: true,
  internal: true,
  authorId: true,
  clientId: true,
  attachment: {
    select: { id: true, mime: true, sizeBytes: true, width: true, height: true },
  },
} as const;

export type MessageRow = {
  id: string;
  conversationId: string;
  sender: string;
  body: string;
  cardsJson: string | null;
  createdAt: Date;
  internal: boolean;
  authorId: string | null;
  clientId: string | null;
  attachment: { id: string; mime: string; sizeBytes: number; width: number | null; height: number | null } | null;
};

export function isCustomerVisible(m: { internal?: boolean | null }): boolean {
  return m.internal !== true;
}

function normSender(s: string): ChatSender {
  return s === "agent" || s === "bot" ? s : "visitor";
}

export function parseCards(json: string | null | undefined): ChatCard[] | null {
  if (!json) return null;
  try {
    const v = JSON.parse(json);
    if (!Array.isArray(v)) return null;
    const cards = v.filter((c): c is ChatCard => !!c && typeof c === "object" && !Array.isArray(c));
    return cards.length ? cards : null;
  } catch {
    return null;
  }
}

function attachmentMeta(a: MessageRow["attachment"]): ChatAttachmentMeta | null {
  return a ? { id: a.id, mime: a.mime, sizeBytes: a.sizeBytes, width: a.width ?? null, height: a.height ?? null } : null;
}

export function firstName(name: string | null | undefined): string | null {
  const n = (name ?? "").trim();
  if (!n) return null;
  return n.split(/\s+/)[0].slice(0, 40);
}

export function toStaffMessage(m: MessageRow, staffNames: Map<string, string>, fallbackAuthorId?: string | null): StaffChatMessage {
  const authorId = m.authorId ?? (m.sender === "agent" ? fallbackAuthorId ?? null : null);
  return {
    id: m.id,
    conversationId: m.conversationId,
    sender: normSender(m.sender),
    body: m.body,
    createdAt: m.createdAt.toISOString(),
    cards: parseCards(m.cardsJson),
    attachment: attachmentMeta(m.attachment),
    internal: m.internal === true,
    authorId,
    authorName: authorId ? staffNames.get(authorId) ?? null : null,
    clientId: m.clientId ?? null,
  };
}

/**
 * Staff → customer projection. Returns null for anything the customer must not
 * see, so callers can `.flatMap`/filter without re-implementing the rule.
 */
export function toCustomerMessage(
  m: Pick<StaffChatMessage, "id" | "sender" | "body" | "createdAt" | "cards" | "attachment" | "internal" | "authorName" | "clientId">,
): CustomerChatMessage | null {
  if (!isCustomerVisible(m)) return null;
  return {
    id: m.id,
    sender: m.sender,
    body: m.body,
    createdAt: m.createdAt,
    cards: m.cards,
    attachment: m.attachment,
    agentName: m.sender === "agent" ? firstName(m.authorName) : null,
    // A visitor's own clientId lets their tab reconcile its optimistic bubble.
    // Staff clientIds are meaningless to the customer, so they're dropped.
    clientId: m.sender === "visitor" ? m.clientId : null,
  };
}

/** One-line list preview for a message (never called for internal notes). */
export function previewOf(body: string, hasAttachment: boolean, cards?: ChatCard[] | null): string {
  const b = (body ?? "").replace(/\s+/g, " ").trim();
  if (b) return b.slice(0, 140);
  if (hasAttachment) return "📎 Image";
  if (cards && cards.length) {
    const t = cards[0]?.type;
    return t === "offer" ? "📦 Offer" : "🗂 Card";
  }
  return "";
}

/** Customer-supplied idempotency key: short, opaque, url-safe. */
export function cleanClientId(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim();
  return /^[A-Za-z0-9_-]{6,64}$/.test(s) ? s : null;
}

