import type { HubEvent, SeqEvent } from "./types";

/**
 * In-process live-chat pub/sub (live-chat overhaul, 2026-10).
 *
 * WHY IN-PROCESS: every code path that writes a chat message runs inside the
 * single `nxeon-web` Node process (API routes, server actions, the Discord
 * webhook route, the AI assistant in lib/kb-run.ts) — nxeon-worker never
 * touches chat. So a write can publish straight to the SSE streams that are
 * open in the same process: zero DB polling, sub-millisecond fan-out.
 *
 * SAFETY NET: lib/chat/sweep.ts runs ONE cheap indexed query every 15 s
 * (only while at least one stream is open) and republishes any message this
 * hub did not see — covering a future second process or a write path that
 * forgets to publish. Clients also backfill from the DB on every (re)connect,
 * so a dropped event can never become a lost message, only a late one.
 *
 * STORED ON globalThis, ALWAYS (not just in dev): Next bundles route handlers
 * and server actions into different module graphs, so a plain module-level
 * singleton can exist more than once in one process. One global = one hub.
 *
 * Pure (no server-only import) so it is unit-testable.
 */

type Listener = (e: SeqEvent) => void;

type Viewing = { staffId: string; name: string; at: number };

type HubState = {
  seq: number;
  listeners: Set<Listener>;
  /** conversationId -> number of open customer streams on it. */
  visitorConns: Map<string, number>;
  /** staffId -> number of open staff streams. */
  staffConns: Map<string, number>;
  /** conversationId -> staffId -> who is looking at it right now. */
  viewing: Map<string, Map<string, Viewing>>;
  /** Message ids published recently (for the sweep's de-duplication). */
  recent: Map<string, number>;
};

const g = globalThis as unknown as { __nxeonChatHub?: HubState };
const state: HubState =
  g.__nxeonChatHub ??
  (g.__nxeonChatHub = {
    seq: 0,
    listeners: new Set(),
    visitorConns: new Map(),
    staffConns: new Map(),
    viewing: new Map(),
    recent: new Map(),
  });

export const VIEWING_TTL_MS = 45_000;
const RECENT_TTL_MS = 5 * 60_000;

export function publish(e: HubEvent): SeqEvent {
  const ev = { ...e, seq: ++state.seq } as SeqEvent;
  if (e.kind === "message") rememberPublished(e.message.id);
  for (const l of state.listeners) {
    try {
      l(ev);
    } catch {
      /* one broken stream must never stop delivery to the others */
    }
  }
  return ev;
}

export function subscribe(l: Listener): () => void {
  state.listeners.add(l);
  return () => {
    state.listeners.delete(l);
  };
}

export function listenerCount(): number {
  return state.listeners.size;
}

export function rememberPublished(id: string, now = Date.now()): void {
  state.recent.set(id, now);
  if (state.recent.size > 2000) {
    for (const [k, t] of state.recent) if (now - t > RECENT_TTL_MS) state.recent.delete(k);
  }
}

export function wasPublished(id: string): boolean {
  return state.recent.has(id);
}

/* ---------------- presence ---------------- */

export function visitorConnected(conversationId: string): () => void {
  const n = (state.visitorConns.get(conversationId) ?? 0) + 1;
  state.visitorConns.set(conversationId, n);
  if (n === 1) publish({ kind: "visitorPresence", conversationId, online: true });
  let done = false;
  return () => {
    if (done) return;
    done = true;
    const left = (state.visitorConns.get(conversationId) ?? 1) - 1;
    if (left <= 0) {
      state.visitorConns.delete(conversationId);
      publish({ kind: "visitorPresence", conversationId, online: false });
    } else state.visitorConns.set(conversationId, left);
