/**
 * Client-side message reconciliation, shared by the customer widget and every
 * staff chat surface. Pure + unit-tested (test/livechat-merge.test.ts).
 *
 * Guarantees, whatever order events/responses arrive in:
 *   - NO DUPLICATES: one entry per server id; an optimistic local bubble is
 *     replaced (not joined) by the server row carrying the same clientId.
 *   - ORDERING: confirmed messages sort by (createdAt, id) — the server clock,
 *     never the browser clock; still-pending local bubbles stay after them, in
 *     the order they were typed.
 *   - Failed sends stay visible (with a retry affordance) until retried or
 *     discarded — a network blip never silently eats a message.
 */

export type LocalState = "sending" | "failed";

export type Mergeable = {
  id: string;
  createdAt: string;
  clientId?: string | null;
  /** Present only on optimistic local entries that the server hasn't confirmed. */
  local?: LocalState;
};

function cmp(a: Mergeable, b: Mergeable): number {
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
}

export function mergeMessages<T extends Mergeable>(existing: readonly T[], incoming: readonly T[]): T[] {
  const byId = new Map<string, T>();
  const pending: T[] = [];
  const confirmedClientIds = new Set<string>();

  for (const m of incoming) {
    if (m.local) continue; // incoming is always server data
    byId.set(m.id, m);
    if (m.clientId) confirmedClientIds.add(m.clientId);
  }
  for (const m of existing) {
    if (m.local) {
      if (m.clientId && confirmedClientIds.has(m.clientId)) continue; // server echo arrived
      pending.push(m);
      continue;
    }
    if (m.clientId && confirmedClientIds.has(m.clientId) && !byId.has(m.id)) continue;
    if (!byId.has(m.id)) byId.set(m.id, m);
  }
  // A confirmed row that matches an existing confirmed row by clientId (e.g. an
  // idempotent retry answered with the original row) collapses to one entry.
  const seenClient = new Set<string>();
  const confirmed = [...byId.values()].sort(cmp).filter((m) => {
    if (!m.clientId) return true;
    if (seenClient.has(m.clientId)) return false;
    seenClient.add(m.clientId);
    return true;
  });
  return [...confirmed, ...pending];
}

/** The newest CONFIRMED message — the backfill cursor after a reconnect. */
export function lastConfirmed<T extends Mergeable>(list: readonly T[]): T | null {
  for (let i = list.length - 1; i >= 0; i--) if (!list[i].local) return list[i];
  return null;
}

/** Mark one optimistic entry failed / sending again. */
export function setLocalState<T extends Mergeable>(list: readonly T[], clientId: string, state: LocalState): T[] {
  return list.map((m) => (m.local && m.clientId === clientId ? { ...m, local: state } : m));
}

export function dropLocal<T extends Mergeable>(list: readonly T[], clientId: string): T[] {
  return list.filter((m) => !(m.local && m.clientId === clientId));
}

/** A fresh idempotency key for an optimistic send. */
export function newClientId(): string {
  const r =
    typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
      ? crypto.randomUUID().replace(/-/g, "")
      : Math.random().toString(36).slice(2) + Date.now().toString(36);
  return `c${r.slice(0, 30)}`;
}

/** Apply canned-reply variables. Unknown `{tokens}` are left untouched. */
export function applyCannedVars(
  body: string,
  vars: { name?: string | null; email?: string | null; agent?: string | null },
): string {
  const full = (vars.name ?? "").trim();
  const first = full.split(/\s+/)[0] ?? "";
  const agentFull = (vars.agent ?? "").trim();
  const agentFirst = agentFull.split(/\s+/)[0] ?? "";
  const map: Record<string, string> = {
    name: full || "there",
    first_name: first || "there",
    firstname: first || "there",
    email: (vars.email ?? "").trim(),
    agent: agentFirst || "the Nxeon team",
    agent_name: agentFull || "the Nxeon team",
  };
  return body.replace(/\{\s*([a-z_]+)\s*\}/gi, (whole, k: string) => {
    const v = map[k.toLowerCase()];
    return v === undefined ? whole : v;
  });
}

