/**
 * Server-Sent Events plumbing for the live-chat streams.
 *
 * Deployment facts this is built around (see /root/agent-notes/livechat/DIAGNOSIS.md):
 *   - nginx proxies with `proxy_buffering on` (default). `X-Accel-Buffering: no`
 *     turns buffering off for THIS response only — no nginx change needed.
 *   - nginx `proxy_read_timeout 600s` would cut an idle stream; a comment
 *     heartbeat every 20 s keeps it (and any intermediate proxy) alive.
 *   - Next's built-in gzip (the `compression` middleware) buffers output, which
 *     would hold events back; it skips any response whose Cache-Control has
 *     `no-transform`, so we send that.
 *   - The browser's EventSource reconnects on its own; `retry:` tells it to wait
 *     2 s. Clients also re-sync from the DB on every (re)connect.
 */

export const SSE_HEADERS: Record<string, string> = {
  "Content-Type": "text/event-stream; charset=utf-8",
  "Cache-Control": "private, no-cache, no-store, no-transform",
  Connection: "keep-alive",
  "X-Accel-Buffering": "no",
};

const HEARTBEAT_MS = 20_000;
/** Close and let the client reconnect after this long — bounds any leak and
 *  re-runs auth periodically (a revoked session stops receiving within 10 min). */
const MAX_STREAM_MS = 10 * 60_000;

export type SseSend = (event: string, data: unknown, id?: string | number) => void;

export function sseStream(
  req: Request,
  start: (send: SseSend, close: () => void) => (() => void) | void,
): Response {
  const enc = new TextEncoder();
  let cleanup: (() => void) | void;
  let closed = false;
  let heartbeat: ReturnType<typeof setInterval> | undefined;
  let lifetime: ReturnType<typeof setTimeout> | undefined;

  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      const write = (s: string) => {
        if (closed) return;
        try {
          controller.enqueue(enc.encode(s));
        } catch {
          close();
        }
      };
      const send: SseSend = (event, data, id) => {
        let s = "";
        if (id !== undefined) s += `id: ${id}\n`;
        s += `event: ${event}\n`;
        s += `data: ${JSON.stringify(data)}\n\n`;
        write(s);
      };
      const close = () => {
        if (closed) return;
        closed = true;
        if (heartbeat) clearInterval(heartbeat);
        if (lifetime) clearTimeout(lifetime);
        try {
          cleanup?.();
        } catch {
          /* ignore */
        }
        try {
          controller.close();
        } catch {
          /* already closed */
        }
      };
      write("retry: 2000\n\n");
      heartbeat = setInterval(() => write(`: ping ${Date.now()}\n\n`), HEARTBEAT_MS);
      lifetime = setTimeout(close, MAX_STREAM_MS);
      req.signal.addEventListener("abort", close);
      cleanup = start(send, close);
    },
    cancel() {
      closed = true;
      if (heartbeat) clearInterval(heartbeat);
      if (lifetime) clearTimeout(lifetime);
      try {
        cleanup?.();
      } catch {
        /* ignore */
      }
    },
  });

  return new Response(stream, { status: 200, headers: SSE_HEADERS });
}

