import "server-only";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { loadCreatorUserIds } from "@/lib/creator-accounts-data";
import { publish } from "./hub";
import {
  CUSTOMER_VISIBLE_WHERE,
  MESSAGE_SELECT,
  previewOf,
  toCustomerMessage,
  toStaffMessage,
  type MessageRow,
} from "./visibility";
import type {
  ChatCard,
  ChatPriority,
  CustomerChatMessage,
  InboxCounts,
  InboxRow,
  InboxTab,
  StaffChatMessage,
} from "./types";

/**
 * Live-chat data core (live-chat overhaul, 2026-10). Every chat read/write that
 * the routes, server actions, the Discord bridge and the AI assistant perform
 * goes through here, so the three invariants live in exactly one file:
 *
 *   1. Never select attachment BYTES unless serving the attachment itself.
 *   2. Internal notes never leave through a customer-facing function
 *      (`pageCustomerMessages` ANDs CUSTOMER_VISIBLE_WHERE; the stream filter
 *      uses toCustomerMessage, which returns null for them).
 *   3. Every write publishes to the in-process hub (lib/chat/hub.ts) so open
 *      streams update immediately.
 *
 * NO AUTHORIZATION HAPPENS HERE (same discipline as lib/reply-core.ts): every
 * caller authenticates first — customer routes scope by visitorId/userId,
 * staff routes call requireGrant("liveChat") (lib/chat/staff-auth.ts).
 */

export const PAGE_SIZE = 40;

/* ------------------------------------------------------------------ */
/* lookups                                                             */
/* ------------------------------------------------------------------ */

export async function staffNameMap(ids: (string | null | undefined)[]): Promise<Map<string, string>> {
  const unique = [...new Set(ids.filter((v): v is string => !!v))];
  if (!unique.length) return new Map();
  const rows = await db.user.findMany({ where: { id: { in: unique } }, select: { id: true, name: true } });
  return new Map(rows.map((u) => [u.id, u.name]));
}

const CONVO_SELECT = {
  id: true,
  visitorId: true,
  userId: true,
  name: true,
  email: true,
  status: true,
  assignedToId: true,
  unreadForAgent: true,
  lastMessageAt: true,
  createdAt: true,
  lastSender: true,
  lastPreview: true,
  pinned: true,
  priority: true,
  snoozedUntil: true,
  aiPaused: true,
  botEscalatedAt: true,
  userLastReadAt: true,
  agentLastReadAt: true,
} as const;

type ConvoRow = Prisma.ChatConversationGetPayload<{ select: typeof CONVO_SELECT }>;

function normPriority(p: string | null | undefined): ChatPriority {
  return p === "HIGH" || p === "URGENT" ? p : "NORMAL";
}

async function toInboxRows(rows: ConvoRow[]): Promise<InboxRow[]> {
  if (!rows.length) return [];
  // Rows written before the overhaul have no denormalised preview yet — one
  // DISTINCT ON query (index: conversationId, createdAt) fills just those.
  const missing = rows.filter((r) => r.lastPreview === null && r.lastSender === null).map((r) => r.id);
  const fallback = new Map<string, { sender: string; preview: string }>();
  if (missing.length) {
    const lasts = await db.$queryRaw<{ conversationId: string; sender: string; body: string; hasAtt: boolean }[]>`
      SELECT DISTINCT ON (m."conversationId") m."conversationId", m.sender, m.body,
             (a.id IS NOT NULL) AS "hasAtt"
        FROM "ChatMessage" m
        LEFT JOIN "ChatAttachment" a ON a."messageId" = m.id
       WHERE m."conversationId" IN (${Prisma.join(missing)}) AND m.internal = false
       ORDER BY m."conversationId", m."createdAt" DESC, m.id DESC`;
    for (const l of lasts) fallback.set(l.conversationId, { sender: l.sender, preview: previewOf(l.body, l.hasAtt) });
  }
  const [names, creators] = await Promise.all([
    staffNameMap(rows.map((r) => r.assignedToId)),
    loadCreatorUserIds(rows.map((r) => r.userId)),
  ]);
  return rows.map((r) => {
    const fb = fallback.get(r.id);
    return {
      id: r.id,
      visitorId: r.visitorId,
      userId: r.userId,
      name: r.name,
      email: r.email,
      status: r.status,
      assignedToId: r.assignedToId,
      assignedToName: r.assignedToId ? names.get(r.assignedToId) ?? null : null,
      unreadForAgent: r.unreadForAgent,
      lastMessageAt: r.lastMessageAt.toISOString(),
      createdAt: r.createdAt.toISOString(),
      lastSender: r.lastSender ?? fb?.sender ?? null,
      lastPreview: r.lastPreview ?? fb?.preview ?? null,
      pinned: r.pinned,
      priority: normPriority(r.priority),
      snoozedUntil: r.snoozedUntil ? r.snoozedUntil.toISOString() : null,
      aiPaused: r.aiPaused,
      botEscalatedAt: r.botEscalatedAt ? r.botEscalatedAt.toISOString() : null,
      userLastReadAt: r.userLastReadAt ? r.userLastReadAt.toISOString() : null,
      agentLastReadAt: r.agentLastReadAt ? r.agentLastReadAt.toISOString() : null,
      isCreator: !!r.userId && creators.has(r.userId),
    };
  });
}

export async function inboxRow(id: string): Promise<InboxRow | null> {
  const r = await db.chatConversation.findUnique({ where: { id }, select: CONVO_SELECT });
  if (!r) return null;
  return (await toInboxRows([r]))[0] ?? null;
}

/* ------------------------------------------------------------------ */
/* inbox list                                                          */
/* ------------------------------------------------------------------ */

/** Prisma filter for one inbox tab. Pure apart from `now`. Exported for tests. */
export function tabWhere(tab: InboxTab, staffId: string, now: Date): Prisma.ChatConversationWhereInput {
  const awake: Prisma.ChatConversationWhereInput = {
    status: "OPEN",
    OR: [{ snoozedUntil: null }, { snoozedUntil: { lte: now } }],
  };
  switch (tab) {
    case "unassigned":
      return { AND: [awake, { assignedToId: null }] };
    case "mine":
      return { AND: [awake, { assignedToId: staffId }] };
    case "waiting":
      // Last customer-visible message is the visitor's — they're waiting on us.
      // Pre-overhaul rows (lastSender null) fall back to the unread flag.
      return {
        AND: [awake, { OR: [{ lastSender: "visitor" }, { lastSender: null, unreadForAgent: true }] }],
      };
    case "snoozed":
      return { status: "OPEN", snoozedUntil: { gt: now } };
    case "closed":
      return { status: "CLOSED" };
    case "all":
    default:
      return {};
  }
}

export function searchWhere(q: string): Prisma.ChatConversationWhereInput | null {
  const s = q.trim().slice(0, 100);
  if (!s) return null;
  const c = { contains: s, mode: "insensitive" as const };
  return {
    OR: [
      { name: c },
      { email: c },
      { visitorId: { startsWith: s } },
      { id: s },
      { messages: { some: { body: c } } },
    ],
  };
}

export async function listInbox(args: {
  tab: InboxTab;
  staffId: string;
  q?: string;
  priorityOnly?: boolean;
  offset?: number;
  limit?: number;
  /** While impersonating: only this customer's conversations, ever. */
  scopeUserId?: string | null;
}): Promise<{ rows: InboxRow[]; hasMore: boolean; counts: InboxCounts }> {
  const now = new Date();
  const limit = Math.min(Math.max(args.limit ?? 50, 1), 100);
  const offset = Math.max(args.offset ?? 0, 0);
  const scope: Prisma.ChatConversationWhereInput = args.scopeUserId ? { userId: args.scopeUserId } : {};
  const search = args.q ? searchWhere(args.q) : null;
  const and: Prisma.ChatConversationWhereInput[] = [scope, tabWhere(args.tab, args.staffId, now)];
  if (search) and.push(search);
  if (args.priorityOnly) and.push({ priority: { in: ["HIGH", "URGENT"] } });

  const tabs: InboxTab[] = ["unassigned", "mine", "waiting", "all", "snoozed", "closed"];
  const [rows, ...counts] = await Promise.all([
    db.chatConversation.findMany({
      where: { AND: and },
      orderBy: [{ pinned: "desc" }, { unreadForAgent: "desc" }, { lastMessageAt: "desc" }, { id: "desc" }],
      skip: offset,
      take: limit + 1,
      select: CONVO_SELECT,
    }),
    ...tabs.map((t) => db.chatConversation.count({ where: { AND: [scope, tabWhere(t, args.staffId, now)] } })),
  ]);
  const list = rows as ConvoRow[];
  const hasMore = list.length > limit;
  const page = hasMore ? list.slice(0, limit) : list;
  const c = Object.fromEntries(tabs.map((t, i) => [t, counts[i] as number])) as InboxCounts;
  return { rows: await toInboxRows(page), hasMore, counts: c };
}

/* ------------------------------------------------------------------ */
/* message paging                                                      */
/* ------------------------------------------------------------------ */

async function cursorOf(conversationId: string, id: string | null | undefined) {
  if (!id) return null;
  return db.chatMessage.findFirst({ where: { id, conversationId }, select: { id: true, createdAt: true } });
}

async function pageRows(args: {
  conversationId: string;
  before?: string | null;
  after?: string | null;
  limit?: number;
  customer: boolean;
}): Promise<{ rows: MessageRow[]; hasMore: boolean }> {
  const limit = Math.min(Math.max(args.limit ?? PAGE_SIZE, 1), 100);
  const vis = args.customer ? CUSTOMER_VISIBLE_WHERE : {};
  if (args.after) {
    const c = await cursorOf(args.conversationId, args.after);
    if (c) {
      const rows = (await db.chatMessage.findMany({
        where: {
          conversationId: args.conversationId,
          ...vis,
          OR: [{ createdAt: { gt: c.createdAt } }, { createdAt: c.createdAt, id: { gt: c.id } }],
        },
        orderBy: [{ createdAt: "asc" }, { id: "asc" }],
        take: 201,
        select: MESSAGE_SELECT,
      })) as MessageRow[];
      // >200 missed while offline: tell the client to reload the latest page.
      return { rows: rows.slice(0, 200), hasMore: rows.length > 200 };
    }
    // Unknown cursor (deleted/foreign id) → fall through to "latest page".
  }
  const c = await cursorOf(args.conversationId, args.before);
  const rows = (await db.chatMessage.findMany({
    where: {
      conversationId: args.conversationId,
      ...vis,
      ...(c ? { OR: [{ createdAt: { lt: c.createdAt } }, { createdAt: c.createdAt, id: { lt: c.id } }] } : {}),
    },
    orderBy: [{ createdAt: "desc" }, { id: "desc" }],
    take: limit + 1,
    select: MESSAGE_SELECT,
  })) as MessageRow[];
  const hasMore = rows.length > limit;
  return { rows: (hasMore ? rows.slice(0, limit) : rows).reverse(), hasMore };
}

export async function pageStaffMessages(args: {
  conversationId: string;
  before?: string | null;
  after?: string | null;
  limit?: number;
  fallbackAuthorId?: string | null;
}): Promise<{ messages: StaffChatMessage[]; hasMore: boolean }> {
  const { rows, hasMore } = await pageRows({ ...args, customer: false });
  const names = await staffNameMap([...rows.map((r) => r.authorId), args.fallbackAuthorId]);
  return { messages: rows.map((r) => toStaffMessage(r, names, args.fallbackAuthorId)), hasMore };
}

export async function pageCustomerMessages(args: {
  conversationId: string;
  before?: string | null;
  after?: string | null;
  limit?: number;
  fallbackAuthorId?: string | null;
}): Promise<{ messages: CustomerChatMessage[]; hasMore: boolean }> {
  const { rows, hasMore } = await pageRows({ ...args, customer: true });
  const names = await staffNameMap([...rows.map((r) => r.authorId), args.fallbackAuthorId]);
  const messages = rows
    .map((r) => toCustomerMessage(toStaffMessage(r, names, args.fallbackAuthorId)))
    .filter((m): m is CustomerChatMessage => m !== null);
  return { messages, hasMore };
}

/* ------------------------------------------------------------------ */
/* publishing                                                          */
/* ------------------------------------------------------------------ */

export async function loadStaffMessage(id: string): Promise<StaffChatMessage | null> {
  const r = (await db.chatMessage.findUnique({
    where: { id },
    select: { ...MESSAGE_SELECT, conversation: { select: { assignedToId: true } } },
  })) as (MessageRow & { conversation: { assignedToId: string | null } }) | null;
  if (!r) return null;
  const names = await staffNameMap([r.authorId, r.conversation.assignedToId]);
  return toStaffMessage(r, names, r.conversation.assignedToId);
}

/** Push a stored message (and the conversation's new list row) to every open stream. */
export async function publishMessage(messageId: string): Promise<StaffChatMessage | null> {
  try {
    const m = await loadStaffMessage(messageId);
    if (!m) return null;
    publish({ kind: "message", conversationId: m.conversationId, message: m });
    await publishConvo(m.conversationId);
    return m;
  } catch (e) {
    console.error("[chat] publishMessage failed (clients will backfill)", messageId, e);
    return null;
  }
}

export async function publishConvo(conversationId: string): Promise<void> {
  try {
    const row = await inboxRow(conversationId);
    if (row) publish({ kind: "convo", conversation: row });
  } catch (e) {
    console.error("[chat] publishConvo failed", conversationId, e);
  }
}

/* ------------------------------------------------------------------ */
/* writes                                                              */
/* ------------------------------------------------------------------ */

export type ImageInput = { mime: string; bytes: Buffer };

function isUniqueViolation(e: unknown): boolean {
  return e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002";
}

async function existingByClientId(conversationId: string, clientId: string | null | undefined) {
  if (!clientId) return null;
  return db.chatMessage.findUnique({
    where: { conversationId_clientId: { conversationId, clientId } },
    select: { id: true },
  });
}

/**
 * Persist a visitor message (text and/or image). Idempotent on clientId: a
 * retried send returns the original row, `duplicate: true`, and writes nothing.
 * The caller has ALREADY verified the visitor owns `conversationId`.
 */
export async function writeVisitorMessage(args: {
  conversationId: string;
  body: string;
  clientId?: string | null;
  image?: ImageInput | null;
  identity?: { userId?: string | null; name?: string | null; email?: string | null };
}): Promise<{ id: string; duplicate: boolean }> {
  const prior = await existingByClientId(args.conversationId, args.clientId);
  if (prior) return { id: prior.id, duplicate: true };
  const now = new Date();
  try {
    const id = await db.$transaction(async (tx) => {
      const convo = await tx.chatConversation.findUnique({
        where: { id: args.conversationId },
        select: { name: true, email: true },
      });
      const msg = await tx.chatMessage.create({
        data: {
          conversationId: args.conversationId,
          sender: "visitor",
          body: args.body,
          clientId: args.clientId ?? null,
        },
        select: { id: true },
      });
      if (args.image) {
        await tx.chatAttachment.create({
          data: {
            messageId: msg.id,
            mime: args.image.mime,
            sizeBytes: args.image.bytes.length,
            data: new Uint8Array(args.image.bytes),
          },
        });
      }
      const idn = args.identity ?? {};
      await tx.chatConversation.update({
        where: { id: args.conversationId },
        data: {
          status: "OPEN",
          closedAt: null,
          snoozedUntil: null, // a visitor writing again always wakes a snoozed thread
          unreadForAgent: true,
          lastMessageAt: now,
          lastSender: "visitor",
          lastPreview: previewOf(args.body, !!args.image),
          // The visitor is obviously looking at the thread they just wrote in.
          userLastReadAt: now,
          ...(idn.userId ? { userId: idn.userId } : {}),
          ...(idn.name && !convo?.name ? { name: idn.name } : {}),
          ...(idn.email && !convo?.email ? { email: idn.email } : {}),
        },
      });
      return msg.id;
    });
    return { id, duplicate: false };
  } catch (e) {
    if (isUniqueViolation(e)) {
      const again = await existingByClientId(args.conversationId, args.clientId);
      if (again) return { id: again.id, duplicate: true };
    }
    throw e;
  }
}

/**
 * Persist a staff message: a customer-visible reply, or (`internal: true`) a
 * staff-only note. `staffId` is ALWAYS the real acting staff member — callers
 * resolve it with requireGrant()/realUser(), never currentUser(), so a reply
 * typed while impersonating is still the admin's (the 2026-09-25 ticket-reply
 * misattribution class).
 *
 * `cards` is the integration seam for structured messages (e.g. the custom
 * Offers feature posts `[{ type: "offer", offerId }]`); rendering is by type
 * through components/chat/cards/registry.tsx.
 */
export async function writeStaffMessage(args: {
  conversationId: string;
  staffId: string;
  body: string;
  internal?: boolean;
  clientId?: string | null;
  image?: ImageInput | null;
  cards?: ChatCard[] | null;
}): Promise<{ id: string; duplicate: boolean; conversationUserId: string | null } | { error: string }> {
  const body = (args.body ?? "").trim();
  if (body.length > 5000) return { error: "Message must be 5000 characters or fewer." };
  if (!body && !args.image && !(args.cards && args.cards.length)) return { error: "Message cannot be empty." };
  const convo = await db.chatConversation.findUnique({
    where: { id: args.conversationId },
    select: { id: true, userId: true, assignedToId: true },
  });
  if (!convo) return { error: "Conversation not found." };
  const prior = await existingByClientId(args.conversationId, args.clientId);
  if (prior) return { id: prior.id, duplicate: true, conversationUserId: convo.userId };

  const internal = args.internal === true;
  const now = new Date();
  let id: string;
  try {
    id = await db.$transaction(async (tx) => {
      const msg = await tx.chatMessage.create({
        data: {
          conversationId: args.conversationId,
          sender: "agent",
          body,
          internal,
          authorId: args.staffId,
          clientId: args.clientId ?? null,
          cardsJson: args.cards && args.cards.length ? JSON.stringify(args.cards) : null,
        },
        select: { id: true },
      });
      if (args.image) {
        await tx.chatAttachment.create({
          data: {
            messageId: msg.id,
            mime: args.image.mime,
            sizeBytes: args.image.bytes.length,
            data: new Uint8Array(args.image.bytes),
          },
        });
      }
      if (internal) {
        // A note changes nothing the customer can observe: no reopen, no unread
        // flag, no list preview, no lastMessageAt bump (their history list is
        // ordered by it). Writing one does mean staff have read the thread.
        await tx.chatConversation.update({
          where: { id: args.conversationId },
          data: { agentLastReadAt: now },
        });
      } else {
        await tx.chatConversation.update({
          where: { id: args.conversationId },
          data: {
            status: "OPEN",
            closedAt: null,
            unreadForUser: true,
            unreadForAgent: false,
            // Claim an unassigned thread; never silently steal a teammate's.
            ...(convo.assignedToId ? {} : { assignedToId: args.staffId }),
            lastMessageAt: now,
            lastSender: "agent",
            lastPreview: previewOf(body, !!args.image, args.cards),
            agentLastReadAt: now,
          },
        });
      }
      return msg.id;
    });
  } catch (e) {
    if (isUniqueViolation(e)) {
      const again = await existingByClientId(args.conversationId, args.clientId);
      if (again) return { id: again.id, duplicate: true, conversationUserId: convo.userId };
    }
    throw e;
  }

  if (!internal && convo.userId) await notifyCustomer(convo.userId);
  return { id, duplicate: false, conversationUserId: convo.userId };
}

/**
 * In-app bell for a signed-in customer. Coalesced: one unread "New reply in your
 * live chat" at a time instead of one per message (a 10-message conversation
 * used to leave 10 identical notifications).
 */
async function notifyCustomer(userId: string): Promise<void> {
  try {
    const title = "New reply in your live chat";
    const existing = await db.notification.findFirst({
      where: { userId, title, readAt: null, createdAt: { gte: new Date(Date.now() - 6 * 3600_000) } },
      select: { id: true },
    });
    if (existing) return;
    await db.notification.create({ data: { userId, title, href: "/dashboard/support?tab=chat" } });
  } catch {
    /* best-effort */
  }
}

/** Bot (AI assistant) message — same denormalisation + publish as the others. */
export async function writeBotMessage(args: {
  conversationId: string;
  body: string;
  cardsJson?: string | null;
}): Promise<string> {
  const now = new Date();
  const id = await db.$transaction(async (tx) => {
    const msg = await tx.chatMessage.create({
      data: { conversationId: args.conversationId, sender: "bot", body: args.body, cardsJson: args.cardsJson ?? null },
      select: { id: true },
    });
    await tx.chatConversation.update({
      where: { id: args.conversationId },
      data: {
        lastMessageAt: now,
        lastSender: "bot",
        lastPreview: previewOf(args.body, false),
        unreadForUser: true,
      },
    });
    return msg.id;
  });
  void publishMessage(id);
  return id;
}

export async function markRead(conversationId: string, who: "visitor" | "agent"): Promise<string> {
  const now = new Date();
  await db.chatConversation.update({
    where: { id: conversationId },
    data: who === "visitor" ? { userLastReadAt: now, unreadForUser: false } : { agentLastReadAt: now, unreadForAgent: false },
  });
  const at = now.toISOString();
  publish({ kind: "read", conversationId, who, at });
  if (who === "agent") void publishConvo(conversationId);
  return at;
}

