import "server-only";

/**
 * Chat image thumbnails. Generated lazily the first time a thumbnail is asked
 * for, then persisted on the ChatAttachment row (thumb/thumbMime/width/height)
 * so it is computed exactly once per image.
 *
 * Uses `sharp`, which ships with Next.js (its image optimizer dependency) and
 * is already present in production's node_modules. It is loaded dynamically
 * and every failure path returns null — the caller then serves the original,
 * which is exactly the pre-overhaul behaviour. A missing/broken sharp can make
 * images slower, never broken.
 *
 * Output is always WEBP (still an allow-listed image type), max 480 px on the
 * long edge, EXIF-rotated, metadata stripped. Animated GIFs keep only their
 * first frame in the thumbnail; the original (opened in the lightbox) is
 * untouched.
 */

export const THUMB_MAX = 480;

type SharpFn = (input: Buffer, opts?: Record<string, unknown>) => {
  rotate: () => ReturnType<SharpFn>;
  resize: (o: Record<string, unknown>) => ReturnType<SharpFn>;
  webp: (o: Record<string, unknown>) => ReturnType<SharpFn>;
  metadata: () => Promise<{ width?: number; height?: number; orientation?: number }>;
  toBuffer: () => Promise<Buffer>;
};

let sharpP: Promise<SharpFn | null> | null = null;
function loadSharp(): Promise<SharpFn | null> {
  if (!sharpP) {
    sharpP = import(/* webpackIgnore: true */ "sharp" as string)
      .then((m: { default?: unknown }) => ((m.default ?? m) as SharpFn) || null)
      .catch((e) => {
        console.warn("[chat] sharp unavailable — serving original images", e?.message ?? e);
        return null;
      });
  }
  return sharpP;
}

export type Thumb = { data: Buffer; mime: "image/webp"; width: number; height: number };

export async function makeThumbnail(bytes: Buffer): Promise<Thumb | null> {
  const sharp = await loadSharp();
  if (!sharp) return null;
  try {
    const meta = await sharp(bytes, { failOn: "none" }).metadata();
    let w = meta.width ?? 0;
    let h = meta.height ?? 0;
    // EXIF orientations 5–8 swap the axes once rotated.
    if (meta.orientation && meta.orientation >= 5) [w, h] = [h, w];
    const data = await sharp(bytes, { failOn: "none", animated: false })
      .rotate()
      .resize({ width: THUMB_MAX, height: THUMB_MAX, fit: "inside", withoutEnlargement: true })
      .webp({ quality: 78 })
      .toBuffer();
    return { data, mime: "image/webp", width: w, height: h };
  } catch (e) {
    console.warn("[chat] thumbnail generation failed — serving original", (e as Error)?.message ?? e);
    return null;
  }
}

