import "server-only";
import type { User } from "@prisma/client";
import { db } from "@/lib/db";
import { impersonating } from "@/lib/auth";
import { requireGrant } from "@/lib/staff-grants";

/**
 * Auth for every STAFF live-chat route (/api/admin/chat/**).
 *
 * Identity is ALWAYS the real signed-in staff member (`requireGrant` →
 * `realUser`), never `currentUser()` — so a reply sent from the chat dock while
 * an admin is impersonating a customer is attributed to the admin and stored
 * as `sender: "agent"`, exactly like a reply from /admin/chat. This is the
 * shape of the 2026-09-25 ticket-reply misattribution fix, applied up front.
 *
 * IMPERSONATION SCOPE: while impersonating, `scopeUserId` is the impersonated
 * customer's id and every staff chat route restricts itself to that
 * customer's own conversations — list, stream, history, context, writes. The
 * dock is the only chat surface rendered inside the customer's portal, and it
 * must never pull a DIFFERENT customer's conversation into that page.
 */

export type ChatStaffCtx = { staff: User; scopeUserId: string | null; impersonatingEmail: string | null };

export class ChatAuthError extends Error {
  constructor(public status: number, message: string) {
    super(message);
  }
}

export async function chatStaffContext(): Promise<ChatStaffCtx> {
  let staff: User;
  try {
    staff = await requireGrant("liveChat");
  } catch (e) {
    const msg = (e as Error)?.message;
    throw new ChatAuthError(msg === "UNAUTHORIZED" ? 401 : 403, msg === "UNAUTHORIZED" ? "Sign in required." : "Forbidden.");
  }
  const imp = await impersonating();
  return { staff, scopeUserId: imp ? imp.target.id : null, impersonatingEmail: imp ? imp.target.email : null };
}

/** Load a conversation the caller may act on, or throw 404 (never 403 — no oracle). */
export async function convoInScope(ctx: ChatStaffCtx, conversationId: string) {
  if (typeof conversationId !== "string" || !conversationId || conversationId.length > 40) {
    throw new ChatAuthError(404, "Conversation not found.");
  }
  const c = await db.chatConversation.findUnique({
    where: { id: conversationId },
    select: { id: true, userId: true, status: true, assignedToId: true, email: true, name: true, discordThreadId: true, aiPaused: true },
  });
  if (!c) throw new ChatAuthError(404, "Conversation not found.");
  if (ctx.scopeUserId && c.userId !== ctx.scopeUserId) throw new ChatAuthError(404, "Conversation not found.");
  return c;
}

/**
 * CSRF backstop for cookie-authenticated state-changing routes. SameSite=lax
 * already keeps the session cookie off cross-site POSTs; this additionally
 * refuses any request whose Origin is present and doesn't match the Host.
 */
export function assertSameOrigin(req: Request): void {
  const origin = req.headers.get("origin");
  if (!origin) return;
  const host = (req.headers.get("x-forwarded-host") ?? req.headers.get("host") ?? "").toLowerCase();
  try {
    if (new URL(origin).host.toLowerCase() !== host) throw new ChatAuthError(403, "Cross-origin request refused.");
  } catch (e) {
    if (e instanceof ChatAuthError) throw e;
    throw new ChatAuthError(403, "Cross-origin request refused.");
  }
}

export function chatErrorResponse(e: unknown): Response {
  if (e instanceof ChatAuthError) {
    return Response.json({ error: e.message }, { status: e.status, headers: { "Cache-Control": "private, no-store" } });
  }
  console.error("[chat] staff route error", e);
  return Response.json({ error: "Something went wrong." }, { status: 500, headers: { "Cache-Control": "private, no-store" } });
}

