import { db } from "@/lib/db";
import { chatStaffContext, chatErrorResponse } from "@/lib/chat/staff-auth";
import { subscribe, staffConnected, agentsOnline, allViewers, onlineVisitorConversationIds } from "@/lib/chat/hub";
import { ensureSweep } from "@/lib/chat/sweep";
import { sseStream } from "@/lib/chat/sse";
import type { SeqEvent } from "@/lib/chat/types";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * GET /api/admin/chat/stream — the staff live-chat event stream (SSE).
 *
 * One stream per admin tab carries EVERYTHING the inbox, open threads and the
 * persistent dock need: new messages (incl. internal notes), list-row updates,
 * typing, read receipts, who-is-viewing, visitor presence. It replaces the old
 * 5-second `listConversations()` server-action poll (≈310 kB + every image's
 * bytes per tick — see /root/agent-notes/livechat/DIAGNOSIS.md).
 *
 * Auth: requireGrant("liveChat") on the REAL account (lib/chat/staff-auth.ts).
 * While impersonating, only the impersonated customer's conversations pass the
 * filter below — the dock inside the customer portal can never receive another
 * customer's chat.
 */
export async function GET(req: Request) {
  let ctx;
  try {
    ctx = await chatStaffContext();
  } catch (e) {
    return chatErrorResponse(e);
  }
  const scope = ctx.scopeUserId;
  const inScope = new Set<string>();
  if (scope) {
    const mine = await db.chatConversation.findMany({ where: { userId: scope }, select: { id: true } });
    for (const c of mine) inScope.add(c.id);
  }
  const staffId = ctx.staff.id;

  return sseStream(req, (send) => {
    const allowed = (conversationId: string) => !scope || inScope.has(conversationId);
    send("hello", {
      me: { id: staffId, name: ctx.staff.name, role: ctx.staff.role },
      scoped: !!scope,
      agentsOnline: agentsOnline() + 1,
      viewers: allViewers().filter((v) => allowed(v.conversationId)),
      visitorsOnline: onlineVisitorConversationIds().filter(allowed),
    });
    const off = subscribe((e: SeqEvent) => {
      switch (e.kind) {
        case "convo":
          if (scope) {
            if (e.conversation.userId !== scope) return;
            inScope.add(e.conversation.id);
          }
          send("convo", e.conversation, e.seq);
          return;
        case "message":
        case "typing":
        case "read":
        case "botStep":
        case "viewing":
        case "visitorPresence":
          if (!allowed(e.conversationId)) return;
          send(e.kind, e, e.seq);
          return;
        case "agentsOnline":
          send("agentsOnline", { count: e.count }, e.seq);
          return;
      }
    });
    const disconnect = staffConnected(staffId);
    ensureSweep();
    return () => {
      off();
      disconnect();
    };
  });
}
EOF
