import "server-only";
import { db } from "@/lib/db";
import { listenerCount, wasPublished, rememberPublished } from "./hub";
import { publishMessage } from "./server";

/**
 * Safety net for the in-process hub: while at least one live-chat stream is
 * open, run ONE indexed query (ChatMessage.createdAt) every 15 s for messages
 * the hub never published, and publish them. Covers a write from another
 * process or a code path that forgot to call publishMessage. Cost is O(1)
 * queries per process regardless of how many clients are connected — never a
 * per-client poll. Stops itself when the last stream closes.
 */

const INTERVAL_MS = 15_000;
const g = globalThis as unknown as { __nxeonChatSweep?: { timer: ReturnType<typeof setInterval> | null; since: Date } };
const st = g.__nxeonChatSweep ?? (g.__nxeonChatSweep = { timer: null, since: new Date() });

async function tick(): Promise<void> {
  if (listenerCount() === 0) {
    if (st.timer) clearInterval(st.timer);
    st.timer = null;
    return;
  }
  const from = new Date(st.since.getTime() - 5_000); // overlap: commit-time skew
  const now = new Date();
  try {
    const rows = await db.chatMessage.findMany({
      where: { createdAt: { gt: from } },
      select: { id: true },
      orderBy: { createdAt: "asc" },
      take: 200,
    });
    for (const r of rows) {
      if (wasPublished(r.id)) continue;
      rememberPublished(r.id);
      await publishMessage(r.id);
    }
    st.since = now;
  } catch {
    /* next tick retries */
  }
}

export function ensureSweep(): void {
  if (st.timer) return;
  st.since = new Date();
  st.timer = setInterval(() => void tick(), INTERVAL_MS);
  // Never keep a process alive just for this.
  (st.timer as unknown as { unref?: () => void }).unref?.();
}
