import { after } from "next/server";
import { chatStaffContext, chatErrorResponse, convoInScope, assertSameOrigin, ChatAuthError } from "@/lib/chat/staff-auth";
import { pageStaffMessages, publishMessage, writeStaffMessage } from "@/lib/chat/server";
import { cleanClientId } from "@/lib/chat/visibility";
import { validateImageBytes, MAX_ATTACHMENT_BYTES } from "@/lib/chat-attachment";
import { checkRateLimit } from "@/lib/rate-limit";
import { mirrorChatMessageToDiscord } from "@/lib/discord-bridge";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * GET  /api/admin/chat/conversations/[id]/messages?before=<id>|after=<id>&limit=
 *      Paginated history: the latest page by default, older pages via `before`
 *      (infinite scroll up), reconnect backfill via `after`.
 * POST same path — send a staff reply or internal note.
 *      JSON `{ body, internal?, clientId? }` or multipart (`file`, `body`,
 *      `internal`, `clientId`) for an image. Idempotent on clientId.
 *
 * The reply is ALWAYS authored by the real staff account (see
 * lib/chat/staff-auth.ts), including from the dock while impersonating.
 */
export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const ctx = await chatStaffContext();
    const { id } = await params;
    const c = await convoInScope(ctx, id);
    const u = new URL(req.url);
    const res = await pageStaffMessages({
      conversationId: id,
      before: u.searchParams.get("before"),
      after: u.searchParams.get("after"),
      limit: Number(u.searchParams.get("limit") ?? 0) || undefined,
      fallbackAuthorId: c.assignedToId,
    });
    return Response.json(res, { headers: NO_STORE_HEADERS });
  } catch (e) {
    return chatErrorResponse(e);
  }
}

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    assertSameOrigin(req);
    const ctx = await chatStaffContext();
    const { id } = await params;
    await convoInScope(ctx, id);

    const rl = checkRateLimit(`chat-staff-send:${ctx.staff.id}`, { max: 90, windowMs: 60_000 });
    if (!rl.ok) throw new ChatAuthError(429, "Too many messages. Please slow down.");

    let body = "";
    let internal = false;
    let clientId: string | null = null;
    let image: { mime: string; bytes: Buffer } | null = null;

    const type = req.headers.get("content-type") ?? "";
    if (type.startsWith("multipart/form-data")) {
      const fd = await req.formData();
      body = typeof fd.get("body") === "string" ? String(fd.get("body")) : "";
      internal = fd.get("internal") === "1" || fd.get("internal") === "true";
      clientId = cleanClientId(fd.get("clientId"));
      const file = fd.get("file");
      if (file instanceof File) {
        if (file.size > MAX_ATTACHMENT_BYTES) throw new ChatAuthError(413, "Image is larger than 5 MB.");
        const check = validateImageBytes(Buffer.from(await file.arrayBuffer()), file.type);
        if (!check.ok) throw new ChatAuthError(400, check.error);
        image = { mime: check.mime, bytes: check.bytes };
      }
    } else {
      const j = (await req.json().catch(() => ({}))) as Record<string, unknown>;
      body = typeof j.body === "string" ? j.body : "";
      internal = j.internal === true;
      clientId = cleanClientId(j.clientId);
    }

    const res = await writeStaffMessage({ conversationId: id, staffId: ctx.staff.id, body, internal, clientId, image });
    if ("error" in res) throw new ChatAuthError(400, res.error);
    const message = await publishMessage(res.id);

    // Discord mirror: customer-visible messages only — a customer can be
    // granted access to their own Discord channel, so an internal note must
    // never be posted there. Runs after the response is sent.
    if (!internal && !res.duplicate) {
      const text = body.trim();
      after(() =>
        mirrorChatMessageToDiscord(
          id,
          image ? (text ? `📎 ${text}` : "📎 (image attachment — view in /admin/chat)") : text,
          "agent",
        ),
      );
    }
    return Response.json({ message, duplicate: res.duplicate }, { headers: NO_STORE_HEADERS });
  } catch (e) {
    return chatErrorResponse(e);
  }
}
