import { after } from "next/server";
import { db } from "@/lib/db";
import { chatStaffContext, chatErrorResponse, convoInScope, assertSameOrigin, ChatAuthError } from "@/lib/chat/staff-auth";
import { markRead, publishConvo, publishMessage, writeStaffMessage, inboxRow } from "@/lib/chat/server";
import { setViewing } from "@/lib/chat/hub";
import { markTyping } from "@/lib/chat-typing";
import { hasAreaAccess } from "@/lib/staff-grants";
import { setDiscordThreadArchived } from "@/lib/discord-bridge";
import { firstName } from "@/lib/chat/visibility";
import { CHAT_PRIORITIES, type ChatPriority } from "@/lib/chat/types";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * POST /api/admin/chat/conversations/[id]/actions  `{ action, ...args }`
 *
 *   assign    { staffId?: string|null }  claim (default: me), transfer to a
 *                                        teammate with liveChat access, or unassign (null)
 *   close | reopen
 *   snooze    { minutes: number }        hide from active tabs until then or the
 *                                        visitor's next message
 *   unsnooze
 *   pin       { on: boolean }
 *   priority  { value: "NORMAL"|"HIGH"|"URGENT" }
 *   ai        { paused: boolean }        per-thread AI assistant kill switch
 *   read                                 read receipt (agent side)
 *   typing                               "agent is typing" (pushed to the visitor)
 *   viewing   { on: boolean }            collision hint for teammates
 *
 * Plain fetch route (not a server action) on purpose: Next serializes server
 * actions per client, so the old inbox's 5 s poll action used to queue every
 * click behind it.
 */
type Body = { action?: string; staffId?: string | null; minutes?: number; on?: boolean; value?: string; paused?: boolean };

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    assertSameOrigin(req);
    const ctx = await chatStaffContext();
    const { id } = await params;
    const convo = await convoInScope(ctx, id);
    const b = ((await req.json().catch(() => ({}))) ?? {}) as Body;
    const me = ctx.staff;

    switch (b.action) {
      case "read": {
        const at = await markRead(id, "agent");
        return ok({ at });
      }
      case "typing": {
        markTyping(id, "agent", Date.now(), firstName(me.name));
        return ok({});
      }
      case "viewing": {
        setViewing(id, me.id, me.name, b.on !== false);
        return ok({});
      }
      case "assign": {
        let target: string | null = me.id;
        if (b.staffId === null) target = null;
        else if (typeof b.staffId === "string" && b.staffId && b.staffId !== me.id) {
          const t = await db.user.findUnique({ where: { id: b.staffId }, select: { id: true, role: true, name: true } });
          if (!t || !(await hasAreaAccess(t, "liveChat"))) throw new ChatAuthError(400, "That teammate can't take live chats.");
          target = t.id;
        }
        await db.chatConversation.update({
          where: { id },
          data: { assignedToId: target, ...(target === me.id ? { unreadForAgent: false, agentLastReadAt: new Date() } : {}) },
        });
        // Transfers leave a staff-only breadcrumb in the thread so the next
        // agent knows who handed it over. Internal: the customer never sees it.
        if (target && target !== me.id && target !== convo.assignedToId) {
          const t = await db.user.findUnique({ where: { id: target }, select: { name: true } });
          const note = await writeStaffMessage({
            conversationId: id,
            staffId: me.id,
            internal: true,
            body: `Transferred this chat to ${t?.name ?? "a teammate"}.`,
          });
          if (!("error" in note)) await publishMessage(note.id);
          await db.notification
            .create({ data: { userId: target, title: `${me.name} transferred a live chat to you`, href: `/admin/chat?c=${id}` } })
            .catch(() => {});
        }
        break;
      }
      case "close": {
        await db.chatConversation.update({
          where: { id },
          data: { status: "CLOSED", closedAt: new Date(), unreadForAgent: false, snoozedUntil: null },
        });
        after(() => setDiscordThreadArchived("chat", convo.discordThreadId, true));
        break;
      }
      case "reopen": {
        await db.chatConversation.update({ where: { id }, data: { status: "OPEN", closedAt: null } });
        after(() => setDiscordThreadArchived("chat", convo.discordThreadId, false));
        break;
      }
      case "snooze": {
        const minutes = Math.min(Math.max(Math.round(Number(b.minutes) || 0), 5), 60 * 24 * 14);
        await db.chatConversation.update({
          where: { id },
          data: { snoozedUntil: new Date(Date.now() + minutes * 60_000), unreadForAgent: false },
        });
        break;
      }
      case "unsnooze": {
        await db.chatConversation.update({ where: { id }, data: { snoozedUntil: null } });
        break;
      }
      case "pin": {
        await db.chatConversation.update({ where: { id }, data: { pinned: b.on !== false } });
        break;
      }
      case "priority": {
        const v = (CHAT_PRIORITIES as string[]).includes(String(b.value)) ? (b.value as ChatPriority) : "NORMAL";
        await db.chatConversation.update({ where: { id }, data: { priority: v } });
        break;
      }
      case "ai": {
        await db.chatConversation.update({ where: { id }, data: { aiPaused: b.paused === true } });
        break;
      }
      default:
        throw new ChatAuthError(400, "Unknown action.");
    }
    await publishConvo(id);
    return ok({ conversation: await inboxRow(id) });
  } catch (e) {
    return chatErrorResponse(e);
  }
}

function ok(data: Record<string, unknown>) {
  return Response.json({ ok: true, ...data }, { headers: NO_STORE_HEADERS });
}
EOF
