        }
        break;
      }
      case "close": {
        await db.chatConversation.update({
          where: { id },
          data: { status: "CLOSED", closedAt: new Date(), unreadForAgent: false, snoozedUntil: null },
        });
        after(() => setDiscordThreadArchived("chat", convo.discordThreadId, true));
        break;
      }
      case "reopen": {
        await db.chatConversation.update({ where: { id }, data: { status: "OPEN", closedAt: null } });
        after(() => setDiscordThreadArchived("chat", convo.discordThreadId, false));
        break;
      }
      case "snooze": {
        const minutes = Math.min(Math.max(Math.round(Number(b.minutes) || 0), 5), 60 * 24 * 14);
        await db.chatConversation.update({
          where: { id },
          data: { snoozedUntil: new Date(Date.now() + minutes * 60_000), unreadForAgent: false },
        });
        break;
      }
      case "unsnooze": {
        await db.chatConversation.update({ where: { id }, data: { snoozedUntil: null } });
        break;
      }
      case "pin": {
        await db.chatConversation.update({ where: { id }, data: { pinned: b.on !== false } });
        break;
      }
      case "priority": {
        const v = (CHAT_PRIORITIES as string[]).includes(String(b.value)) ? (b.value as ChatPriority) : "NORMAL";
        await db.chatConversation.update({ where: { id }, data: { priority: v } });
        break;
      }
      case "ai": {
        await db.chatConversation.update({ where: { id }, data: { aiPaused: b.paused === true } });
        break;
      }
      default:
        throw new ChatAuthError(400, "Unknown action.");
    }
    await publishConvo(id);
    return ok({ conversation: await inboxRow(id) });
  } catch (e) {
    return chatErrorResponse(e);
  }
}

function ok(data: Record<string, unknown>) {
  return Response.json({ ok: true, ...data }, { headers: NO_STORE_HEADERS });
}
