import { db } from "@/lib/db";
import { chatStaffContext, chatErrorResponse, convoInScope } from "@/lib/chat/staff-auth";
import { loadCreatorUserIds } from "@/lib/creator-accounts-data";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * GET /api/admin/chat/conversations/[id]/context — the customer context panel
 * beside a chat: account, servers, billing status, recent invoices/payments,
 * open tickets, and this visitor's other chats. Read-only, staff-gated, scoped
 * like every other staff chat route. Anonymous visitors get an "unlinked" shape
 * (plus a best-effort match by the email they typed, clearly labelled as such).
 */
export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const ctx = await chatStaffContext();
    const { id } = await params;
    const c = await convoInScope(ctx, id);

    let userId = c.userId;
    let matchedByEmail = false;
    if (!userId && c.email) {
      const m = await db.user.findUnique({ where: { email: c.email }, select: { id: true } });
      if (m) {
        userId = m.id;
        matchedByEmail = true;
      }
    }

    const otherChats = await db.chatConversation.findMany({
      where: {
        id: { not: id },
        OR: [{ visitorId: (await db.chatConversation.findUnique({ where: { id }, select: { visitorId: true } }))!.visitorId }, ...(userId ? [{ userId }] : [])],
        ...(ctx.scopeUserId ? { userId: ctx.scopeUserId } : {}),
      },
      orderBy: { lastMessageAt: "desc" },
      take: 5,
      select: { id: true, status: true, lastMessageAt: true, lastPreview: true },
    });

    if (!userId) {
      return Response.json({ linked: false, otherChats }, { headers: NO_STORE_HEADERS });
    }

    const [user, servers, openInvoices, invoices, tickets, wallet, creators] = await Promise.all([
      db.user.findUnique({
        where: { id: userId },
        select: { id: true, name: true, email: true, role: true, createdAt: true, balanceCents: true, suspended: true, emailVerifiedAt: true },
      }),
      db.server.findMany({
        where: { userId },
        orderBy: { createdAt: "desc" },
        take: 8,
        select: { id: true, name: true, label: true, hostname: true, status: true, isFree: true, expiresAt: true, gameFamily: true, plan: { select: { name: true } } },
      }),
      db.invoice.aggregate({ where: { userId, status: "OPEN" }, _count: true, _sum: { amountCents: true } }),
      db.invoice.findMany({
        where: { userId },
        orderBy: { createdAt: "desc" },
        take: 5,
        select: { id: true, number: true, amountCents: true, status: true, description: true, createdAt: true, paidAt: true },
      }),
      db.ticket.findMany({
        where: { userId, status: { notIn: ["CLOSED"] } },
        orderBy: { createdAt: "desc" },
        take: 5,
        select: { id: true, subject: true, status: true, createdAt: true },
      }),
      db.walletTransaction.findMany({
        where: { userId },
        orderBy: { createdAt: "desc" },
        take: 5,
        select: { id: true, amountCents: true, description: true, createdAt: true },
      }),
      loadCreatorUserIds([userId]),
    ]);
    if (!user) return Response.json({ linked: false, otherChats }, { headers: NO_STORE_HEADERS });
    const serverCount = await db.server.count({ where: { userId } });

    return Response.json(
      {
        linked: true,
        matchedByEmail,
        user: { ...user, isCreator: creators.has(user.id) },
        servers,
        serverCount,
        billing: { openInvoices: openInvoices._count, openCents: openInvoices._sum.amountCents ?? 0, balanceCents: user.balanceCents },
        invoices,
        payments: wallet,
        tickets,
        otherChats,
      },
      { headers: NO_STORE_HEADERS },
    );
  } catch (e) {
    return chatErrorResponse(e);
  }
}
