import "server-only";
import type { User } from "@prisma/client";
import { db } from "@/lib/db";
import { currentUser, impersonating } from "@/lib/auth";

/**
 * Ownership for every CUSTOMER live-chat route (/api/chat/**).
 *
 * A conversation belongs to the caller when its `visitorId` matches the
 * browser's (localStorage) visitor id, OR — for a signed-in customer — its
 * `userId` is theirs, so their threads follow them across devices.
 *
 * IMPERSONATION: while an admin is impersonating, `currentUser()` is the
 * customer. The customer chat API must not let that admin read or post AS the
 * customer (the 2026-09-25 ticket-reply misattribution class), and must not
 * register "customer is viewing" presence. So every customer route refuses
 * while impersonating; the admin uses the staff chat dock (lib/chat/staff-auth.ts),
 * which writes as the admin.
 */

export const IMPERSONATION_REFUSAL =
  "Live chat as the customer is disabled while impersonating — use the staff chat dock, which replies as you.";

export function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

export async function customerCaller(): Promise<{ user: User | null; impersonating: boolean }> {
  const imp = await impersonating();
  if (imp) return { user: null, impersonating: true };
  return { user: await currentUser(), impersonating: false };
}

export function ownershipOr(visitorId: string | null, user: User | null): Record<string, unknown>[] {
  const or: Record<string, unknown>[] = [];
  if (visitorId) or.push({ visitorId });
  if (user?.id) or.push({ userId: user.id });
  return or;
}

const CUSTOMER_CONVO_SELECT = {
  id: true,
  visitorId: true,
  userId: true,
  status: true,
  name: true,
  email: true,
  assignedToId: true,
  botEscalatedAt: true,
  unreadForUser: true,
  userLastReadAt: true,
  agentLastReadAt: true,
  lastMessageAt: true,
} as const;

export async function findOwnedConversation(conversationId: string | null, visitorId: string | null, user: User | null) {
  if (!conversationId) return null;
  const or = ownershipOr(visitorId, user);
  if (!or.length) return null;
  return db.chatConversation.findFirst({ where: { id: conversationId, OR: or }, select: CUSTOMER_CONVO_SELECT });
}

/** The visitor's most recent OPEN thread (back-compat for clients that don't name one). */
export async function findLatestOpenConversation(visitorId: string) {
  return db.chatConversation.findFirst({
    where: { visitorId, status: "OPEN" },
    orderBy: { lastMessageAt: "desc" },
    select: CUSTOMER_CONVO_SELECT,
  });
}

export type CustomerConvo = NonNullable<Awaited<ReturnType<typeof findOwnedConversation>>>;

/** The conversation header a customer may see — no staff ids, no internal state. */
export function customerConvoView(c: CustomerConvo) {
  return {
    id: c.id,
    status: c.status,
    name: c.name,
    email: c.email,
    agentLastReadAt: c.agentLastReadAt ? c.agentLastReadAt.toISOString() : null,
  };
}

