import { NextResponse, after } from "next/server";
import { db } from "@/lib/db";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
import { readTyping } from "@/lib/chat-typing";
import { readBotStep } from "@/lib/chat-bot-step";
import { mirrorChatMessageToDiscord } from "@/lib/discord-bridge";
import { agentsOnline } from "@/lib/chat/hub";
import { markRead, pageCustomerMessages, publishMessage, writeVisitorMessage } from "@/lib/chat/server";
import { cleanClientId, toCustomerMessage } from "@/lib/chat/visibility";
import {
  IMPERSONATION_REFUSAL,
  clip,
  customerCaller,
  customerConvoView,
  findLatestOpenConversation,
  findOwnedConversation,
} from "@/lib/chat/customer-auth";

export const runtime = "nodejs";

/**
 * Public live-chat endpoint used by <ChatWidget/>.
 *
 * POST /api/chat — start or continue a conversation. Returns as soon as the
 *   visitor's message is stored (`{ conversation, message, messages }`); the
 *   Discord mirror and the AI assistant run AFTER the response (next/server
 *   `after`) and reach the widget over the live stream (/api/chat/stream).
 *   Before the overhaul both were awaited, so every send sat on "sending…" for
 *   a full Claude tool-loop call. Idempotent on `clientId`.
 * GET  /api/chat?visitorId=…&conversationId=…[&before=id|&after=id&limit=n]
 *   Paginated transcript (latest page by default). Also the polling fallback
 *   when the stream is unavailable.
 *
 * Ownership is strictly visitorId / signed-in userId (lib/chat/customer-auth.ts).
 * Internal staff notes are never returned (lib/chat/visibility.ts). Refused
 * while an admin is impersonating — they reply as staff from the chat dock.
 */

export async function POST(req: Request) {
  const rl = checkRateLimit(`chat:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "Too many messages. Please slow down." },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } },
    );
  }
  const caller = await customerCaller();
  if (caller.impersonating) {
    return NextResponse.json({ error: IMPERSONATION_REFUSAL, impersonating: true }, { status: 403, headers: NO_STORE_HEADERS });
  }
  const user = caller.user;

  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const visitorId = clip(raw.visitorId, 100);
  const conversationId = clip(raw.conversationId, 40);
  const body = clip(raw.body, 5000);
  const name = clip(raw.name, 120);
  const email = clip(raw.email, 200);
  const clientId = cleanClientId(raw.clientId);

