  const conversationId = clip(url.searchParams.get("conversationId"), 40);
  const empty = { conversation: null, messages: [], hasMore: false, agentsOnline: agentsOnline() > 0 };
  if (!visitorId) return NextResponse.json(empty, { headers: NO_STORE_HEADERS });

  const caller = await customerCaller();
  if (caller.impersonating) {
    return NextResponse.json({ ...empty, impersonating: true }, { headers: NO_STORE_HEADERS });
  }

  let convo = conversationId
    ? await findOwnedConversation(conversationId, visitorId, caller.user)
    : await findLatestOpenConversation(visitorId);
  if (!convo) return NextResponse.json(empty, { headers: NO_STORE_HEADERS });

  // Waiting on a live agent: let this read drive the handoff window too (the
  // stream's sweep also does, see lib/chat/sweep.ts).
  if (convo.botEscalatedAt) {
    try {
      const { checkEscalationTimeout } = await import("@/lib/kb-run");
      await checkEscalationTimeout(convo.id);
    } catch {
      /* non-essential */
    }
  }

  const page = await pageCustomerMessages({
    conversationId: convo.id,
    before: url.searchParams.get("before"),
    after: url.searchParams.get("after"),
    limit: Number(url.searchParams.get("limit") ?? 0) || undefined,
    fallbackAuthorId: convo.assignedToId,
  });

  // Reading the latest page is a read receipt (only when something is unread,
  // so the polling fallback doesn't spam the agent side with read events).
  const loadingOlder = !!url.searchParams.get("before");
  if (!loadingOlder && (convo.unreadForUser || !convo.userLastReadAt || convo.userLastReadAt < convo.lastMessageAt)) {
    await markRead(convo.id, "visitor").catch(() => {});
    convo = (await findOwnedConversation(convo.id, visitorId, caller.user)) ?? convo;
  }

  // The `?visitorId=` in the URL is the only thing scoping this transcript —
  // which makes the URL itself the secret; never let a shared cache store it.
  return NextResponse.json(
    {
      conversation: customerConvoView(convo),
      messages: page.messages,
      hasMore: page.hasMore,
      typing: { agent: readTyping(convo.id).agent },
      botStep: readBotStep(convo.id),
      agentsOnline: agentsOnline() > 0,
    },
    { headers: NO_STORE_HEADERS },
  );
}

