import { NextResponse } from "next/server";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
import { agentsOnline } from "@/lib/chat/hub";
import { previewOf } from "@/lib/chat/visibility";
import { clip, customerCaller, ownershipOr } from "@/lib/chat/customer-auth";

export const runtime = "nodejs";

/**
 * GET /api/chat/list?visitorId=… — the visitor's past conversations, newest
 * first, for the widget's "previous chats" list. Ownership: visitorId match,
 * or (signed in) the conversation's userId. Also reports whether any support
 * agent is online right now, so the widget can show "online" vs "away".
 *
 * Previews come from the denormalised `lastPreview` (never an internal note);
 * titles from the first customer-visible message, one DISTINCT ON query.
 */
export async function GET(req: Request) {
  const url = new URL(req.url);
  const visitorId = clip(url.searchParams.get("visitorId"), 100);
  const caller = await customerCaller();
  const online = agentsOnline() > 0;
  if (caller.impersonating) return NextResponse.json({ conversations: [], agentsOnline: online, impersonating: true }, { headers: NO_STORE_HEADERS });

  const or = ownershipOr(visitorId, caller.user);
  if (!or.length) return NextResponse.json({ conversations: [], agentsOnline: online }, { headers: NO_STORE_HEADERS });

  const rows = await db.chatConversation.findMany({
    where: { OR: or },
    orderBy: { lastMessageAt: "desc" },
    take: 20,
    select: { id: true, status: true, lastMessageAt: true, unreadForUser: true, lastPreview: true, lastSender: true },
  });
  const ids = rows.map((r) => r.id);

  type Edge = { conversationId: string; sender: string; body: string; hasAtt: boolean };
  const [firsts, lasts] = ids.length
    ? await Promise.all([
        db.$queryRaw<Edge[]>`
          SELECT DISTINCT ON (m."conversationId") m."conversationId", m.sender, m.body, (a.id IS NOT NULL) AS "hasAtt"
            FROM "ChatMessage" m LEFT JOIN "ChatAttachment" a ON a."messageId" = m.id
           WHERE m."conversationId" IN (${Prisma.join(ids)}) AND m.internal = false
           ORDER BY m."conversationId", m."createdAt" ASC, m.id ASC`,
        db.$queryRaw<Edge[]>`
          SELECT DISTINCT ON (m."conversationId") m."conversationId", m.sender, m.body, (a.id IS NOT NULL) AS "hasAtt"
            FROM "ChatMessage" m LEFT JOIN "ChatAttachment" a ON a."messageId" = m.id
           WHERE m."conversationId" IN (${Prisma.join(ids)}) AND m.internal = false
             AND m."conversationId" IN (SELECT id FROM "ChatConversation" WHERE id IN (${Prisma.join(ids)}) AND "lastPreview" IS NULL)
           ORDER BY m."conversationId", m."createdAt" DESC, m.id DESC`,
      ])
    : [[], []];
  const firstBy = new Map(firsts.map((m) => [m.conversationId, m]));
  const lastBy = new Map(lasts.map((m) => [m.conversationId, m]));

  const conversations = rows.map((r) => {
    const first = firstBy.get(r.id);
    const title = first?.body?.trim() ? first.body.trim().slice(0, 60) : first?.hasAtt ? "Image" : "New conversation";
    const fb = lastBy.get(r.id);
    const sender = r.lastSender ?? fb?.sender ?? null;
    const text = r.lastPreview ?? (fb ? previewOf(fb.body, fb.hasAtt) : "");
    const preview = text ? `${sender === "visitor" ? "You: " : ""}${text.slice(0, 80)}` : "";
    return {
      id: r.id,
      title,
      preview,
      status: r.status,
      unread: r.unreadForUser,
      lastMessageAt: r.lastMessageAt.toISOString(),
    };
  });

  return NextResponse.json({ conversations, agentsOnline: online }, { headers: NO_STORE_HEADERS });
}

