import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { markTyping } from "@/lib/chat-typing";
import { clip, customerCaller, findOwnedConversation } from "@/lib/chat/customer-auth";

export const runtime = "nodejs";

/**
 * POST /api/chat/typing `{ visitorId, conversationId? }` — "the visitor is
 * typing". Pushed to staff instantly through the live-chat hub (markTyping
 * publishes). Separate from POST /api/chat so typing pings never consume the
 * send budget. Best-effort: every problem is a silent 204.
 */
export async function POST(req: Request) {
  const rl = checkRateLimit(`chat-typing:${trustedClientIp(req)}`, { max: 40, windowMs: 60_000 });
  if (!rl.ok) return new NextResponse(null, { status: 204 });

  const caller = await customerCaller();
  if (caller.impersonating) return new NextResponse(null, { status: 204 });

  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const visitorId = clip(raw.visitorId, 100);
  const conversationId = clip(raw.conversationId, 40);
  if (!visitorId) return new NextResponse(null, { status: 204 });

  const convo = conversationId
    ? await findOwnedConversation(conversationId, visitorId, caller.user).catch(() => null)
    : await db.chatConversation
        .findFirst({ where: { visitorId, status: "OPEN" }, orderBy: { lastMessageAt: "desc" }, select: { id: true } })
        .catch(() => null);

  if (convo) markTyping(convo.id, "visitor");
  return new NextResponse(null, { status: 204 });
}

