import { NextResponse, after } from "next/server";
import { db } from "@/lib/db";
import { checkRateLimit } from "@/lib/rate-limit";
import { validateImageBytes, MAX_ATTACHMENT_BYTES } from "@/lib/chat-attachment";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
import { mirrorChatMessageToDiscord } from "@/lib/discord-bridge";
import { pageCustomerMessages, publishMessage, writeVisitorMessage } from "@/lib/chat/server";
import { cleanClientId, toCustomerMessage } from "@/lib/chat/visibility";
import {
  IMPERSONATION_REFUSAL,
  clip,
  customerCaller,
  customerConvoView,
  findOwnedConversation,
} from "@/lib/chat/customer-auth";

export const runtime = "nodejs";

/**
 * Image upload for <ChatWidget/> (multipart: visitorId, file, optional body,
 * conversationId, clientId, name/email). Same ownership, identity gate,
 * idempotency and after-response assistant/Discord handling as POST /api/chat.
 * The image is validated by signature (never the declared type) in
 * lib/chat-attachment — SVG and non-images are rejected. Bytes live in Postgres.
 */
export async function POST(req: Request) {
  const rl = checkRateLimit(`chat-upload:${trustedClientIp(req)}`, { max: 15, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "Too many uploads. Please slow down." },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } },
    );
  }
  const caller = await customerCaller();
  if (caller.impersonating) {
    return NextResponse.json({ error: IMPERSONATION_REFUSAL, impersonating: true }, { status: 403, headers: NO_STORE_HEADERS });
  }
  const user = caller.user;

  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "Invalid upload." }, { status: 400 });
  }

  const visitorId = clip(form.get("visitorId"), 100);
  const body = clip(form.get("body"), 5000) ?? "";
  const name = clip(form.get("name"), 120);
  const email = clip(form.get("email"), 200);
  const conversationId = clip(form.get("conversationId"), 40);
  const clientId = cleanClientId(form.get("clientId"));
  const file = form.get("file");

  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
  if (!(file instanceof File)) return NextResponse.json({ error: "No image provided." }, { status: 400 });
  if (file.size > MAX_ATTACHMENT_BYTES) {
    return NextResponse.json({ error: "Image is larger than 5 MB." }, { status: 413 });
  }
  const check = validateImageBytes(Buffer.from(await file.arrayBuffer()), file.type);
  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });

  let convo = await findOwnedConversation(conversationId, visitorId, user);
  if (!convo) {
    if (!user) {
      if (!name || !email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
        return NextResponse.json(
          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
          { status: 400 },
        );
      }
    }
    const created = await db.chatConversation.create({
      data: { visitorId, userId: user?.id ?? null, name: name ?? user?.name ?? null, email: email ?? user?.email ?? null },
      select: { id: true },
    });
    convo = await findOwnedConversation(created.id, visitorId, user);
  }
  if (!convo) return NextResponse.json({ error: "Could not start the chat." }, { status: 500 });

  const written = await writeVisitorMessage({
    conversationId: convo.id,
    body,
    clientId,
    image: { mime: check.mime, bytes: check.bytes },
    identity: { userId: user?.id ?? null, name, email },
  });
  const staffMsg = await publishMessage(written.id);

  if (!written.duplicate) {
    const cid = convo.id;
    const b64 = Buffer.from(check.bytes).toString("base64");
    const mime = check.mime;
    after(async () => {
      await mirrorChatMessageToDiscord(cid, body ? `📎 ${body}` : "📎 (image attachment — view in the chat widget/admin)", "visitor");
      try {
        const { runAssistant } = await import("@/lib/kb-run");
        await runAssistant({ conversationId: cid, visitorId, currentBody: body, images: [{ mediaType: mime, dataB64: b64 }] });
      } catch {
        /* assistant is non-essential */
      }
    });
  }

  const page = await pageCustomerMessages({ conversationId: convo.id, fallbackAuthorId: convo.assignedToId });
  return NextResponse.json(
    {
      conversation: customerConvoView(convo),
      message: staffMsg ? toCustomerMessage(staffMsg) : null,
      duplicate: written.duplicate,
      messages: page.messages,
      hasMore: page.hasMore,
    },
    { headers: NO_STORE_HEADERS },
  );
}

