    convo = await findOwnedConversation(created.id, visitorId, user);
  }
  if (!convo) return NextResponse.json({ error: "Could not start the chat." }, { status: 500 });

  const written = await writeVisitorMessage({
    conversationId: convo.id,
    body,
    clientId,
    image: { mime: check.mime, bytes: check.bytes },
    identity: { userId: user?.id ?? null, name, email },
  });
  const staffMsg = await publishMessage(written.id);

  if (!written.duplicate) {
    const cid = convo.id;
    const b64 = Buffer.from(check.bytes).toString("base64");
    const mime = check.mime;
    after(async () => {
      await mirrorChatMessageToDiscord(cid, body ? `📎 ${body}` : "📎 (image attachment — view in the chat widget/admin)", "visitor");
      try {
        const { runAssistant } = await import("@/lib/kb-run");
        await runAssistant({ conversationId: cid, visitorId, currentBody: body, images: [{ mediaType: mime, dataB64: b64 }] });
      } catch {
        /* assistant is non-essential */
      }
    });
  }

  const page = await pageCustomerMessages({ conversationId: convo.id, fallbackAuthorId: convo.assignedToId });
  return NextResponse.json(
    {
      conversation: customerConvoView(convo),
      message: staffMsg ? toCustomerMessage(staffMsg) : null,
      duplicate: written.duplicate,
      messages: page.messages,
      hasMore: page.hasMore,
    },
    { headers: NO_STORE_HEADERS },
  );
}

