import { db } from "@/lib/db";
import { realUser, currentUser, impersonating } from "@/lib/auth";
import { isStaff } from "@/lib/rbac";
import { hasAreaAccess } from "@/lib/staff-grants";
import { isAllowedImageMime } from "@/lib/chat-attachment";
import { makeThumbnail } from "@/lib/chat/thumbnail";

export const runtime = "nodejs";

/**
 * GET /api/chat/attachment/[id][?size=thumb][&visitorId=…] — stream a chat
 * image ONLY to an authorized viewer:
 *   • staff with live-chat access (SUPPORT / ADMIN, or an EMPLOYEE granted
 *     liveChat), OR
 *   • the visitor who owns the conversation (visitorId matches), OR
 *   • the signed-in customer the conversation is linked to (userId matches).
 * An image on an INTERNAL staff note is staff-only, whatever the caller holds.
 *
 * `?size=thumb` serves a ≤480 px WEBP generated once and persisted on the row
 * (lib/chat/thumbnail.ts); the original is only fetched when the lightbox
 * opens. Both are immutable for a given id, so they're cached privately for a
 * year with an ETag — never in a shared cache (Cache-Control: private), and the
 * id is an unguessable cuid that is only ever handed to authorized viewers.
 *
 * `id` is a database id, never a filename (no path traversal). Responses carry
 * the real stored MIME (always allow-listed), nosniff, an inline disposition
 * with a fixed filename and a sandboxing CSP.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

const BASE_HEADERS = {
  "Content-Disposition": 'inline; filename="image"',
  "X-Content-Type-Options": "nosniff",
  "Content-Security-Policy": "default-src 'none'; sandbox",
  "Cache-Control": "private, max-age=31536000, immutable, no-transform",
};

export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  if (typeof id !== "string" || !id || id.length > 40) return new Response("Not found", { status: 404 });
  const url = new URL(req.url);
  const wantThumb = url.searchParams.get("size") === "thumb";

  // Metadata only — the bytes are fetched below, after authorization.
  const meta = await db.chatAttachment.findUnique({
    where: { id },
    select: {
      id: true,
      mime: true,
      thumbMime: true,
      message: { select: { internal: true, conversation: { select: { visitorId: true, userId: true } } } },
    },
  });
  if (!meta) return new Response("Not found", { status: 404 });
  const convo = meta.message.conversation;

  let authorized = false;
  const staff = await realUser();
  if (staff && (isStaff(staff.role) || staff.role === "EMPLOYEE") && (await hasAreaAccess(staff, "liveChat"))) {
    authorized = true;
  } else if (!meta.message.internal) {
    const visitorId = clip(url.searchParams.get("visitorId"), 100);
    if (visitorId && visitorId === convo.visitorId) {
      authorized = true;
    } else if (convo.userId && !(await impersonating())) {
      const user = await currentUser();
      if (user && user.id === convo.userId) authorized = true;
    }
  }
  if (!authorized) return new Response("Forbidden", { status: 403 });

  const etag = `"${id}${wantThumb ? "-t" : ""}"`;
  if (req.headers.get("if-none-match") === etag) {
    return new Response(null, { status: 304, headers: { ETag: etag, "Cache-Control": BASE_HEADERS["Cache-Control"] } });
  }

  if (wantThumb) {
    const row = await db.chatAttachment.findUnique({ where: { id }, select: { thumb: true, thumbMime: true } });
    let thumb: Buffer | null = row?.thumb ? Buffer.from(row.thumb as Uint8Array) : null;
    let thumbMime = row?.thumbMime ?? null;
    if (!thumb) {
      const full = await db.chatAttachment.findUnique({ where: { id }, select: { data: true } });
      const made = full ? await makeThumbnail(Buffer.from(full.data as Uint8Array)) : null;
      if (made) {
        thumb = made.data;
        thumbMime = made.mime;
        await db.chatAttachment
          .update({
            where: { id },
            data: { thumb: new Uint8Array(made.data), thumbMime: made.mime, width: made.width || null, height: made.height || null },
          })
          .catch(() => {});
      } else if (full) {
        // No thumbnailer available: fall back to the original (pre-overhaul behaviour).
        return send(Buffer.from(full.data as Uint8Array), meta.mime, `"${id}"`);
      }
    }
    if (thumb && thumbMime && isAllowedImageMime(thumbMime)) return send(thumb, thumbMime, etag);
  }

  const full = await db.chatAttachment.findUnique({ where: { id }, select: { data: true } });
  if (!full) return new Response("Not found", { status: 404 });
  return send(Buffer.from(full.data as Uint8Array), meta.mime, `"${id}"`);
}

function send(data: Buffer, mime: string, etag: string): Response {
  // Defense in depth: never serve anything that isn't an allow-listed image.
  const type = isAllowedImageMime(mime) ? mime : "application/octet-stream";
  return new Response(new Uint8Array(data), {
    status: 200,
    headers: { ...BASE_HEADERS, "Content-Type": type, "Content-Length": String(data.length), ETag: etag },
  });
}

