import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
import { subscribe, visitorConnected, agentsOnline } from "@/lib/chat/hub";
import { ensureSweep } from "@/lib/chat/sweep";
import { sseStream } from "@/lib/chat/sse";
import { toCustomerMessage } from "@/lib/chat/visibility";
import { readTyping } from "@/lib/chat-typing";
import { readBotStep } from "@/lib/chat-bot-step";
import { clip, customerCaller, findOwnedConversation } from "@/lib/chat/customer-auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import type { SeqEvent } from "@/lib/chat/types";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * GET /api/chat/stream?visitorId=…&conversationId=… — the customer widget's
 * live event stream (SSE) for ONE conversation it owns.
 *
 * Everything sent is projected through the customer view: messages go through
 * `toCustomerMessage` (internal notes → dropped, staff identity → first name
 * only); typing/read/bot-step are the agent/assistant side only; no staff ids,
 * no other conversation's events, no viewing/presence of staff by name.
 *
 * Refused while an admin is impersonating (they'd otherwise register as "the
 * customer is viewing" and receive the customer's view) — see
 * lib/chat/customer-auth.ts.
 */
export async function GET(req: Request) {
  const rl = checkRateLimit(`chat-stream:${trustedClientIp(req)}`, { max: 60, windowMs: 60_000 });
  if (!rl.ok) return Response.json({ error: "slow down" }, { status: 429, headers: NO_STORE_HEADERS });

  const url = new URL(req.url);
  const visitorId = clip(url.searchParams.get("visitorId"), 100);
  const conversationId = clip(url.searchParams.get("conversationId"), 40);
  const caller = await customerCaller();
  if (caller.impersonating) return Response.json({ error: "impersonating" }, { status: 403, headers: NO_STORE_HEADERS });
  const convo = await findOwnedConversation(conversationId, visitorId, caller.user);
  if (!convo) return Response.json({ error: "not found" }, { status: 404, headers: NO_STORE_HEADERS });
  const cid = convo.id;

  return sseStream(req, (send) => {
    send("hello", {
      conversationId: cid,
      status: convo.status,
      agentsOnline: agentsOnline() > 0,
      agentTyping: readTyping(cid).agent,
      botStep: readBotStep(cid),
      agentLastReadAt: convo.agentLastReadAt ? convo.agentLastReadAt.toISOString() : null,
    });
    const off = subscribe((e: SeqEvent) => {
      switch (e.kind) {
        case "message": {
          if (e.conversationId !== cid) return;
          const m = toCustomerMessage(e.message);
          if (m) send("message", m, e.seq);
          return;
        }
        case "typing":
          if (e.conversationId !== cid || e.who !== "agent") return;
          send("typing", { active: e.active, name: e.name }, e.seq);
          return;
        case "read":
          if (e.conversationId !== cid || e.who !== "agent") return;
          send("read", { at: e.at }, e.seq);
          return;
        case "botStep":
          if (e.conversationId !== cid) return;
          send("botStep", { step: e.step }, e.seq);
          return;
        case "convo":
          if (e.conversation.id !== cid) return;
          send("status", { status: e.conversation.status }, e.seq);
          return;
        case "agentsOnline":
          send("agents", { online: e.count > 0 }, e.seq);
          return;
        default:
          return; // viewing / visitorPresence are staff-only signals
      }
    });
    const gone = visitorConnected(cid);
    ensureSweep();
    return () => {
      off();
      gone();
    };
  });
}
EOF
