export async function writeChatReply(args: {
  conversationId: string;
  body: string;
  /** The staff/admin user id the reply is attributed to. */
  staffId: string;
}): Promise<{ error?: string; ok?: boolean; conversationUserId?: string | null }> {
  const parsed = z
