}

/**
 * "View as customer" from a chat: start impersonating the signed-in customer
 * this conversation belongs to, so the admin can see exactly what they see
 * while the staff chat dock (components/admin/chat/ChatDock.tsx) stays open
 * beside it. ADMIN only — impersonation is an ADMIN capability
 * (lib/auth.ts setImpersonation). Same audit row as /admin/users' button
 * (`admin.impersonate_start`, detail = the target email) plus a chat-specific
 * row naming the conversation, written BEFORE the cookie so neither carries
 * an `actingAdmin=` suffix.
 *
 * Returns instead of redirecting; the client navigates with a real
 * window.location.assign — the same production-router quirk that made the
 * impersonation exit 404 (see components/nx/Banners.tsx) applies to entry.
 */
export async function impersonateFromChat(conversationId: string): Promise<{ ok?: boolean; error?: string }> {
  const admin = await requireAdmin();
  if (typeof conversationId !== "string" || !conversationId) return { error: "Invalid conversation." };
  const convo = await db.chatConversation.findUnique({ where: { id: conversationId }, select: { userId: true } });
  if (!convo?.userId) return { error: "This visitor isn't signed in to a customer account, so there's nobody to view as." };
  const target = await db.user.findUnique({ where: { id: convo.userId }, select: { id: true, email: true, role: true, suspended: true } });
  if (!target || target.role !== "CUSTOMER" || target.suspended) return { error: "This account can't be impersonated." };
  await recordAudit(admin.id, "admin.impersonate_start", `${target.email}`);
  await recordAudit(admin.id, "chat.impersonate_from_chat", `conversation=${conversationId} target=${target.email}`);
  await setImpersonation(target.id);
  return { ok: true };
}

