"use client";

import type { ComponentType } from "react";
import PlanCard, { type PlanCardData } from "./PlanCard";
import ActionCard, { type ActionCardData } from "./ActionCard";
import type { ChatCard } from "@/lib/chat/types";

/**
 * Chat card registry — renders `ChatMessage.cardsJson` entries by `type`.
 *
 * INTEGRATION SEAM (custom Offers, branch feature/chat-offers): a card
 * `{ "type": "offer", "offerId": "..." }` is rendered by the default export of
 * `components/chat/cards/OfferCard.tsx` with props
 * `{ offerId: string; viewer: "admin" | "customer" }`. That file is owned by
 * the Offers work and is picked up AUTOMATICALLY when it exists — this file
 * does not import it by name, so this branch builds with or without it
 * (webpack `require.context` over this directory matching only OfferCard.tsx).
 * Until it lands, offer cards render the neutral placeholder below.
 *
 * Unknown/unsupported card types NEVER render raw JSON or any field of the
 * card — only a neutral "this message has content your app can't show yet".
 */

export type CardViewer = "admin" | "customer";
type OfferCardProps = { offerId: string; viewer: CardViewer };

type ReqCtx = { keys(): string[]; (k: string): { default?: ComponentType<OfferCardProps> } };
let OfferCard: ComponentType<OfferCardProps> | null = null;
try {
  const ctx = (require as unknown as { context: (d: string, s: boolean, r: RegExp) => ReqCtx }).context("./", false, /^\.\/OfferCard\.tsx$/);
  const key = ctx.keys()[0];
  if (key) OfferCard = ctx(key).default ?? null;
} catch {
  OfferCard = null;
}

/** Exposed for tests / feature detection (e.g. hide offer-only UI). */
export function hasOfferCard(): boolean {
  return OfferCard !== null;
}

function Placeholder({ label }: { label: string }) {
  return (
    <div className="mt-2 w-full max-w-[85%] rounded-2xl border border-dashed border-white/15 bg-white/[0.02] px-3 py-2.5 text-xs text-slate-400">
      {label}
    </div>
  );
}

export function ChatCardView({ card, viewer }: { card: ChatCard; viewer: CardViewer }) {
  const type = typeof card.type === "string" ? card.type : "plan"; // legacy plan cards carry no type
  switch (type) {
    case "plan":
      return <PlanCard c={card as unknown as PlanCardData} />;
    case "action":
      return <ActionCard c={card as unknown as ActionCardData} />;
    case "offer": {
      const offerId = typeof card.offerId === "string" ? card.offerId : "";
      if (OfferCard && offerId) return <OfferCard offerId={offerId} viewer={viewer} />;
      return <Placeholder label={viewer === "admin" ? "Offer card (the Offers module isn't installed on this build)." : "An offer was shared here — refresh to view it."} />;
    }
    default:
      return <Placeholder label="This message contains content that can't be shown here." />;
  }
}

export function ChatCards({ cards, viewer }: { cards: ChatCard[] | null | undefined; viewer: CardViewer }) {
  if (!cards || !cards.length) return null;
  return (
    <div className="w-full">
      {cards.map((c, i) => (
        <ChatCardView key={typeof c.key === "string" ? c.key : `${c.type ?? "card"}-${i}`} card={c} viewer={viewer} />
      ))}
    </div>
  );
}
EOF
