import type { InboxCounts, InboxRow, InboxTab, StaffChatMessage } from "@/lib/chat/types";

/**
 * Client store for every staff live-chat surface (the /admin/chat workspace and
 * the persistent dock). ONE instance per browser tab, mounted at layout level,
 * so the live stream survives client-side navigation between admin pages.
 *
 * Transport: one EventSource on /api/admin/chat/stream. On every (re)connect
 * the store re-syncs from the DB (list + `after=<last id>` for each open
 * thread), so events missed during a drop are backfilled, never lost. If the
 * stream can't be established at all (proxy, old browser), it falls back to a
 * 5 s poll of the same JSON routes and keeps retrying the stream every 30 s.
 */

export type UiMessage = StaffChatMessage & { local?: LocalState; file?: File | null; previewUrl?: string | null };

export type Thread = {
  messages: UiMessage[];
  hasMore: boolean;
  loaded: boolean;
  loadingOlder: boolean;
};

export type Conn = "connecting" | "live" | "polling" | "offline";

export type ChatState = {
  me: { id: string; name: string; role: string } | null;
  scoped: boolean;
  conn: Conn;
  rows: Record<string, InboxRow>;
  /** Ids of the current list view, in server order. */
  listIds: string[];
  listHasMore: boolean;
  listLoading: boolean;
  counts: InboxCounts | null;
  tab: InboxTab;
  q: string;
  priorityOnly: boolean;
  threads: Record<string, Thread>;
  /** conversationId -> epoch ms until which the visitor counts as typing. */
  visitorTyping: Record<string, number>;
  botStep: Record<string, string | null>;
  viewers: Record<string, { staffId: string; name: string }[]>;
  visitorsOnline: Record<string, boolean>;
  agentsOnline: number;
};

type Listener = () => void;
type MessageHook = (m: StaffChatMessage, row: InboxRow | undefined) => void;

const TYPING_MS = 6500;

async function j<T>(url: string, init?: RequestInit): Promise<T> {
  const res = await fetch(url, { cache: "no-store", credentials: "same-origin", ...init });
  const data = (await res.json().catch(() => ({}))) as T & { error?: string };
  if (!res.ok) throw new Error((data as { error?: string }).error || `Request failed (${res.status})`);
  return data;
}

export class StaffChatStore {
  state: ChatState;
  private listeners = new Set<Listener>();
  private messageHooks = new Set<MessageHook>();
  private es: EventSource | null = null;
  private pollTimer: ReturnType<typeof setInterval> | null = null;
  private retryTimer: ReturnType<typeof setTimeout> | null = null;
  private failures = 0;
  private everOpened = false;
  private started = false;
  private listReq = 0;
  /** Threads someone has open right now (refcounted by mounted panes). */
  private open = new Map<string, number>();

  constructor(initialTab: InboxTab = "waiting") {
    this.state = {
      me: null,
      scoped: false,
      conn: "connecting",
      rows: {},
      listIds: [],
      listHasMore: false,
      listLoading: false,
      counts: null,
      tab: initialTab,
      q: "",
      priorityOnly: false,
      threads: {},
      visitorTyping: {},
      botStep: {},
      viewers: {},
      visitorsOnline: {},
      agentsOnline: 0,
    };
  }

  subscribe = (l: Listener) => {
    this.listeners.add(l);
    return () => {
      this.listeners.delete(l);
    };
  };
  getSnapshot = () => this.state;

  private set(patch: Partial<ChatState> | ((s: ChatState) => Partial<ChatState>)) {
    const p = typeof patch === "function" ? patch(this.state) : patch;
    this.state = { ...this.state, ...p };
    for (const l of this.listeners) l();
  }

  onMessage(h: MessageHook): () => void {
    this.messageHooks.add(h);
    return () => {
      this.messageHooks.delete(h);
    };
  }

  /* ---------------- lifecycle ---------------- */

  start() {
    if (this.started) return;
    this.started = true;
    this.connect();
    void this.refreshList();
    if (typeof document !== "undefined") {
      document.addEventListener("visibilitychange", this.onVisible);
      window.addEventListener("online", this.onVisible);
    }
  }

  stop() {
    this.started = false;
    this.es?.close();
    this.es = null;
    if (this.pollTimer) clearInterval(this.pollTimer);
    if (this.retryTimer) clearTimeout(this.retryTimer);
    if (typeof document !== "undefined") {
      document.removeEventListener("visibilitychange", this.onVisible);
      window.removeEventListener("online", this.onVisible);
    }
  }

  private onVisible = () => {
    if (typeof document !== "undefined" && document.visibilityState !== "visible") return;
    if (!this.es || this.es.readyState === 2) this.connect();
    void this.resync();
  };

  private connect() {
    if (typeof window === "undefined" || typeof EventSource === "undefined") {
      this.startPolling();
      return;
    }
    this.es?.close();
    const es = new EventSource("/api/admin/chat/stream");
    this.es = es;
    this.set({ conn: this.everOpened ? "connecting" : this.state.conn });
    es.onopen = () => {
      const wasOpened = this.everOpened;
      this.everOpened = true;
      this.failures = 0;
      this.stopPolling();
      this.set({ conn: "live" });
      if (wasOpened) void this.resync(); // backfill whatever happened while we were away
    };
    es.onerror = () => {
      // EventSource auto-reconnects (server sends retry: 2000) unless CLOSED.
      this.failures++;
      if (es.readyState === 2 || this.failures >= 3) {
        es.close();
        if (this.es === es) this.es = null;
        this.startPolling();
        if (this.retryTimer) clearTimeout(this.retryTimer);
        this.retryTimer = setTimeout(() => this.started && this.connect(), 30_000);
      } else {
        this.set({ conn: "connecting" });
      }
    };
    es.addEventListener("hello", (ev) => {
      const d = JSON.parse((ev as MessageEvent).data) as {
        me: ChatState["me"];
        scoped: boolean;
        agentsOnline: number;
        viewers: { conversationId: string; staffId: string; name: string }[];
        visitorsOnline: string[];
      };
      const viewers: ChatState["viewers"] = {};
      for (const v of d.viewers) (viewers[v.conversationId] ??= []).push({ staffId: v.staffId, name: v.name });
      this.set({
        me: d.me,
        scoped: d.scoped,
        agentsOnline: d.agentsOnline,
        viewers,
        visitorsOnline: Object.fromEntries(d.visitorsOnline.map((id) => [id, true])),
      });
    });
    es.addEventListener("convo", (ev) => this.applyRow(JSON.parse((ev as MessageEvent).data) as InboxRow));
    es.addEventListener("message", (ev) => {
      const d = JSON.parse((ev as MessageEvent).data) as { message: StaffChatMessage };
      this.applyMessage(d.message);
    });
    es.addEventListener("typing", (ev) => {
      const d = JSON.parse((ev as MessageEvent).data) as { conversationId: string; who: string; active: boolean };
      if (d.who !== "visitor") return;
      this.set((s) => ({ visitorTyping: { ...s.visitorTyping, [d.conversationId]: d.active ? Date.now() + TYPING_MS : 0 } }));
    });
    es.addEventListener("read", (ev) => {
      const d = JSON.parse((ev as MessageEvent).data) as { conversationId: string; who: string; at: string };
      const row = this.state.rows[d.conversationId];
      if (!row) return;
      this.applyRow({ ...row, ...(d.who === "visitor" ? { userLastReadAt: d.at } : { agentLastReadAt: d.at }) }, false);
    });
    es.addEventListener("botStep", (ev) => {
      const d = JSON.parse((ev as MessageEvent).data) as { conversationId: string; step: string | null };
      this.set((s) => ({ botStep: { ...s.botStep, [d.conversationId]: d.step } }));
    });
    es.addEventListener("viewing", (ev) => {
      const d = JSON.parse((ev as MessageEvent).data) as { conversationId: string; staffId: string; name: string; on: boolean };
      this.set((s) => {
        const cur = (s.viewers[d.conversationId] ?? []).filter((v) => v.staffId !== d.staffId);
        return { viewers: { ...s.viewers, [d.conversationId]: d.on ? [...cur, { staffId: d.staffId, name: d.name }] : cur } };
      });
    });
    es.addEventListener("visitorPresence", (ev) => {
      const d = JSON.parse((ev as MessageEvent).data) as { conversationId: string; online: boolean };
      this.set((s) => ({ visitorsOnline: { ...s.visitorsOnline, [d.conversationId]: d.online } }));
    });
    es.addEventListener("agentsOnline", (ev) => {
      const d = JSON.parse((ev as MessageEvent).data) as { count: number };
      this.set({ agentsOnline: d.count });
    });
  }

  private startPolling() {
    this.set({ conn: typeof navigator !== "undefined" && navigator.onLine === false ? "offline" : "polling" });
    if (this.pollTimer) return;
    this.pollTimer = setInterval(() => void this.resync(), 5000);
  }
  private stopPolling() {
    if (this.pollTimer) clearInterval(this.pollTimer);
    this.pollTimer = null;
  }

  /** Re-read the list and backfill every open thread from its last known message. */
  async resync() {
    await Promise.all([this.refreshList(true), ...[...this.open.keys()].map((id) => this.backfill(id))]);
  }

  /* ---------------- list ---------------- */

  setFilters(p: { tab?: InboxTab; q?: string; priorityOnly?: boolean }) {
    this.set(p);
    void this.refreshList();
  }

  async refreshList(quiet = false, more = false) {
    const req = ++this.listReq;
    const s = this.state;
    if (!quiet) this.set({ listLoading: true });
    const params = new URLSearchParams({ tab: s.tab, limit: "50", offset: String(more ? s.listIds.length : 0) });
    if (s.q.trim()) params.set("q", s.q.trim());
    if (s.priorityOnly) params.set("priority", "1");
    try {
      const d = await j<{ rows: InboxRow[]; hasMore: boolean; counts: InboxCounts; scoped: boolean }>(`/api/admin/chat/conversations?${params}`);
      if (req !== this.listReq) return; // a newer filter won
      const rows = { ...this.state.rows };
      for (const r of d.rows) rows[r.id] = r;
      const ids = d.rows.map((r) => r.id);
      this.set({
        rows,
        listIds: more ? [...this.state.listIds, ...ids.filter((id) => !this.state.listIds.includes(id))] : ids,
        listHasMore: d.hasMore,
        counts: d.counts,
        scoped: d.scoped,
        listLoading: false,
      });
    } catch {
      if (req === this.listReq) this.set({ listLoading: false });
    }
  }

  /** Does a row belong in the current list view? Mirrors lib/chat/server.ts tabWhere. */
  private matchesView(r: InboxRow): boolean {
    const s = this.state;
    const now = Date.now();
    const awake = r.status === "OPEN" && (!r.snoozedUntil || new Date(r.snoozedUntil).getTime() <= now);
    if (s.priorityOnly && r.priority === "NORMAL") return false;
    if (s.q.trim()) return s.listIds.includes(r.id); // server-side search: don't guess
    switch (s.tab) {
      case "unassigned":
        return awake && !r.assignedToId;
      case "mine":
        return awake && r.assignedToId === s.me?.id;
      case "waiting":
        return awake && (r.lastSender === "visitor" || (r.lastSender === null && r.unreadForAgent));
      case "snoozed":
        return r.status === "OPEN" && !!r.snoozedUntil && new Date(r.snoozedUntil).getTime() > now;
      case "closed":
        return r.status === "CLOSED";
      default:
        return true;
    }
  }

  private applyRow(r: InboxRow, recount = true) {
    this.set((s) => {
      const rows = { ...s.rows, [r.id]: r };
      let listIds = s.listIds;
      const inList = listIds.includes(r.id);
      const belongs = this.matchesView(r);
      if (belongs && !inList) listIds = [r.id, ...listIds];
      else if (!belongs && inList) listIds = listIds.filter((id) => id !== r.id);
      if (belongs) {
        // Keep the server's ordering rule: pinned, unread, newest activity.
        listIds = [...listIds].sort((a, b) => {
          const A = rows[a];
          const B = rows[b];
          if (!A || !B) return 0;
          if (A.pinned !== B.pinned) return A.pinned ? -1 : 1;
          if (A.unreadForAgent !== B.unreadForAgent) return A.unreadForAgent ? -1 : 1;
          return A.lastMessageAt < B.lastMessageAt ? 1 : A.lastMessageAt > B.lastMessageAt ? -1 : 0;
        });
      }
      return { rows, listIds };
    });
    if (recount) this.scheduleCounts();
  }

  private countsTimer: ReturnType<typeof setTimeout> | null = null;
  private scheduleCounts() {
    if (this.countsTimer) return;
    this.countsTimer = setTimeout(() => {
      this.countsTimer = null;
      void this.refreshList(true);
    }, 1500);
  }

  /* ---------------- threads ---------------- */

  /** A pane mounted for this conversation. Returns the release function. */
  openThread(id: string): () => void {
    this.open.set(id, (this.open.get(id) ?? 0) + 1);
    if (!this.state.threads[id]?.loaded) void this.loadLatest(id);
    if (!this.state.rows[id]) void this.loadRow(id);
    return () => {
      const n = (this.open.get(id) ?? 1) - 1;
      if (n <= 0) this.open.delete(id);
      else this.open.set(id, n);
    };
  }

  async loadRow(id: string) {
    try {
      const d = await j<{ conversation: InboxRow | null; visitorOnline: boolean; viewers: { staffId: string; name: string }[]; visitorTyping: boolean }>(
        `/api/admin/chat/conversations/${encodeURIComponent(id)}`,
      );
      if (d.conversation) this.applyRow(d.conversation, false);
      this.set((s) => ({
        visitorsOnline: { ...s.visitorsOnline, [id]: d.visitorOnline },
        viewers: { ...s.viewers, [id]: d.viewers },
        visitorTyping: { ...s.visitorTyping, [id]: d.visitorTyping ? Date.now() + TYPING_MS : 0 },
      }));
    } catch {
      /* not found / out of scope — pane shows its own message */
    }
  }

  private patchThread(id: string, fn: (t: Thread) => Partial<Thread>) {
    this.set((s) => {
      const t = s.threads[id] ?? { messages: [], hasMore: false, loaded: false, loadingOlder: false };
      return { threads: { ...s.threads, [id]: { ...t, ...fn(t) } } };
    });
  }

  async loadLatest(id: string) {
    try {
      const d = await j<{ messages: StaffChatMessage[]; hasMore: boolean }>(`/api/admin/chat/conversations/${encodeURIComponent(id)}/messages`);
      this.patchThread(id, (t) => ({ messages: mergeMessages(t.messages, d.messages), hasMore: d.hasMore, loaded: true }));
    } catch {
      this.patchThread(id, () => ({ loaded: true }));
    }
  }

  async loadOlder(id: string) {
    const t = this.state.threads[id];
    if (!t || t.loadingOlder || !t.hasMore) return;
    const first = t.messages.find((m) => !m.local);
    if (!first) return;
    this.patchThread(id, () => ({ loadingOlder: true }));
    try {
      const d = await j<{ messages: StaffChatMessage[]; hasMore: boolean }>(
        `/api/admin/chat/conversations/${encodeURIComponent(id)}/messages?before=${encodeURIComponent(first.id)}`,
      );
      this.patchThread(id, (cur) => ({ messages: mergeMessages(cur.messages, d.messages), hasMore: d.hasMore, loadingOlder: false }));
    } catch {
      this.patchThread(id, () => ({ loadingOlder: false }));
    }
  }

  private async backfill(id: string) {
    const t = this.state.threads[id];
    if (!t?.loaded) return this.loadLatest(id);
    const last = lastConfirmed(t.messages);
    if (!last) return this.loadLatest(id);
    try {
      const d = await j<{ messages: StaffChatMessage[]; hasMore: boolean }>(
        `/api/admin/chat/conversations/${encodeURIComponent(id)}/messages?after=${encodeURIComponent(last.id)}`,
      );
      if (d.hasMore) return this.loadLatest(id); // missed a lot: reload the latest page
      if (d.messages.length) this.patchThread(id, (cur) => ({ messages: mergeMessages(cur.messages, d.messages) }));
    } catch {
      /* next resync */
    }
  }

  private applyMessage(m: StaffChatMessage) {
    const t = this.state.threads[m.conversationId];
    if (t) this.patchThread(m.conversationId, (cur) => ({ messages: mergeMessages(cur.messages, [m]) }));
    if (m.sender === "visitor") {
      this.set((s) => ({ visitorTyping: { ...s.visitorTyping, [m.conversationId]: 0 } }));
    }
    for (const h of this.messageHooks) {
      try {
        h(m, this.state.rows[m.conversationId]);
      } catch {
        /* ignore */
      }
    }
  }

  /* ---------------- writes ---------------- */

  async send(id: string, input: { body: string; internal: boolean; file?: File | null }) {
    const clientId = newClientId();
    const previewUrl = input.file ? URL.createObjectURL(input.file) : null;
    const me = this.state.me;
    const optimistic: UiMessage = {
      id: `local_${clientId}`,
      conversationId: id,
      sender: "agent",
      body: input.body.trim(),
      createdAt: new Date().toISOString(),
      cards: null,
      attachment: null,
      internal: input.internal,
      authorId: me?.id ?? null,
      authorName: me?.name ?? null,
      clientId,
      local: "sending",
      file: input.file ?? null,
      previewUrl,
    };
    this.patchThread(id, (t) => ({ messages: [...t.messages, optimistic] }));
    await this.deliver(id, optimistic);
  }

  async retry(id: string, clientId: string) {
    const m = this.state.threads[id]?.messages.find((x) => x.local && x.clientId === clientId);
    if (!m) return;
    this.patchThread(id, (t) => ({ messages: setLocalState(t.messages, clientId, "sending") }));
    await this.deliver(id, m);
  }

  discard(id: string, clientId: string) {
    const m = this.state.threads[id]?.messages.find((x) => x.local && x.clientId === clientId);
    if (m?.previewUrl) URL.revokeObjectURL(m.previewUrl);
    this.patchThread(id, (t) => ({ messages: dropLocal(t.messages, clientId) }));
  }

  private async deliver(id: string, m: UiMessage): Promise<void> {
    const url = `/api/admin/chat/conversations/${encodeURIComponent(id)}/messages`;
    try {
      let init: RequestInit;
      if (m.file) {
        const fd = new FormData();
        fd.append("file", m.file);
        fd.append("body", m.body);
        fd.append("internal", m.internal ? "1" : "0");
        fd.append("clientId", m.clientId ?? "");
        init = { method: "POST", body: fd };
      } else {
        init = {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ body: m.body, internal: m.internal, clientId: m.clientId }),
        };
      }
      const d = await j<{ message: StaffChatMessage | null }>(url, init);
      if (d.message) {
        if (m.previewUrl) URL.revokeObjectURL(m.previewUrl);
        this.patchThread(id, (t) => ({ messages: mergeMessages(t.messages, [d.message as StaffChatMessage]) }));
      }
    } catch (e) {
      this.patchThread(id, (t) => ({ messages: setLocalState(t.messages, m.clientId ?? "", "failed") }));
      throw e;
    }
  }

  async action(id: string, action: string, args: Record<string, unknown> = {}): Promise<void> {
    const d = await j<{ conversation?: InboxRow | null }>(`/api/admin/chat/conversations/${encodeURIComponent(id)}/actions`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action, ...args }),
    });
    if (d.conversation) this.applyRow(d.conversation);
  }

  private lastTyping = new Map<string, number>();
  typing(id: string) {
    const now = Date.now();
    if (now - (this.lastTyping.get(id) ?? 0) < 2500) return;
    this.lastTyping.set(id, now);
    void this.action(id, "typing").catch(() => {});
  }

  private lastRead = new Map<string, number>();
  markRead(id: string) {
    const row = this.state.rows[id];
    const now = Date.now();
    if (now - (this.lastRead.get(id) ?? 0) < 3000) return;
    if (row && !row.unreadForAgent && row.agentLastReadAt && row.agentLastReadAt >= row.lastMessageAt) return;
    this.lastRead.set(id, now);
    void this.action(id, "read").catch(() => {});
  }
}

/* ---------------- React bindings ---------------- */

const Ctx = createContext<StaffChatStore | null>(null);

export function StaffChatProvider({ children, initialTab }: { children: ReactNode; initialTab?: InboxTab }) {
  const ref = useRef<StaffChatStore | null>(null);
  if (!ref.current) ref.current = new StaffChatStore(initialTab);
  useEffect(() => {
    const s = ref.current!;
    s.start();
    return () => s.stop();
  }, []);
  return <Ctx.Provider value={ref.current}>{children}</Ctx.Provider>;
}

export function useStaffChatStore(): StaffChatStore {
  const s = useContext(Ctx);
  if (!s) throw new Error("useStaffChatStore must be used inside <StaffChatProvider>");
  return s;
}

/** Optional variant for components that may render outside a provider. */
export function useMaybeStaffChatStore(): StaffChatStore | null {
  return useContext(Ctx);
}

export function useChatState(): ChatState {
  const s = useStaffChatStore();
  return useSyncExternalStore(s.subscribe, s.getSnapshot, s.getSnapshot);
}

