    <span className="flex items-center gap-1" aria-hidden>
      {[0, 150, 300].map((d) => (
        <span key={d} className="h-1.5 w-1.5 rounded-full bg-brand-300 motion-safe:animate-pulse" style={{ animationDelay: `${d}ms`, animationDuration: "1s" }} />
      ))}
    </span>
  );
}

export function Chip({ children, tone = "slate", title }: { children: ReactNode; tone?: "slate" | "brand" | "cyan" | "amber" | "red" | "green"; title?: string }) {
  const cls: Record<string, string> = {
    slate: "border-white/10 bg-white/[0.05] text-slate-300",
    brand: "border-brand-400/30 bg-brand-500/10 text-brand-200",
    cyan: "border-cyan-400/30 bg-cyan-500/10 text-cyan-300",
    amber: "border-amber-400/30 bg-amber-500/10 text-amber-300",
    red: "border-red-400/30 bg-red-500/10 text-red-300",
    green: "border-emerald-400/30 bg-emerald-500/10 text-emerald-300",
  };
  return (
    <span title={title} className={`inline-flex items-center gap-1 whitespace-nowrap rounded-full border px-1.5 py-[1px] text-[10px] font-medium ${cls[tone]}`}>
      {children}
    </span>
  );
}

export function Avatar({ name, tone = "visitor", size = 28 }: { name: string | null | undefined; tone?: "visitor" | "agent" | "bot"; size?: number }) {
  const bg =
    tone === "bot"
      ? "bg-gradient-to-br from-brand-500 to-accent-blue"
      : tone === "agent"
        ? "bg-gradient-to-br from-cyan-500 to-brand-500"
        : "bg-white/[0.08] text-slate-200";
  return (
    <span className={`grid flex-none place-items-center rounded-full text-[10px] font-semibold ${tone === "visitor" ? "" : "text-white"} ${bg}`} style={{ width: size, height: size }} aria-hidden>
      {tone === "bot" ? <Ico name="bot" size={Math.round(size * 0.5)} /> : initials(name)}
    </span>
  );
}

export const PRIORITY_TONE: Record<string, "slate" | "amber" | "red"> = { NORMAL: "slate", HIGH: "amber", URGENT: "red" };

