"use client";

import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ClipboardEvent } from "react";
import { CannedReplyPicker } from "@/components/support/CannedReplyPicker";
import { listCannedReplies, type CannedReplyItem } from "@/lib/actions-canned-replies";
import { useVoiceDictation } from "@/components/customer/claude-code/voice";
import { applyCannedVars } from "@/lib/chat/merge";
import type { InboxRow } from "@/lib/chat/types";
import { useStaffChatStore } from "./store";
import { OfferComposer } from "./optional";
import { Ico } from "./ui";

/**
 * Staff reply box shared by the workspace panes and the dock windows.
 *
 *  - Reply vs Internal note (Alt+N). Notes are staff-only (lib/chat/visibility.ts).
 *  - Canned replies: the full picker, plus "/" quick insert at the start of the
 *    box. Variables {name} {first_name} {email} {agent} {agent_name} are filled
 *    from this conversation and the signed-in agent.
 *  - Images: button, paste, or drop anywhere on the pane (via `acceptFile`).
 *  - Drafts are kept per conversation (sessionStorage) so switching between
