"use client";

/**
 * Persistent chat-dock state, in localStorage so it survives FULL page loads —
 * starting/ending impersonation is a hard navigation (window.location.assign),
 * and the dock must come back with the same chats open on the other side.
 *
 * Per-browser, per-admin convenience state only: it holds conversation IDS,
 * never message content. Every id is re-authorized server-side when the dock
 * loads it (and while impersonating, only the impersonated customer's own
 * conversations load at all — see lib/chat/staff-auth.ts).
 */

const KEY = "nxeon.chatdock.v1";
const RETURN_KEY = "nxeon.chat.impReturn";
const EVT = "nxeon:chatdock";
export const MAX_DOCK = 3;

export type DockState = { open: string[]; minimized: string[]; collapsed: boolean };

const EMPTY: DockState = { open: [], minimized: [], collapsed: false };

function valid(id: unknown): id is string {
  return typeof id === "string" && /^[a-z0-9]{8,40}$/i.test(id);
}

export function readDock(): DockState {
  try {
    const raw = JSON.parse(localStorage.getItem(KEY) ?? "null") as Partial<DockState> | null;
    if (!raw) return EMPTY;
    const open = (Array.isArray(raw.open) ? raw.open : []).filter(valid).slice(-MAX_DOCK);
    return {
      open,
      minimized: (Array.isArray(raw.minimized) ? raw.minimized : []).filter((id) => open.includes(id as string)) as string[],
      collapsed: !!raw.collapsed,
    };
  } catch {
    return EMPTY;
  }
}

export function writeDock(s: DockState): void {
  try {
    localStorage.setItem(KEY, JSON.stringify(s));
  } catch {
    /* storage blocked: dock still works for this page view */
  }
  try {
    window.dispatchEvent(new CustomEvent(EVT, { detail: s }));
  } catch {
    /* ignore */
  }
}

export function onDockChange(fn: (s: DockState) => void): () => void {
  const h = (e: Event) => fn((e as CustomEvent<DockState>).detail ?? readDock());
  const st = (e: StorageEvent) => {
    if (e.key === KEY) fn(readDock());
  };
  window.addEventListener(EVT, h);
  window.addEventListener("storage", st);
  return () => {
    window.removeEventListener(EVT, h);
    window.removeEventListener("storage", st);
  };
}

/** Open (or focus) a conversation in the dock from anywhere in the admin UI. */
export function openInDock(id: string): void {
  if (!valid(id)) return;
  const s = readDock();
  const open = [...s.open.filter((x) => x !== id), id].slice(-MAX_DOCK);
  writeDock({ open, minimized: s.minimized.filter((x) => x !== id && open.includes(x)), collapsed: false });
}

export function closeInDock(id: string): void {
  const s = readDock();
  writeDock({ ...s, open: s.open.filter((x) => x !== id), minimized: s.minimized.filter((x) => x !== id) });
}

export function toggleMinimized(id: string): void {
  const s = readDock();
  const min = s.minimized.includes(id) ? s.minimized.filter((x) => x !== id) : [...s.minimized, id];
  writeDock({ ...s, minimized: min });
}

/** Remember which chat an impersonation was started from, so "Leave" lands back on it. */
export function rememberImpersonationReturn(conversationId: string): void {
  try {
    localStorage.setItem(RETURN_KEY, JSON.stringify({ id: conversationId, at: Date.now() }));
  } catch {
    /* ignore */
  }
}

/**
 * Where "Leave impersonation" should go: back to the chat it started from (if
 * it started from one in the last 2 h — the impersonation grant's own
 * lifetime), else the caller's default. Consumes the marker.
 */
export function takeImpersonationReturn(fallback: string): string {
  try {
    const raw = JSON.parse(localStorage.getItem(RETURN_KEY) ?? "null") as { id?: unknown; at?: unknown } | null;
    localStorage.removeItem(RETURN_KEY);
    if (raw && valid(raw.id) && typeof raw.at === "number" && Date.now() - raw.at < 2 * 3600_000) {
      return `/admin/chat?c=${encodeURIComponent(raw.id)}`;
    }
  } catch {
    /* ignore */
  }
  return fallback;
}

