"use client";

import Link from "next/link";
import { Fragment, useEffect, useLayoutEffect, useMemo, useRef, useState, useTransition, type DragEvent } from "react";
import { LightboxImage } from "@/components/ui/LightboxImage";
import { UserName } from "@/components/ui/UserName";
import { ChatCards } from "@/components/chat/cards/registry";
import { impersonateFromChat, transferChatToTicket } from "@/lib/actions-chat";
import { useChatState, useStaffChatStore, type UiMessage } from "./store";
import { Composer, type ComposerHandle } from "./Composer";
import { openInDock, rememberImpersonationReturn, readDock, writeDock } from "./dock-state";
import { Avatar, Chip, Ico, PRIORITY_TONE, TypingDots, clock, dayLabel, rowLabel, timeAgo } from "./ui";

/**
 * One live conversation: header + actions, paginated history (infinite scroll
 * up), typing / AI-step / read receipts, and the composer. Used three ways:
 * a workspace column, one of several side-by-side workspace columns, and a
 * dock window (`variant="dock"`), all fed by the same store and stream.
 */

type Staff = { id: string; name: string };
let staffCache: Promise<Staff[]> | null = null;
function loadStaff(): Promise<Staff[]> {
  if (!staffCache) {
    staffCache = fetch("/api/admin/chat/staff", { cache: "no-store" })
      .then((r) => (r.ok ? r.json() : { staff: [] }))
      .then((d: { staff?: Staff[] }) => d.staff ?? [])
      .catch(() => []);
  }
  return staffCache;
}

const SNOOZES: { label: string; minutes: number }[] = [
  { label: "30 minutes", minutes: 30 },
  { label: "2 hours", minutes: 120 },
  { label: "Tomorrow", minutes: 60 * 18 },
  { label: "3 days", minutes: 60 * 72 },
];

function Menu({ label, icon, children, align = "right" }: { label: string; icon: string; children: (close: () => void) => React.ReactNode; align?: "left" | "right" }) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const d = (e: MouseEvent) => ref.current && !ref.current.contains(e.target as Node) && setOpen(false);
    const k = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    document.addEventListener("mousedown", d);
    document.addEventListener("keydown", k);
    return () => {
      document.removeEventListener("mousedown", d);
      document.removeEventListener("keydown", k);
    };
  }, [open]);
  return (
    <div ref={ref} className="relative">
      <button
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        title={label}
        aria-label={label}
        onClick={() => setOpen((v) => !v)}
        className="grid h-7 w-7 place-items-center rounded-lg text-slate-400 hover:bg-white/[0.07] hover:text-slate-100"
      >
        <Ico name={icon} size={15} />
      </button>
      {open && (
        <div role="menu" className={`absolute top-full z-30 mt-1 min-w-[12rem] rounded-xl border border-white/10 bg-[var(--adm-surface,#0b1226)] p-1 shadow-2xl ${align === "right" ? "right-0" : "left-0"}`}>
          {children(() => setOpen(false))}
        </div>
      )}
    </div>
  );
}

function MenuItem({ onClick, children, tone }: { onClick: () => void; children: React.ReactNode; tone?: "danger" }) {
  return (
    <button
      type="button"
      role="menuitem"
      onClick={onClick}
      className={`flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-left text-xs ${tone === "danger" ? "text-red-300 hover:bg-red-500/10" : "text-slate-200 hover:bg-white/[0.06]"}`}
    >
      {children}
    </button>
  );
}

export function ThreadPane({
  id,
  variant = "workspace",
  focused = true,
  onClose,
  onFocus,
  contextOpen,
  onToggleContext,
  onMinimize,
  minimized = false,
}: {
  id: string;
  variant?: "workspace" | "dock";
  focused?: boolean;
  onClose?: () => void;
  onFocus?: () => void;
  contextOpen?: boolean;
  onToggleContext?: () => void;
  onMinimize?: () => void;
  minimized?: boolean;
}) {
  const store = useStaffChatStore();
  const s = useChatState();
  const row = s.rows[id] ?? null;
  const thread = s.threads[id];
  const me = s.me;
  const dock = variant === "dock";
  const [err, setErr] = useState("");
  const [pending, start] = useTransition();
  const [staff, setStaff] = useState<Staff[]>([]);
  const [dragging, setDragging] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const topRef = useRef<HTMLDivElement>(null);
  const atBottom = useRef(true);
  const prevHeight = useRef<number | null>(null);
  const composerRef = useRef<ComposerHandle>(null);
  const [, tick] = useState(0);

  useEffect(() => store.openThread(id), [store, id]);

  // Collision hint: tell teammates we're looking at this thread (heartbeat
  // keeps it alive; the server expires it after 45 s without one).
  useEffect(() => {
    if (minimized) return;
    const on = () => void store.action(id, "viewing", { on: true }).catch(() => {});
    on();
    const t = setInterval(on, 30_000);
    return () => {
      clearInterval(t);
      void store.action(id, "viewing", { on: false }).catch(() => {});
    };
  }, [store, id, minimized]);

  // Re-render every 30 s so "2m" style stamps stay true.
  useEffect(() => {
    const t = setInterval(() => tick((n) => n + 1), 30_000);
    return () => clearInterval(t);
  }, []);

  const messages = thread?.messages ?? [];
  const lastId = messages[messages.length - 1]?.id;

  // Read receipt: an open, focused, visible pane reads what arrives.
  useEffect(() => {
    if (!focused || minimized || !thread?.loaded) return;
    if (typeof document !== "undefined" && document.visibilityState !== "visible") return;
    store.markRead(id);
  }, [store, id, focused, minimized, thread?.loaded, lastId, row?.unreadForAgent]);

  // Scroll: follow new messages when pinned to the bottom; keep position when
  // older history is prepended.
  useLayoutEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    if (prevHeight.current !== null) {
      el.scrollTop += el.scrollHeight - prevHeight.current;
      prevHeight.current = null;
    } else if (atBottom.current) {
      el.scrollTop = el.scrollHeight;
    }
  }, [messages.length, lastId, minimized]);

  useEffect(() => {
    atBottom.current = true;
  }, [id]);

  // Infinite scroll up.
  useEffect(() => {
    const root = scrollRef.current;
    const top = topRef.current;
    if (!root || !top || !thread?.hasMore) return;
    const io = new IntersectionObserver(
      (es) => {
        if (es.some((e) => e.isIntersecting) && thread?.hasMore && !thread.loadingOlder) {
          prevHeight.current = root.scrollHeight;
          void store.loadOlder(id);
        }
      },
      { root, rootMargin: "200px 0px 0px 0px" },
    );
    io.observe(top);
    return () => io.disconnect();
  }, [store, id, thread?.hasMore, thread?.loadingOlder]);

  const typing = (s.visitorTyping[id] ?? 0) > Date.now();
  const botStep = s.botStep[id] ?? null;
  const viewers = (s.viewers[id] ?? []).filter((v) => v.staffId !== me?.id);
  const online = !!s.visitorsOnline[id];

  const lastAgentConfirmed = useMemo(() => {
    for (let i = messages.length - 1; i >= 0; i--) {
      const m = messages[i];
      if (m.sender === "agent" && !m.internal && !m.local) return m.id;
    }
    return null;
  }, [messages]);

  function run(fn: () => Promise<unknown>) {
    setErr("");
    start(async () => {
      try {
        await fn();
      } catch (e) {
        setErr((e as Error).message || "Something went wrong.");
      }
    });
  }

  function viewAsCustomer() {
    if (!row?.userId) return;
    if (!window.confirm(`View the portal as ${rowLabel(row)}? This chat stays open in the staff dock while you do.`)) return;
    run(async () => {
      const r = await impersonateFromChat(id);
      if (r.error) throw new Error(r.error);
      // The dock carries this chat into the impersonated view; "Leave" returns here.
      const d = readDock();
      writeDock({ open: [...d.open.filter((x) => x !== id), id].slice(-3), minimized: d.minimized.filter((x) => x !== id), collapsed: false });
      rememberImpersonationReturn(id);
      window.location.assign("/dashboard");
    });
  }

  function toTicket() {
    if (!window.confirm("Transfer this conversation to a support ticket? The chat will be closed.")) return;
    run(async () => {
      const r = await transferChatToTicket(id);
      if (r?.error) throw new Error(r.error);
    });
  }

  function onDrop(e: DragEvent) {
    e.preventDefault();
    setDragging(false);
    const f = Array.from(e.dataTransfer.files ?? []).find((x) => x.type.startsWith("image/"));
    if (f) composerRef.current?.acceptFile(f);
  }

  const label = rowLabel(row);
  const closed = row?.status === "CLOSED";
  const snoozed = !!row?.snoozedUntil && new Date(row.snoozedUntil).getTime() > Date.now();
  const canImpersonate = !s.scoped && me?.role === "ADMIN" && !!row?.userId;

  /* ----------------------------- header ----------------------------- */
  const header = (
    <div className={`flex items-center gap-2 border-b border-white/10 ${dock ? "px-2.5 py-2" : "px-3.5 py-2.5"}`} onClick={dock ? onFocus : undefined}>
      <div className="relative">
        <Avatar name={label} size={dock ? 26 : 32} />
        <span
          className={`absolute -bottom-0.5 -right-0.5 h-2.5 w-2.5 rounded-full ring-2 ring-[var(--adm-surface,#0b1226)] ${online ? "bg-emerald-400" : "bg-slate-600"}`}
          title={online ? "Customer has the chat open" : "Customer is not viewing the chat"}
        />
      </div>
      <div className="min-w-0 flex-1">
        <p className="flex items-center gap-1.5 truncate text-sm font-semibold text-slate-100">
          {row?.userId && !s.scoped && !dock ? (
            <Link href={`/admin/users/${row.userId}`} className="truncate hover:text-brand-300">
              <UserName name={label} creator={!!row?.isCreator} />
            </Link>
          ) : (
            <span className="truncate">
              <UserName name={label} creator={!!row?.isCreator} />
            </span>
          )}
          {row?.pinned && <Ico name="pin" size={12} className="flex-none text-brand-300" />}
          {row && row.priority !== "NORMAL" && <Chip tone={PRIORITY_TONE[row.priority]}>{row.priority.toLowerCase()}</Chip>}
        </p>
        <p className="truncate text-[11px] text-slate-400">
          {typing ? (
            <span className="text-cyan-300">typing…</span>
          ) : (
            <>
              {row?.email || "no email"} · {row?.userId ? "customer" : "guest"}
              {closed ? " · closed" : snoozed ? ` · snoozed ${timeAgo(new Date().toISOString())}` : ""}
              {row?.assignedToName ? ` · ${row.assignedToId === me?.id ? "you" : row.assignedToName}` : " · unassigned"}
            </>
          )}
        </p>
      </div>

      <div className="flex flex-none items-center gap-0.5">
        {!dock && row && !row.assignedToId && !closed && (
          <button type="button" onClick={() => run(() => store.action(id, "assign"))} disabled={pending} className="mr-1 rounded-lg border border-brand-400/30 bg-brand-500/10 px-2 py-1 text-[11px] font-medium text-brand-100 hover:bg-brand-500/20">
            Claim
          </button>
        )}
        {!dock && (
          <button
            type="button"
            onClick={() => run(() => store.action(id, "ai", { paused: !row?.aiPaused }))}
            title={row?.aiPaused ? "AI assistant paused on this thread — click to resume" : "AI assistant may answer — click to pause"}
            className={`mr-1 rounded-lg border px-2 py-1 text-[11px] font-medium ${row?.aiPaused ? "border-amber-400/30 bg-amber-500/10 text-amber-300" : "border-white/10 text-slate-300 hover:bg-white/[0.06]"}`}
          >
            AI {row?.aiPaused ? "paused" : "on"}
          </button>
        )}
        {!closed ? (
          <button type="button" title="Close conversation" aria-label="Close conversation" onClick={() => run(() => store.action(id, "close"))} className="grid h-7 w-7 place-items-center rounded-lg text-slate-400 hover:bg-white/[0.07] hover:text-emerald-300">
            <Ico name="check" size={15} />
          </button>
        ) : (
          <button type="button" title="Reopen" aria-label="Reopen conversation" onClick={() => run(() => store.action(id, "reopen"))} className="grid h-7 w-7 place-items-center rounded-lg text-slate-400 hover:bg-white/[0.07] hover:text-slate-100">
            <Ico name="refresh" size={14} />
          </button>
        )}
        <Menu label="Snooze" icon="clock">
          {(close) => (
            <>
              {SNOOZES.map((z) => (
                <MenuItem key={z.minutes} onClick={() => (close(), run(() => store.action(id, "snooze", { minutes: z.minutes })))}>
                  Snooze {z.label}
                </MenuItem>
              ))}
              {snoozed && <MenuItem onClick={() => (close(), run(() => store.action(id, "unsnooze")))}>Wake now</MenuItem>}
              <p className="px-2.5 pb-1 pt-1.5 text-[10px] text-slate-500">A new customer message always wakes it.</p>
            </>
          )}
        </Menu>
        <Menu label="More actions" icon="more">
          {(close) => (
            <>
              <MenuItem onClick={() => (close(), run(() => store.action(id, "assign")))}>
                <Ico name="user" size={13} /> Assign to me
              </MenuItem>
              <TransferItems id={id} staff={staff} load={() => loadStaff().then(setStaff)} onPick={(sid) => (close(), run(() => store.action(id, "assign", { staffId: sid })))} meId={me?.id} />
              {row?.assignedToId && (
                <MenuItem onClick={() => (close(), run(() => store.action(id, "assign", { staffId: null })))}>Unassign</MenuItem>
              )}
              <div className="my-1 border-t border-white/10" />
              <MenuItem onClick={() => (close(), run(() => store.action(id, "pin", { on: !row?.pinned })))}>
                <Ico name="pin" size={13} /> {row?.pinned ? "Unpin" : "Pin to top"}
              </MenuItem>
              {(["NORMAL", "HIGH", "URGENT"] as const).map((p) => (
                <MenuItem key={p} onClick={() => (close(), run(() => store.action(id, "priority", { value: p })))}>
                  <span className={`h-2 w-2 rounded-full ${p === "URGENT" ? "bg-red-400" : p === "HIGH" ? "bg-amber-400" : "bg-slate-500"}`} />
                  Priority: {p.toLowerCase()} {row?.priority === p ? "✓" : ""}
                </MenuItem>
              ))}
              {dock && (
                <MenuItem onClick={() => (close(), run(() => store.action(id, "ai", { paused: !row?.aiPaused })))}>
                  <Ico name="bot" size={13} /> {row?.aiPaused ? "Resume AI assistant" : "Pause AI assistant"}
                </MenuItem>
              )}
              <div className="my-1 border-t border-white/10" />
              {canImpersonate && (
                <MenuItem onClick={() => (close(), viewAsCustomer())}>
                  <Ico name="eye" size={13} /> View as customer (keeps this chat docked)
                </MenuItem>
              )}
              {!dock && (
                <MenuItem onClick={() => (close(), openInDock(id))}>
                  <Ico name="dock" size={13} /> Pop out to dock
                </MenuItem>
              )}
              {dock && !s.scoped && (
                <Link href={`/admin/chat?c=${id}`} className="flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-left text-xs text-slate-200 hover:bg-white/[0.06]" onClick={close}>
                  <Ico name="expand" size={13} /> Open in inbox
                </Link>
              )}
              {!s.scoped && (
                <MenuItem onClick={() => (close(), toTicket())}>
                  <Ico name="ticket" size={13} /> Transfer to ticket
                </MenuItem>
              )}
            </>
          )}
        </Menu>
        {onToggleContext && (
          <button type="button" title="Customer details" aria-label="Toggle customer details" aria-pressed={contextOpen} onClick={onToggleContext} className={`grid h-7 w-7 place-items-center rounded-lg hover:bg-white/[0.07] ${contextOpen ? "text-brand-300" : "text-slate-400"}`}>
            <Ico name="info" size={15} />
          </button>
        )}
        {onMinimize && (
          <button type="button" title={minimized ? "Expand" : "Minimize"} aria-label={minimized ? "Expand chat" : "Minimize chat"} onClick={(e) => (e.stopPropagation(), onMinimize())} className="grid h-7 w-7 place-items-center rounded-lg text-slate-400 hover:bg-white/[0.07] hover:text-slate-100">
            <Ico name={minimized ? "expand" : "min"} size={14} />
          </button>
        )}
        {onClose && (
          <button type="button" title="Close pane" aria-label="Close pane" onClick={(e) => (e.stopPropagation(), onClose())} className="grid h-7 w-7 place-items-center rounded-lg text-slate-400 hover:bg-white/[0.07] hover:text-slate-100">
            <Ico name="x" size={14} />
          </button>
        )}
      </div>
    </div>
  );

  if (minimized) return <div className="flex flex-col">{header}</div>;

  /* ----------------------------- body ----------------------------- */
  let lastDay = "";
  return (
    <div
      className={`relative flex min-h-0 flex-1 flex-col ${focused ? "" : "opacity-[0.97]"}`}
      onMouseDown={onFocus}
      onDragOver={(e) => {
        if (Array.from(e.dataTransfer.types).includes("Files")) {
          e.preventDefault();
          setDragging(true);
        }
      }}
      onDragLeave={(e) => {
        if (e.currentTarget === e.target) setDragging(false);
      }}
      onDrop={onDrop}
    >
      {header}
      {viewers.length > 0 && (
        <div className="flex items-center gap-1.5 border-b border-white/5 bg-cyan-500/[0.06] px-3 py-1 text-[11px] text-cyan-200">
          <Ico name="eye" size={12} /> {viewers.map((v) => v.name.split(" ")[0]).join(", ")} {viewers.length === 1 ? "is" : "are"} also viewing
        </div>
      )}
      {err && (
        <div className="flex items-center justify-between border-b border-red-400/20 bg-red-500/10 px-3 py-1.5 text-xs text-red-300" role="alert">
          {err}
          <button type="button" onClick={() => setErr("")} aria-label="Dismiss" className="text-red-300/70 hover:text-red-200">
            <Ico name="x" size={12} />
          </button>
        </div>
      )}

      <div
        ref={scrollRef}
        onScroll={(e) => {
          const el = e.currentTarget;
          atBottom.current = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
        }}
        className={`min-h-0 flex-1 overflow-y-auto ${dock ? "px-2.5 py-2.5" : "px-4 py-3"}`}
        aria-live="polite"
        aria-label={`Conversation with ${label}`}
      >
        <div ref={topRef} />
        {thread?.loadingOlder && <p className="py-2 text-center text-[11px] text-slate-500">Loading earlier messages…</p>}
        {thread && !thread.hasMore && thread.loaded && messages.length > 0 && (
          <p className="pb-3 text-center text-[10px] uppercase tracking-wide text-slate-600">Start of conversation</p>
        )}
        {!thread?.loaded && (
          <div className="space-y-2 py-4" aria-hidden>
            {[60, 40, 70].map((w, i) => (
              <div key={i} className={`h-8 animate-pulse rounded-2xl bg-white/[0.05] ${i % 2 ? "ml-auto" : ""}`} style={{ width: `${w}%` }} />
            ))}
          </div>
        )}
        <div className="space-y-2.5">
          {messages.map((m) => {
            const d = dayLabel(m.createdAt);
            const showDay = d !== lastDay;
            lastDay = d;
            return (
              <Fragment key={m.clientId && m.local ? `l-${m.clientId}` : m.id}>
                {showDay && (
                  <div className="flex items-center gap-2 py-1 text-[10px] uppercase tracking-wide text-slate-500">
                    <span className="h-px flex-1 bg-white/10" />
                    {d}
                    <span className="h-px flex-1 bg-white/10" />
                  </div>
                )}
                <Bubble
                  m={m}
                  label={label}
                  compact={dock}
                  seen={m.id === lastAgentConfirmed ? (row?.userLastReadAt ? row.userLastReadAt >= m.createdAt : false) : null}
                  onRetry={() => m.clientId && void store.retry(id, m.clientId)}
                  onDiscard={() => m.clientId && store.discard(id, m.clientId)}
                />
              </Fragment>
            );
          })}
        </div>
        {(typing || botStep) && (
          <div className="mt-2.5 flex items-center gap-2" aria-live="polite">
            <div className="flex items-center gap-2 rounded-2xl border border-white/10 bg-white/[0.05] px-3 py-2">
              <TypingDots />
              <span className="text-[11px] text-slate-400">{typing ? `${label} is typing…` : `AI: ${botStep}`}</span>
            </div>
          </div>
        )}
      </div>

      {row?.botEscalatedAt && !row.assignedToId && (
        <div className="border-t border-cyan-400/20 bg-cyan-500/[0.07] px-3 py-1.5 text-[11px] text-cyan-200">
          The AI handed this visitor to a human {timeAgo(row.botEscalatedAt)} ago — reply or claim to take over.
        </div>
      )}
      <Composer ref={composerRef} row={row} conversationId={id} compact={dock} />

      {dragging && (
        <div className="pointer-events-none absolute inset-0 z-20 grid place-items-center rounded-[inherit] border-2 border-dashed border-brand-400/60 bg-brand-500/10 text-sm font-medium text-brand-100">
          Drop image to attach
        </div>
      )}
    </div>
  );
}

function TransferItems({ id, staff, load, onPick, meId }: { id: string; staff: Staff[]; load: () => void; onPick: (id: string) => void; meId?: string }) {
  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);
  const others = staff.filter((s) => s.id !== meId);
  if (!others.length) return null;
  return (
    <>
      <p className="px-2.5 pb-0.5 pt-1.5 text-[10px] uppercase tracking-wide text-slate-500">Transfer to</p>
      <div className="max-h-40 overflow-y-auto">
        {others.map((s) => (
          <MenuItem key={s.id} onClick={() => onPick(s.id)}>
            <span className="grid h-5 w-5 place-items-center rounded-full bg-white/[0.08] text-[9px]">{s.name.slice(0, 1).toUpperCase()}</span>
            {s.name}
          </MenuItem>
        ))}
      </div>
    </>
  );
}

function Bubble({
  m,
  label,
  compact,
  seen,
  onRetry,
  onDiscard,
}: {
  m: UiMessage;
  label: string;
  compact: boolean;
  seen: boolean | null;
  onRetry: () => void;
  onDiscard: () => void;
}) {
  const visitor = m.sender === "visitor";
  const bot = m.sender === "bot";
  const note = m.internal;
  const who = visitor ? label : bot ? "Nxeon Assistant · AI" : `${m.authorName ?? "Support"}${note ? " · internal note" : ""}`;
  const bubble = note
    ? "border border-dashed border-amber-400/40 bg-amber-500/[0.08] text-amber-50"
    : visitor
      ? "border border-white/10 bg-white/[0.06] text-slate-100"
      : bot
        ? "border border-brand-400/30 bg-brand-500/10 text-slate-100"
        : "bg-gradient-to-br from-brand-500 to-brand-600 text-white";
  const img = m.attachment
    ? { thumb: `/api/chat/attachment/${m.attachment.id}?size=thumb`, full: `/api/chat/attachment/${m.attachment.id}` }
    : null;
  return (
    <div className={`flex flex-col ${visitor ? "items-start" : "items-end"}`}>
      <span className={`mb-0.5 flex items-center gap-1 px-1 text-[10.5px] font-medium ${note ? "text-amber-300" : bot ? "text-brand-300" : visitor ? "text-slate-400" : "text-brand-200"}`}>
        {note && <Ico name="lock" size={10} />}
        {bot && <Ico name="bot" size={10} />}
        {who}
      </span>
      <div className={`${compact ? "max-w-[88%]" : "max-w-[78%]"} space-y-1.5 whitespace-pre-wrap break-words rounded-2xl px-3 py-2 text-sm ${bubble} ${m.local === "sending" ? "opacity-70" : ""}`}>
        {img && (
          <LightboxImage
            src={img.thumb}
            fullSrc={img.full}
            width={m.attachment?.width}
            height={m.attachment?.height}
            alt="Image attachment"
            className="h-auto max-h-56 w-auto max-w-full rounded-lg border border-white/10 object-contain"
          />
        )}
        {!img && m.local && m.previewUrl && (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={m.previewUrl} alt="Sending image" className="max-h-56 max-w-full rounded-lg border border-white/10 object-contain" />
        )}
        {m.body && <div>{m.body}</div>}
      </div>
      {m.cards && m.cards.length > 0 && (
        <div className={`flex w-full flex-col ${visitor ? "items-start" : "items-end"}`}>
          <ChatCards cards={m.cards} viewer="admin" />
        </div>
      )}
      <span className="mt-0.5 flex items-center gap-1.5 px-1 text-[10px] text-slate-500">
        {m.local === "sending" && "Sending…"}
        {m.local === "failed" && (
          <span className="flex items-center gap-1.5 text-red-300">
            Not sent.
            <button type="button" onClick={onRetry} className="underline hover:text-red-200">Retry</button>
            <button type="button" onClick={onDiscard} className="underline hover:text-red-200">Discard</button>
          </span>
        )}
        {!m.local && clock(m.createdAt)}
        {!m.local && seen !== null && (
          <span className={`flex items-center gap-0.5 ${seen ? "text-cyan-300" : ""}`} title={seen ? "The customer has seen this" : "Delivered — not seen yet"}>
            <Ico name={seen ? "checks" : "check"} size={11} /> {seen ? "Seen" : "Delivered"}
          </span>
        )}
      </span>
    </div>
  );
}

