                {r.unreadForAgent && r.status === "OPEN" && <span className="h-2 w-2 flex-none rounded-full bg-amber-400" title="Needs a reply" />}
              </div>
              <div className="mt-1 flex flex-wrap items-center gap-1 pl-3.5">
                {waiting && <Chip tone="amber">waiting</Chip>}
