"use client";

import { useEffect, useRef, useState } from "react";
import { UserName } from "@/components/ui/UserName";
import type { InboxTab } from "@/lib/chat/types";
import { useChatState, useStaffChatStore } from "./store";
import { Chip, Ico, PRIORITY_TONE, TypingDots, rowLabel, timeAgo } from "./ui";

/**
 * Inbox column: tabs (Waiting / Unassigned / Mine / All / Snoozed / Closed)
 * with server-side counts, server-side search, a priority filter, and a
 * lightweight list (one page of rows, preview text only). Live: rows move
 * between tabs as the stream reports changes.
 */

export const TAB_LABEL: Record<InboxTab, string> = {
  waiting: "Waiting",
  unassigned: "Unassigned",
  mine: "Mine",
  all: "All",
  snoozed: "Snoozed",
  closed: "Closed",
};
const TAB_ORDER: InboxTab[] = ["waiting", "unassigned", "mine", "all", "snoozed", "closed"];

export function InboxList({
  selectedId,
  openIds,
  onSelect,
  searchRef,
}: {
  selectedId: string | null;
  openIds: string[];
  onSelect: (id: string, e: React.MouseEvent | React.KeyboardEvent | null) => void;
  searchRef?: React.RefObject<HTMLInputElement | null>;
}) {
  const store = useStaffChatStore();
  const s = useChatState();
  const [q, setQ] = useState(s.q);
  const deb = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [, tick] = useState(0);

  useEffect(() => {
    const t = setInterval(() => tick((n) => n + 1), 30_000);
    return () => clearInterval(t);
  }, []);

  function onSearch(v: string) {
    setQ(v);
    if (deb.current) clearTimeout(deb.current);
    deb.current = setTimeout(() => store.setFilters({ q: v }), 250);
  }

  const now = Date.now();
  return (
    <div className="flex min-h-0 flex-col">
      <div className="space-y-2 border-b border-white/10 p-2.5">
        <div className="relative">
          <Ico name="search" size={14} className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500" />
          <input
            ref={searchRef}
            type="search"
            value={q}
            onChange={(e) => onSearch(e.target.value)}
            placeholder="Search name, email, message…  ( / )"
            aria-label="Search conversations"
            className="input w-full py-1.5 pl-8 pr-2 text-xs"
          />
        </div>
        <div className="flex flex-wrap gap-1" role="tablist" aria-label="Inbox filters">
          {TAB_ORDER.map((t) => {
            const active = s.tab === t;
            const n = s.counts?.[t];
            return (
              <button
                key={t}
                type="button"
                role="tab"
                aria-selected={active}
                onClick={() => store.setFilters({ tab: t })}
                className={`inline-flex items-center gap-1 rounded-lg px-2 py-1 text-[11px] font-medium transition ${active ? "bg-brand-500/20 text-brand-100 ring-1 ring-brand-400/40" : "text-slate-400 hover:bg-white/[0.05] hover:text-slate-200"}`}
              >
                {TAB_LABEL[t]}
                {typeof n === "number" && (
                  <span className={`rounded-full px-1.5 text-[10px] ${active ? "bg-brand-500/30" : "bg-white/[0.07]"} ${t === "waiting" && n > 0 ? "text-amber-200" : ""}`}>{n}</span>
                )}
              </button>
            );
          })}
        </div>
        <label className="flex items-center gap-1.5 px-0.5 text-[11px] text-slate-400">
          <input type="checkbox" checked={s.priorityOnly} onChange={(e) => store.setFilters({ priorityOnly: e.target.checked })} className="accent-brand-500" />
          High / urgent only
        </label>
      </div>

      <div className="min-h-0 flex-1 overflow-y-auto p-1.5" role="listbox" aria-label="Conversations">
        {s.listLoading && s.listIds.length === 0 && (
          <div className="space-y-1.5 p-1" aria-hidden>
            {[0, 1, 2, 3].map((i) => (
              <div key={i} className="h-14 animate-pulse rounded-xl bg-white/[0.04]" />
            ))}
          </div>
        )}
        {!s.listLoading && s.listIds.length === 0 && (
          <p className="p-6 text-center text-sm text-slate-500">{s.q ? `No matches for “${s.q}”.` : s.tab === "waiting" ? "Nobody is waiting. 🎉" : "Nothing here."}</p>
        )}
        {s.listIds.map((id) => {
          const r = s.rows[id];
          if (!r) return null;
          const active = id === selectedId;
          const isOpen = openIds.includes(id);
          const typing = (s.visitorTyping[id] ?? 0) > now;
          const online = !!s.visitorsOnline[id];
          const waiting = r.status === "OPEN" && r.lastSender === "visitor";
          const viewers = (s.viewers[id] ?? []).filter((v) => v.staffId !== s.me?.id);
          return (
            <button
              key={id}
              type="button"
              role="option"
              aria-selected={active}
              data-convo={id}
              onClick={(e) => onSelect(id, e)}
              className={`mb-1 w-full rounded-xl border px-2.5 py-2 text-left transition ${active ? "border-brand-400/50 bg-brand-500/10" : isOpen ? "border-white/10 bg-white/[0.03]" : "border-transparent hover:bg-white/[0.04]"}`}
            >
              <div className="flex items-center gap-1.5">
                <span className={`h-2 w-2 flex-none rounded-full ${online ? "bg-emerald-400" : "bg-transparent"}`} title={online ? "Viewing the chat now" : undefined} />
                <span className={`min-w-0 flex-1 truncate text-[13px] ${r.unreadForAgent ? "font-semibold text-slate-50" : "font-medium text-slate-200"} ${r.status === "CLOSED" ? "opacity-60" : ""}`}>
                  <UserName name={rowLabel(r)} creator={r.isCreator} />
                </span>
                {r.pinned && <Ico name="pin" size={11} className="flex-none text-brand-300" />}
                {r.priority !== "NORMAL" && <Chip tone={PRIORITY_TONE[r.priority]}>{r.priority === "URGENT" ? "!!" : "!"}</Chip>}
                <span className="flex-none text-[10px] text-slate-500">{timeAgo(r.lastMessageAt, now)}</span>
              </div>
              <div className="mt-0.5 flex items-center gap-1.5 pl-3.5">
                {typing ? (
                  <span className="flex items-center gap-1.5 text-[11.5px] text-cyan-300">
                    <TypingDots /> typing…
                  </span>
                ) : (
                  <span className={`min-w-0 flex-1 truncate text-[11.5px] ${r.unreadForAgent ? "text-slate-300" : "text-slate-500"}`}>
                    {r.lastSender === "agent" ? "You: " : r.lastSender === "bot" ? "AI: " : ""}
                    {r.lastPreview || "…"}
                  </span>
                )}
                {r.unreadForAgent && r.status === "OPEN" && <span className="h-2 w-2 flex-none rounded-full bg-amber-400" title="Needs a reply" />}
              </div>
              <div className="mt-1 flex flex-wrap items-center gap-1 pl-3.5">
                {waiting && <Chip tone="amber">waiting</Chip>}
                {r.botEscalatedAt && !r.assignedToId && <Chip tone="cyan">wants a human</Chip>}
                {r.assignedToName ? (
                  <Chip tone={r.assignedToId === s.me?.id ? "brand" : "slate"}>{r.assignedToId === s.me?.id ? "mine" : r.assignedToName.split(" ")[0]}</Chip>
                ) : (
                  r.status === "OPEN" && <Chip>unassigned</Chip>
                )}
                {r.aiPaused && <Chip tone="amber">AI paused</Chip>}
                {r.snoozedUntil && new Date(r.snoozedUntil).getTime() > now && <Chip>snoozed</Chip>}
