      alive = false;
    };
  }, [id, row?.userId]);

  return (
    <aside className="flex min-h-0 flex-col overflow-y-auto text-xs" aria-label="Customer details">
      <div className="border-b border-white/10 px-3.5 py-3">
        <p className="truncate text-sm font-semibold text-slate-100">{rowLabel(row)}</p>
        <p className="truncate text-[11px] text-slate-400">{row?.email ?? "no email given"}</p>
        <p className="mt-1 text-[11px] text-slate-500">Chat started {timeAgo(row?.createdAt)} ago</p>
      </div>
      {err && <p className="p-3.5 text-slate-500">Couldn&apos;t load customer details.</p>}
      {!ctx && !err && <div className="m-3.5 h-24 animate-pulse rounded-xl bg-white/[0.04]" aria-hidden />}
      {ctx && !ctx.linked && (
        <Section title="Account">
          <p className="text-slate-400">Guest visitor — not linked to a customer account{row?.email ? `, and no account uses ${row.email}` : ""}.</p>
        </Section>
      )}
      {ctx && ctx.linked && (
        <>
          <Section
            title="Account"
            right={!scoped ? <Link href={`/admin/users/${ctx.user.id}`} className="text-[11px] text-brand-300 hover:text-brand-200">Open 360 →</Link> : null}
          >
            {ctx.matchedByEmail && <p className="mb-1 text-[11px] text-amber-300">Matched by the email they typed (they aren&apos;t signed in).</p>}
            <p className="font-medium text-slate-200">{ctx.user.name}</p>
            <div className="mt-1 flex flex-wrap gap-1">
              <Chip>since {new Date(ctx.user.createdAt).toLocaleDateString(undefined, { month: "short", year: "numeric" })}</Chip>
              {ctx.user.isCreator && <Chip tone="brand">creator</Chip>}
              {ctx.user.suspended && <Chip tone="red">suspended</Chip>}
              {!ctx.user.emailVerifiedAt && <Chip tone="amber">email unverified</Chip>}
            </div>
          </Section>
          <Section title="Billing">
            <div className="grid grid-cols-2 gap-2">
              <div className="rounded-lg bg-white/[0.04] px-2 py-1.5">
                <p className="text-[10px] text-slate-500">Wallet</p>
                <p className="font-semibold text-slate-100">{money(ctx.billing.balanceCents)}</p>
              </div>
              <div className={`rounded-lg px-2 py-1.5 ${ctx.billing.openInvoices ? "bg-amber-500/10" : "bg-white/[0.04]"}`}>
                <p className="text-[10px] text-slate-500">Unpaid</p>
                <p className={`font-semibold ${ctx.billing.openInvoices ? "text-amber-200" : "text-slate-100"}`}>
                  {ctx.billing.openInvoices ? `${ctx.billing.openInvoices} · ${money(ctx.billing.openCents)}` : "none"}
                </p>
              </div>
            </div>
            {ctx.invoices.length > 0 && (
              <ul className="mt-2 space-y-1">
                {ctx.invoices.map((i) => (
                  <li key={i.id} className="flex items-center justify-between gap-2">
                    <span className="min-w-0 truncate text-slate-400">#{i.number} {i.description}</span>
                    <span className={`flex-none ${i.status === "OPEN" ? "text-amber-300" : i.status === "PAID" ? "text-emerald-300" : "text-slate-500"}`}>
                      {money(i.amountCents)} · {i.status.toLowerCase()}
                    </span>
                  </li>
                ))}
              </ul>
            )}
            {ctx.payments.length > 0 && (
              <details className="mt-2">
                <summary className="cursor-pointer text-[11px] text-slate-500">Recent wallet activity</summary>
                <ul className="mt-1 space-y-1">
                  {ctx.payments.map((p) => (
                    <li key={p.id} className="flex justify-between gap-2">
                      <span className="min-w-0 truncate text-slate-400">{p.description}</span>
                      <span className={p.amountCents >= 0 ? "text-emerald-300" : "text-slate-300"}>{money(p.amountCents)}</span>
                    </li>
                  ))}
                </ul>
              </details>
            )}
          </Section>
          <Section title={`Servers (${ctx.serverCount})`}>
            {ctx.servers.length === 0 && <p className="text-slate-500">No servers.</p>}
            <ul className="space-y-1.5">
              {ctx.servers.map((sv) => {
                const inner = (
                  <>
                    <span className={`h-1.5 w-1.5 flex-none rounded-full ${sv.status === "RUNNING" ? "bg-emerald-400" : sv.status === "STOPPED" ? "bg-slate-500" : "bg-amber-400"}`} />
                    <span className="min-w-0 flex-1 truncate text-slate-200">{sv.label || sv.name}</span>
                    <span className="flex-none text-[10px] text-slate-500">{sv.gamePlan?.name ?? sv.plan?.name ?? ""}</span>
                  </>
                );
                return (
                  <li key={sv.id}>
                    {!scoped ? (
                      <Link href={`/admin/servers/${sv.id}`} className="flex items-center gap-1.5 rounded-md px-1 py-0.5 hover:bg-white/[0.05]">
                        {inner}
                      </Link>
                    ) : (
                      <span className="flex items-center gap-1.5 px-1 py-0.5">{inner}</span>
                    )}
                    {sv.expiresAt && !sv.isFree && (
                      <p className="pl-4 text-[10px] text-slate-500">
                        {sv.status.toLowerCase()} · renews {new Date(sv.expiresAt).toLocaleDateString(undefined, { month: "short", day: "numeric" })}
                      </p>
                    )}
                  </li>
                );
              })}
            </ul>
          </Section>
          <Section title="Open tickets">
            {ctx.tickets.length === 0 ? (
              <p className="text-slate-500">None.</p>
            ) : (
              <ul className="space-y-1">
                {ctx.tickets.map((t) => (
                  <li key={t.id}>
                    {!scoped ? (
                      <Link href={`/admin/support/${t.id}`} className="flex justify-between gap-2 rounded-md px-1 py-0.5 hover:bg-white/[0.05]">
                        <span className="min-w-0 truncate text-slate-200">{t.subject}</span>
                        <span className="flex-none text-[10px] text-slate-500">{t.status.toLowerCase().replace("_", " ")}</span>
                      </Link>
                    ) : (
                      <span className="flex justify-between gap-2 px-1 py-0.5">
                        <span className="min-w-0 truncate text-slate-200">{t.subject}</span>
                        <span className="flex-none text-[10px] text-slate-500">{t.status.toLowerCase().replace("_", " ")}</span>
                      </span>
                    )}
                  </li>
                ))}
              </ul>
            )}
          </Section>
        </>
      )}
      {ctx && ctx.otherChats.length > 0 && (
        <Section title="Other chats">
          <ul className="space-y-1">
            {ctx.otherChats.map((c) => (
              <li key={c.id}>
                <button type="button" onClick={() => onOpenChat?.(c.id)} className="flex w-full justify-between gap-2 rounded-md px-1 py-0.5 text-left hover:bg-white/[0.05]">
                  <span className="min-w-0 truncate text-slate-300">{c.lastPreview || "…"}</span>
                  <span className="flex-none text-[10px] text-slate-500">{timeAgo(c.lastMessageAt)} · {c.status.toLowerCase()}</span>
                </button>
              </li>
            ))}
          </ul>
        </Section>
      )}
    </aside>
  );
}

