"use client";

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import { useRouter } from "next/navigation";
import { closeAllConversations } from "@/lib/actions-chat";
import { StaffChatProvider, useChatState, useMaybeStaffChatStore, useStaffChatStore } from "./store";
import { InboxList } from "./InboxList";
import { ThreadPane } from "./ThreadPane";
import { ContextPanel } from "./ContextPanel";
import { NotificationPrefs } from "./Notifier";
import { Ico, rowLabel } from "./ui";

/**
 * The /admin/chat (and /staff/chat) workspace.
 *
 * Built for several simultaneous conversations:
 *   - up to 3 conversations side by side (Shift/⌘/Ctrl-click a row, or "Split"),
 *   - a quick-switch strip of recently opened chats with unread dots (Alt+1…9),
 *   - keyboard: Alt+↑/↓ next/previous in the list, Alt+←/→ move between
 *     columns, Alt+W close column, Alt+C claim, Alt+E close conversation,
 *     / search, ? help,
 *   - the customer context panel for the focused chat.
 * Everything updates live from the one stream in the store.
 */

const MAX_COLS = 3;
const SS_KEY = "nxeon.chat.workspace.v1";

type WsState = { cols: string[]; focus: number; recent: string[]; context: boolean };

function readWs(): WsState {
  try {
    const raw = JSON.parse(sessionStorage.getItem(SS_KEY) ?? "null") as WsState | null;
    if (raw && Array.isArray(raw.cols)) {
      return { cols: raw.cols.slice(0, MAX_COLS), focus: Math.min(raw.focus ?? 0, Math.max(raw.cols.length - 1, 0)), recent: (raw.recent ?? []).slice(0, 9), context: raw.context !== false };
    }
  } catch {
    /* ignore */
  }
  return { cols: [], focus: 0, recent: [], context: true };
}

function isTyping(el: EventTarget | null): boolean {
  const t = el as HTMLElement | null;
  return !!t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable);
}

export function ChatWorkspace({ initialId }: { initialId?: string | null }) {
  const existing = useMaybeStaffChatStore();
  if (existing) return <Workspace initialId={initialId} />;
  // /staff/chat renders outside the admin layout's provider.
  return (
    <StaffChatProvider>
      <Workspace initialId={initialId} />
    </StaffChatProvider>
  );
}

function Workspace({ initialId }: { initialId?: string | null }) {
  const store = useStaffChatStore();
  const s = useChatState();
  const router = useRouter();
  const [ws, setWs] = useState<WsState>({ cols: [], focus: 0, recent: [], context: true });
  const [hydrated, setHydrated] = useState(false);
  const [help, setHelp] = useState(false);
  const searchRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const saved = readWs();
    if (initialId) {
      const cols = saved.cols.includes(initialId) ? saved.cols : [initialId, ...saved.cols.slice(1)].slice(0, MAX_COLS);
      if (!cols.length) cols.push(initialId);
      saved.cols = cols;
      saved.focus = cols.indexOf(initialId);
      saved.recent = [initialId, ...saved.recent.filter((x) => x !== initialId)].slice(0, 9);
    }
    setWs(saved);
    setHydrated(true);
  }, [initialId]);

  useEffect(() => {
    if (!hydrated) return;
    try {
      sessionStorage.setItem(SS_KEY, JSON.stringify(ws));
    } catch {
      /* ignore */
    }
  }, [ws, hydrated]);

  // Nothing open yet: open the top of the list once it arrives.
  useEffect(() => {
    if (hydrated && ws.cols.length === 0 && s.listIds[0]) setWs((w) => ({ ...w, cols: [s.listIds[0]], focus: 0, recent: [s.listIds[0], ...w.recent].slice(0, 9) }));
  }, [hydrated, ws.cols.length, s.listIds]);

  const focusedId = ws.cols[ws.focus] ?? null;

  // Keep the URL shareable (?c=<focused>) without a navigation.
  useEffect(() => {
    if (!hydrated || !focusedId) return;
    const url = new URL(window.location.href);
    if (url.searchParams.get("c") !== focusedId) {
      url.searchParams.set("c", focusedId);
      window.history.replaceState(window.history.state, "", url.toString());
    }
  }, [focusedId, hydrated]);

  const open = useCallback((id: string, split = false) => {
    setWs((w) => {
      const recent = [id, ...w.recent.filter((x) => x !== id)].slice(0, 9);
      const at = w.cols.indexOf(id);
      if (at >= 0) return { ...w, focus: at, recent };
      if (split && w.cols.length < MAX_COLS) return { ...w, cols: [...w.cols, id], focus: w.cols.length, recent };
      const cols = w.cols.length ? [...w.cols] : [id];
      cols[Math.min(w.focus, cols.length - 1)] = id;
      return { ...w, cols, focus: Math.min(w.focus, cols.length - 1), recent };
    });
  }, []);

  const closeCol = useCallback((idx: number) => {
    setWs((w) => {
      if (w.cols.length <= 1) return w;
      const cols = w.cols.filter((_, i) => i !== idx);
      return { ...w, cols, focus: Math.min(w.focus >= idx ? Math.max(w.focus - 1, 0) : w.focus, cols.length - 1) };
    });
  }, []);

  // Keyboard shortcuts.
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "/" && !isTyping(e.target) && !e.altKey && !e.metaKey && !e.ctrlKey) {
        e.preventDefault();
        searchRef.current?.focus();
        return;
      }
      if (e.key === "?" && !isTyping(e.target)) {
        setHelp((v) => !v);
        return;
      }
      if (!e.altKey || e.metaKey || e.ctrlKey) return;
      const list = s.listIds;
      if (e.key === "ArrowDown" || e.key === "ArrowUp") {
        e.preventDefault();
        const cur = focusedId ? list.indexOf(focusedId) : -1;
        const next = list[Math.max(0, Math.min(list.length - 1, cur + (e.key === "ArrowDown" ? 1 : -1)))];
        if (next) open(next);
        return;
      }
      if (e.key === "ArrowRight" || e.key === "ArrowLeft") {
        e.preventDefault();
        setWs((w) => ({ ...w, focus: Math.max(0, Math.min(w.cols.length - 1, w.focus + (e.key === "ArrowRight" ? 1 : -1))) }));
        return;
      }
      if (/^Digit[1-9]$/.test(e.code)) {
        e.preventDefault();
        const id = ws.recent[Number(e.code.slice(5)) - 1];
        if (id) open(id);
        return;
      }
      const k = e.code;
      if (k === "KeyW") {
        e.preventDefault();
        closeCol(ws.focus);
      } else if (k === "KeyC" && focusedId) {
        e.preventDefault();
        void store.action(focusedId, "assign").catch(() => {});
      } else if (k === "KeyE" && focusedId) {
        e.preventDefault();
        void store.action(focusedId, "close").catch(() => {});
      } else if (k === "KeyI") {
        e.preventDefault();
        setWs((w) => ({ ...w, context: !w.context }));
      }
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [s.listIds, focusedId, ws.recent, ws.focus, open, closeCol, store]);

  function doCloseAll() {
    const n = s.counts ? s.counts.all - s.counts.closed : 0;
    if (!window.confirm(`Close all ${n} open conversation${n === 1 ? "" : "s"}?`)) return;
    void closeAllConversations().then(() => {
      void store.refreshList();
      router.refresh();
    });
  }

  const connBadge: Record<string, ReactNode> = {
    live: <span className="flex items-center gap-1 text-emerald-300"><span className="h-1.5 w-1.5 rounded-full bg-emerald-400 motion-safe:animate-pulse" /> Live</span>,
    connecting: <span className="text-slate-400">Connecting…</span>,
    polling: <span className="text-amber-300" title="Live stream unavailable — refreshing every 5 s">Polling</span>,
    offline: <span className="text-red-300">Offline</span>,
  };

  return (
    <div className="space-y-2">
      <div className="flex flex-wrap items-center gap-2 text-[11px]">
        {connBadge[s.conn]}
        <span className="text-slate-500">· {s.agentsOnline} agent{s.agentsOnline === 1 ? "" : "s"} online</span>
        {/* Quick-switch strip: recently opened chats. */}
        <div className="flex min-w-0 flex-1 items-center gap-1 overflow-x-auto px-1" aria-label="Recent chats">
          {ws.recent.map((id, i) => {
            const r = s.rows[id];
            const active = ws.cols.includes(id);
            return (
              <button
                key={id}
                type="button"
                onClick={(e) => open(id, e.shiftKey || e.metaKey || e.ctrlKey)}
                title={`Alt+${i + 1}`}
                className={`inline-flex max-w-[11rem] flex-none items-center gap-1 rounded-lg border px-2 py-0.5 ${active ? "border-brand-400/40 bg-brand-500/10 text-brand-100" : "border-white/10 text-slate-400 hover:text-slate-200"}`}
              >
                <span className="text-[9px] text-slate-500">{i + 1}</span>
                <span className="truncate">{rowLabel(r)}</span>
                {r?.unreadForAgent && r.status === "OPEN" && <span className="h-1.5 w-1.5 flex-none rounded-full bg-amber-400" />}
              </button>
            );
          })}
        </div>
        <NotificationPrefs />
        <button type="button" onClick={() => setHelp((v) => !v)} className="inline-flex items-center gap-1 rounded-lg border border-white/10 px-2 py-0.5 text-slate-400 hover:text-slate-200" aria-expanded={help}>
          <Ico name="keyboard" size={13} /> Shortcuts
        </button>
        <button type="button" onClick={doCloseAll} className="rounded-lg border border-white/10 px-2 py-0.5 text-slate-400 hover:text-slate-200">
          Close all
        </button>
      </div>

      {help && (
        <div className="card grid gap-x-6 gap-y-1 p-3 text-[11.5px] text-slate-300 sm:grid-cols-2 lg:grid-cols-3">
          {[
            ["Alt + ↓ / ↑", "Next / previous conversation"],
            ["Shift-click", "Open beside the current chat (up to 3)"],
            ["Alt + ← / →", "Move between open columns"],
            ["Alt + 1…9", "Jump to a recent chat"],
            ["Alt + W", "Close the focused column"],
            ["Alt + C", "Claim (assign to me)"],
            ["Alt + E", "Close the conversation"],
            ["Alt + N", "Toggle reply / internal note"],
            ["Alt + I", "Toggle customer details"],
            ["/", "Search · in the reply box: canned replies"],
            ["Enter / Shift+Enter", "Send / new line"],
          ].map(([k, v]) => (
            <p key={k}>
              <kbd className="rounded border border-white/15 bg-white/[0.05] px-1 font-mono text-[10.5px]">{k}</kbd> <span className="text-slate-400">{v}</span>
            </p>
          ))}
        </div>
      )}

      <div
        className={`grid h-[calc(100vh-12rem)] min-h-[34rem] gap-3 ${
          ws.context && focusedId ? "lg:grid-cols-[20rem_minmax(0,1fr)_17rem]" : "lg:grid-cols-[20rem_minmax(0,1fr)]"
        }`}
      >
        <div className="card flex min-h-0 flex-col overflow-hidden p-0">
          <InboxList selectedId={focusedId} openIds={ws.cols} searchRef={searchRef} onSelect={(id, e) => open(id, !!e && "shiftKey" in e && (e.shiftKey || e.metaKey || e.ctrlKey))} />
        </div>

        <div className="flex min-h-0 gap-3">
          {ws.cols.length === 0 && (
            <div className="card flex flex-1 items-center justify-center p-10 text-sm text-slate-500">Select a conversation.</div>
          )}
          {ws.cols.map((id, i) => (
            <div
              key={`${i}-${id}`}
              className={`card flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden p-0 transition ${ws.cols.length > 1 && i === ws.focus ? "ring-1 ring-brand-400/50" : ""}`}
            >
              <ThreadPane
                id={id}
                focused={i === ws.focus}
                onFocus={() => setWs((w) => (w.focus === i ? w : { ...w, focus: i }))}
                onClose={ws.cols.length > 1 ? () => closeCol(i) : undefined}
                contextOpen={ws.context}
                onToggleContext={() => setWs((w) => ({ ...w, context: !w.context }))}
              />
            </div>
          ))}
          {ws.cols.length > 0 && ws.cols.length < MAX_COLS && (
            <button
              type="button"
              title="Open another conversation beside this one (or Shift-click one in the list)"
              onClick={() => {
                const next = s.listIds.find((x) => !ws.cols.includes(x));
                if (next) open(next, true);
              }}
              className="hidden w-9 flex-none items-center justify-center rounded-2xl border border-dashed border-white/10 text-slate-500 hover:border-brand-400/40 hover:text-brand-200 xl:flex"
            >
              <Ico name="split" size={15} />
            </button>
          )}
        </div>

        {ws.context && focusedId && (
          <div className="card hidden min-h-0 overflow-hidden p-0 lg:flex lg:flex-col">
            <ContextPanel id={focusedId} onOpenChat={(cid) => open(cid)} />
          </div>
        )}
      </div>
    </div>
  );
}

