"use client";

import { useEffect, useState } from "react";
import { useStaffChatStore } from "./store";
import { openInDock } from "./dock-state";
import { Ico, rowLabel } from "./ui";

/**
 * Sound + desktop notifications for live chat, driven by the live stream
 * (replaces components/admin/AdminChatNotifier.tsx's 10 s count poll).
 *
 * Fires for a VISITOR message when the agent isn't already looking at that
 * thread (tab hidden, or the conversation isn't open in any pane/dock window).
 * Preferences are per browser (localStorage); defaults: sound on, desktop off
 * until the agent grants permission from the toggle.
 */

const PREFS_KEY = "nxeon.chat.notify.v1";
type Prefs = { sound: boolean; desktop: boolean };

function readPrefs(): Prefs {
  try {
    const p = JSON.parse(localStorage.getItem(PREFS_KEY) ?? "null") as Partial<Prefs> | null;
    return { sound: p?.sound !== false, desktop: !!p?.desktop };
  } catch {
    return { sound: true, desktop: false };
  }
}
function writePrefs(p: Prefs) {
  try {
    localStorage.setItem(PREFS_KEY, JSON.stringify(p));
    window.dispatchEvent(new Event("nxeon:chat-prefs"));
  } catch {
    /* ignore */
  }
}

function beep() {
  try {
    const W = window as unknown as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext };
    const Ctx = W.AudioContext ?? W.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    const now = ctx.currentTime;
    [880, 1175].forEach((f, i) => {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = "sine";
      o.frequency.value = f;
      g.gain.setValueAtTime(0.0001, now + i * 0.12);
      g.gain.exponentialRampToValueAtTime(0.12, now + i * 0.12 + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, now + i * 0.12 + 0.22);
      o.connect(g);
      g.connect(ctx.destination);
      o.start(now + i * 0.12);
      o.stop(now + i * 0.12 + 0.24);
    });
    setTimeout(() => ctx.close().catch(() => {}), 600);
  } catch {
    /* blocked */
  }
}

export function ChatNotifier({ dockOnClick = true }: { dockOnClick?: boolean }) {
  const store = useStaffChatStore();
  useEffect(() => {
    let lastAt = 0;
    const baseTitle = document.title;
    let unseen = 0;
    const onVis = () => {
      if (document.visibilityState === "visible") {
        unseen = 0;
        document.title = baseTitle;
      }
    };
    document.addEventListener("visibilitychange", onVis);
    const off = store.onMessage((m, row) => {
      if (m.sender !== "visitor") return;
      const hidden = document.visibilityState !== "visible";
      if (!hidden && store.isOpen(m.conversationId)) return;
      const prefs = readPrefs();
      if (hidden) {
        unseen++;
        document.title = `(${unseen}) 💬 ${baseTitle}`;
      }
      if (Date.now() - lastAt < 2500) return; // burst → one alert
      lastAt = Date.now();
      if (prefs.sound) beep();
      if (prefs.desktop && typeof Notification !== "undefined" && Notification.permission === "granted") {
        try {
          const n = new Notification(`💬 ${rowLabel(row)}`, {
            body: m.body ? m.body.slice(0, 140) : "📎 Image",
            tag: `nxeon-chat-${m.conversationId}`,
            icon: "/favicon.ico",
          });
          n.onclick = () => {
            window.focus();
            if (dockOnClick) openInDock(m.conversationId);
            n.close();
          };
        } catch {
          /* ignore */
        }
      }
    });
    return () => {
      off();
      document.removeEventListener("visibilitychange", onVis);
      document.title = baseTitle;
    };
  }, [store, dockOnClick]);
  return null;
}

/** Sound / desktop toggles shown in the workspace toolbar and the dock. */
export function NotificationPrefs({ compact = false }: { compact?: boolean }) {
  const [p, setP] = useState<Prefs>({ sound: true, desktop: false });
  useEffect(() => {
    setP(readPrefs());
    const h = () => setP(readPrefs());
    window.addEventListener("nxeon:chat-prefs", h);
    return () => window.removeEventListener("nxeon:chat-prefs", h);
  }, []);
  async function toggleDesktop() {
    if (!p.desktop && typeof Notification !== "undefined" && Notification.permission !== "granted") {
      const r = await Notification.requestPermission().catch(() => "denied");
      if (r !== "granted") return;
    }
    writePrefs({ ...p, desktop: !p.desktop });
  }
  const btn = "inline-flex items-center gap-1 rounded-lg border px-2 py-0.5";
  return (
    <span className="inline-flex items-center gap-1">
      <button type="button" aria-pressed={p.sound} onClick={() => writePrefs({ ...p, sound: !p.sound })} className={`${btn} ${p.sound ? "border-brand-400/30 text-brand-200" : "border-white/10 text-slate-500"}`} title="Play a sound for new customer messages">
        {p.sound ? "🔔" : "🔕"} {!compact && "Sound"}
      </button>
      <button type="button" aria-pressed={p.desktop} onClick={() => void toggleDesktop()} className={`${btn} ${p.desktop ? "border-brand-400/30 text-brand-200" : "border-white/10 text-slate-500"}`} title="Desktop notifications for new customer messages">
        <Ico name="bell" size={12} /> {!compact && "Desktop"}
      </button>
    </span>
  );
}

