"use client";

import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { usePathname } from "next/navigation";
import { UserName } from "@/components/ui/UserName";
import { StaffChatProvider, useChatState, useStaffChatStore } from "./store";
import { ThreadPane } from "./ThreadPane";
import { ChatNotifier, NotificationPrefs } from "./Notifier";
import { closeInDock, onDockChange, openInDock, readDock, toggleMinimized, writeDock, type DockState } from "./dock-state";
import { Chip, Ico, TypingDots, rowLabel, timeAgo } from "./ui";
import type { InboxTab } from "@/lib/chat/types";

/**
 * Persistent staff chat dock.
 *
 * ADMIN PORTAL: mounted once in app/admin/layout.tsx inside the shared
 * StaffChatProvider, so it stays open and live while the agent navigates
 * anywhere in /admin (layouts persist across client navigation). Hidden on
 * /admin/chat itself, where the full workspace is.
 *
 * IMPERSONATION: app/dashboard/layout.tsx mounts <ImpersonationChatDock/> only
 * when `impersonating()` is non-null. It has its own provider whose server
 * routes are scoped to the impersonated customer's conversations
 * (lib/chat/staff-auth.ts) — so it can show THIS customer's chats and nothing
 * else — and every reply is written as the real admin (`sender: "agent"`,
 * authorId = admin), never as the customer. It is framed in the impersonation
 * magenta and labelled STAFF ONLY. The open-chat list is carried across the
 * hard navigation by localStorage (dock-state.ts).
 *
 * Portaled to <body> so no backdrop-filter ancestor can trap its fixed
 * positioning (CLAUDE.md landmine).
 */

export function ChatDock() {
  const pathname = usePathname() ?? "";
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  if (!mounted || pathname.startsWith("/admin/chat") || pathname.startsWith("/admin/login")) return null;
  return createPortal(<Dock mode="admin" />, document.body);
}

export function ImpersonationChatDock({ adminName, targetEmail }: { adminName: string; targetEmail: string }) {
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  if (!mounted) return null;
  return createPortal(
    <StaffChatProvider initialTab="all">
      <ChatNotifier dockOnClick />
      <Dock mode="impersonating" adminName={adminName} targetEmail={targetEmail} />
    </StaffChatProvider>,
    document.body,
  );
}

const PICK_TABS: InboxTab[] = ["waiting", "mine", "unassigned", "all"];

function Dock({ mode, adminName, targetEmail }: { mode: "admin" | "impersonating"; adminName?: string; targetEmail?: string }) {
  const store = useStaffChatStore();
  const s = useChatState();
  const [dock, setDock] = useState<DockState>({ open: [], minimized: [], collapsed: false });
  const [picker, setPicker] = useState(false);
  const imp = mode === "impersonating";

  useEffect(() => {
    setDock(readDock());
    return onDockChange(setDock);
  }, []);

  // While impersonating, the server refuses any chat outside this customer's
  // scope; drop those ids from the dock instead of showing dead windows.
  useEffect(() => {
    if (!imp) return;
    const bad = dock.open.filter((id) => s.missing[id]);
    if (bad.length) writeDock({ ...dock, open: dock.open.filter((id) => !s.missing[id]), minimized: dock.minimized.filter((id) => !s.missing[id]) });
  }, [imp, s.missing, dock]);

  const waiting = s.counts?.waiting ?? 0;
  const unreadOpen = dock.open.filter((id) => s.rows[id]?.unreadForAgent).length;

  return (
    <div
      data-staff-only="true"
      className="pointer-events-none fixed bottom-3 right-3 z-[65] flex max-w-[calc(100vw-1.5rem)] items-end gap-2"
      aria-label={imp ? "Staff-only chat dock" : "Chat dock"}
    >
      {dock.open.map((id) => {
        const min = dock.minimized.includes(id);
        return (
          <div
            key={id}
            className={`pointer-events-auto flex w-[22rem] max-w-[calc(100vw-1.5rem)] flex-col overflow-hidden rounded-2xl border bg-[var(--adm-surface,#0b1226)] shadow-2xl shadow-black/50 max-sm:fixed max-sm:inset-x-2 max-sm:bottom-16 max-sm:w-auto ${
              imp ? "border-[#d623e1]/50" : "border-white/10"
            } ${min ? "" : "h-[31rem] max-h-[calc(100vh-6rem)]"}`}
            style={{ background: "var(--adm-surface, #0b1226)" }}
          >
            {imp && !min && <StaffOnlyStrip adminName={adminName} />}
            <ThreadPane
              id={id}
              variant="dock"
              minimized={min}
              onMinimize={() => toggleMinimized(id)}
              onClose={() => closeInDock(id)}
            />
          </div>
        );
      })}

      <div className="pointer-events-auto relative flex flex-col items-end gap-2">
        {picker && <Picker mode={mode} targetEmail={targetEmail} onPick={(id) => (openInDock(id), setPicker(false))} onClose={() => setPicker(false)} />}
        <button
          type="button"
          onClick={() => {
            setPicker((v) => !v);
            if (!picker) store.setFilters({ tab: imp ? "all" : "waiting", q: "" });
          }}
          aria-expanded={picker}
          className={`flex items-center gap-2 rounded-full border px-3.5 py-2 text-xs font-semibold text-white shadow-xl transition hover:scale-[1.02] ${
            imp ? "border-[#d623e1]/60 bg-[#2a0f3a]" : "border-brand-400/40 bg-gradient-to-br from-brand-600 to-accent-blue"
          }`}
          style={imp ? { boxShadow: "0 0 24px -8px rgba(214,35,225,0.8)" } : undefined}
        >
          <Ico name="reply" size={14} />
          {imp ? "Staff chat" : "Chats"}
          {!imp && waiting > 0 && <span className="rounded-full bg-amber-400 px-1.5 text-[10px] font-bold text-slate-950">{waiting}</span>}
          {unreadOpen > 0 && <span className="h-2 w-2 rounded-full bg-amber-300" aria-label="unread" />}
          <span className={`h-1.5 w-1.5 rounded-full ${s.conn === "live" ? "bg-emerald-300" : s.conn === "polling" ? "bg-amber-300" : "bg-slate-400"}`} title={`Connection: ${s.conn}`} />
        </button>
      </div>
    </div>
  );
}

function StaffOnlyStrip({ adminName }: { adminName?: string }) {
  return (
    <div className="flex items-center gap-1.5 border-b border-[#d623e1]/40 px-2.5 py-1 text-[10.5px] font-semibold text-[#f5b8fb]" style={{ background: "linear-gradient(96deg, rgba(214,35,225,0.22), rgba(140,58,233,0.10))" }}>
      <Ico name="lock" size={11} /> STAFF ONLY · the customer can&apos;t see this · replies are sent as {adminName ?? "you"} (staff)
    </div>
  );
}

function Picker({ mode, targetEmail, onPick, onClose }: { mode: "admin" | "impersonating"; targetEmail?: string; onPick: (id: string) => void; onClose: () => void }) {
  const store = useStaffChatStore();
  const s = useChatState();
  const imp = mode === "impersonating";
  useEffect(() => {
    const k = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [onClose]);
  return (
    <div className={`w-[20rem] max-w-[calc(100vw-1.5rem)] overflow-hidden rounded-2xl border bg-[var(--adm-surface,#0b1226)] shadow-2xl ${imp ? "border-[#d623e1]/50" : "border-white/10"}`} style={{ background: "var(--adm-surface, #0b1226)" }} role="dialog" aria-label="Open a chat">
      {imp && (
        <div className="border-b border-[#d623e1]/40 px-3 py-2 text-[11px] text-[#f5b8fb]" style={{ background: "linear-gradient(96deg, rgba(214,35,225,0.22), rgba(140,58,233,0.10))" }}>
          <p className="font-semibold">STAFF ONLY — not visible to the customer</p>
          <p className="text-[10.5px] opacity-80">Showing {targetEmail ?? "this customer"}&apos;s chats only.</p>
        </div>
      )}
      <div className="flex items-center gap-1 border-b border-white/10 p-2">
        {!imp &&
          PICK_TABS.map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => store.setFilters({ tab: t })}
              className={`rounded-lg px-2 py-0.5 text-[11px] font-medium ${s.tab === t ? "bg-brand-500/20 text-brand-100" : "text-slate-400 hover:text-slate-200"}`}
            >
              {t[0].toUpperCase() + t.slice(1)} {s.counts ? <span className="text-slate-500">{s.counts[t]}</span> : null}
            </button>
          ))}
        <span className="ml-auto">
          <NotificationPrefs compact />
        </span>
      </div>
      <div className="max-h-80 overflow-y-auto p-1.5">
        {s.listIds.length === 0 && <p className="p-4 text-center text-xs text-slate-500">{s.listLoading ? "Loading…" : "No conversations."}</p>}
        {s.listIds.slice(0, 30).map((id) => {
          const r = s.rows[id];
          if (!r) return null;
          const typing = (s.visitorTyping[id] ?? 0) > Date.now();
          return (
            <button key={id} type="button" onClick={() => onPick(id)} className="mb-0.5 w-full rounded-xl px-2.5 py-1.5 text-left hover:bg-white/[0.05]">
              <div className="flex items-center gap-1.5">
                <span className={`h-1.5 w-1.5 flex-none rounded-full ${s.visitorsOnline[id] ? "bg-emerald-400" : "bg-transparent"}`} />
                <span className={`min-w-0 flex-1 truncate text-xs ${r.unreadForAgent ? "font-semibold text-slate-50" : "text-slate-200"}`}>
                  <UserName name={rowLabel(r)} creator={r.isCreator} />
                </span>
                {r.status === "CLOSED" && <Chip>closed</Chip>}
                <span className="text-[10px] text-slate-500">{timeAgo(r.lastMessageAt)}</span>
              </div>
              <p className="truncate pl-3 text-[11px] text-slate-500">{typing ? <span className="inline-flex items-center gap-1 text-cyan-300"><TypingDots /> typing…</span> : r.lastPreview || "…"}</p>
            </button>
          );
        })}
      </div>
      {!imp && (
        <a href="/admin/chat" className="block border-t border-white/10 px-3 py-2 text-center text-[11px] text-brand-300 hover:bg-white/[0.04]">
          Open the full inbox →
        </a>
      )}
    </div>
  );
}

