  help: {
    chips: [
      { id: "h-migrate", label: "Migrate my site to Nxeon", kind: "seed", seed: "I'd like help migrating my existing site to Nxeon." },
      { id: "h-tech", label: "Fix a technical issue", kind: "seed", seed: "I need technical help — something on my site or server isn't working right." },
      { id: "h-build", label: "Build a website with AI", kind: "seed", seed: "I'd like to build a website using your Build-with-AI tool." },
    ],
  },
};
const FUNNEL_PARENT: Record<string, string> = { pricing: "root", help: "root" };

type ServerPage = {
  conversation: { id: string; status: string; agentLastReadAt?: string | null } | null;
  messages: CustomerChatMessage[];
  hasMore?: boolean;
  typing?: { agent?: boolean };
  botStep?: string | null;
  agentsOnline?: boolean;
  impersonating?: boolean;
};

export default function ChatWidget({
  viewer = null,
  embedded = false,
  staffImpersonating = false,
}: {
  viewer?: ChatViewer;
  embedded?: boolean;
  /** True while an admin is impersonating — the widget stays out of the way. */
  staffImpersonating?: boolean;
}) {
  // Suppressed on every /admin route (staff answer from /admin/chat + the dock).
  const pathname = usePathname();
  const onAdmin = pathname?.startsWith("/admin") ?? false;
  const isAuthed = !!viewer;
  const [open, setOpen] = useState(false);
  /* `embedded` mounts a SECOND instance of this exact component (Support page
   * "Live Chat" tab): no bubble chrome, always "open". */
  const panelOpen = embedded || open;
  const consentPending = useConsentPending();
  const [visitorId, setVisitorId] = useState("");
  const [messages, setMessages] = useState<Msg[]>([]);
  const [hasMore, setHasMore] = useState(false);
  const [loadingOlder, setLoadingOlder] = useState(false);
  const [draft, setDraftState] = useState("");
  const [name, setName] = useState(viewer?.name ?? "");
  const [email, setEmail] = useState(viewer?.email ?? "");
  const [error, setError] = useState("");
  const [started, setStarted] = useState(false);
  const [pendingImage, setPendingImage] = useState<{ file: File; url: string } | null>(null);
  const [agentTypingUntil, setAgentTypingUntil] = useState(0);
  const [agentTypingName, setAgentTypingName] = useState<string | null>(null);
  const [awaitingSince, setAwaitingSince] = useState(0); // "Thinking…" after a send, until any reply
  const [botStep, setBotStep] = useState<string | null>(null);
  const [agentLastReadAt, setAgentLastReadAt] = useState<string | null>(null);
  const [agentsOnline, setAgentsOnline] = useState<boolean | null>(null);
  const [closedThread, setClosedThread] = useState(false);
  const [closing, setClosing] = useState(false);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [convos, setConvos] = useState<ConvoSummary[]>([]);
  const [showHistory, setShowHistory] = useState(false);
  const [funnelNode, setFunnelNode] = useState<string | null>("root");
  const [live, setLive] = useState<"off" | "live" | "polling">("off");
  const [dragging, setDragging] = useState(false);
  const [announce, setAnnounce] = useState("");
  const [blockedByImpersonation, setBlockedByImpersonation] = useState(staffImpersonating);
  const scrollRef = useRef<HTMLDivElement>(null);
  const topRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const taRef = useRef<HTMLTextAreaElement>(null);
  const bubbleRef = useRef<HTMLButtonElement>(null);
  const lastTypingPingRef = useRef(0);
  const atBottomRef = useRef(true);
  const prevHeightRef = useRef<number | null>(null);
  const messagesRef = useRef<Msg[]>([]);
  messagesRef.current = messages;
  const [, forceTick] = useState(0);

  const setDraft = (v: string) => {
    setDraftState(v);
    try {
      if (v) sessionStorage.setItem(DRAFT_KEY, v);
      else sessionStorage.removeItem(DRAFT_KEY);
    } catch {
      /* ignore */
    }
  };

  useEffect(() => {
    setVisitorId(getVisitorId());
    try {
      setDraftState(sessionStorage.getItem(DRAFT_KEY) ?? "");
    } catch {
      /* ignore */
    }
  }, []);

  // A "Live Chat" link anywhere on the site can open this widget.
  useEffect(() => {
    const openFromEvent = () => setOpen(true);
    window.addEventListener("nxeon:open-chat", openFromEvent);
    return () => window.removeEventListener("nxeon:open-chat", openFromEvent);
  }, []);

  const closePanel = useCallback(() => {
    const reduceMotion =
      typeof window !== "undefined" && typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const done = () => {
      setOpen(false);
      setClosing(false);
      requestAnimationFrame(() => bubbleRef.current?.focus());
    };
    if (reduceMotion) return done();
    setClosing(true);
    window.setTimeout(done, 260);
  }, []);

  function identityError(): string | null {
    if (isAuthed || started) return null;
    if (!name.trim() || !EMAIL_RE.test(email.trim())) return "Please add your name and a valid email to start the chat.";
    return null;
  }

  useEffect(() => {
    return () => {
      if (pendingImage) URL.revokeObjectURL(pendingImage.url);
    };
  }, [pendingImage]);

  const attachUrl = useCallback(
    (id: string, thumb: boolean) =>
      `/api/chat/attachment/${id}?${thumb ? "size=thumb&" : ""}visitorId=${encodeURIComponent(visitorId)}`,
    [visitorId],
  );

  function pickImage(file: File | null | undefined) {
    if (!file) return;
    const err = imageError(file);
    if (err) return setError(err);
    setError("");
    setPendingImage((prev) => {
      if (prev) URL.revokeObjectURL(prev.url);
      return { file, url: URL.createObjectURL(file) };
    });
  }
  function clearImage() {
    setPendingImage((prev) => {
      if (prev) URL.revokeObjectURL(prev.url);
      return null;
    });
    if (fileInputRef.current) fileInputRef.current.value = "";
  }
  function onPaste(e: ClipboardEvent) {
    const item = Array.from(e.clipboardData?.items ?? []).find((i) => i.type.startsWith("image/"));
    const file = item?.getAsFile();
    if (file) {
      e.preventDefault();
      pickImage(file);
    }
  }
  function onDrop(e: DragEvent) {
    e.preventDefault();
    setDragging(false);
    pickImage(Array.from(e.dataTransfer.files ?? []).find((f) => f.type.startsWith("image/")));
  }

  /** Fold server messages in; announce new staff/bot replies to screen readers. */
  const absorb = useCallback((incoming: CustomerChatMessage[]) => {
    if (!incoming.length) return;
    const before = new Set(messagesRef.current.map((m) => m.id));
    const fresh = incoming.filter((m) => !before.has(m.id) && m.sender !== "visitor");
    setMessages((cur) => mergeMessages(cur, incoming as Msg[]));
    if (fresh.length) {
      setAwaitingSince(0);
      setBotStep(null);
      setAgentTypingUntil(0);
      const last = fresh[fresh.length - 1];
      setAnnounce(`${senderName(last.sender === "bot" ? "bot" : "agent", last.agentName)}: ${last.body || "sent an image"}`);
    }
  }, []);

  const applyPage = useCallback(
    (d: ServerPage, mode: "replace" | "merge") => {
      if (d.impersonating) {
        setBlockedByImpersonation(true);
        return;
      }
      if (typeof d.agentsOnline === "boolean") setAgentsOnline(d.agentsOnline);
      if (!d.conversation) return;
      setStarted(true);
      setClosedThread(d.conversation.status === "CLOSED");
      if (d.conversation.agentLastReadAt !== undefined) setAgentLastReadAt(d.conversation.agentLastReadAt ?? null);
      if (mode === "replace") {
        setMessages((cur) => mergeMessages(cur.filter((m) => m.local), d.messages as Msg[]));
        setHasMore(!!d.hasMore);
      } else absorb(d.messages);
      if (d.typing?.agent) setAgentTypingUntil(Date.now() + TYPING_MS);
      if (d.botStep !== undefined) setBotStep(d.botStep ?? null);
    },
    [absorb],
  );

  const adopt = useCallback((id: string | null | undefined) => {
    if (!id) return;
    setActiveId(id);
    try {
      sessionStorage.setItem(ACTIVE_KEY, id);
    } catch {
      /* private mode */
    }
  }, []);

  const loadConvos = useCallback(async () => {
    if (!visitorId) return;
    try {
      const res = await fetch(`/api/chat/list?visitorId=${encodeURIComponent(visitorId)}`, { cache: "no-store" });
      if (!res.ok) return;
      const data = (await res.json()) as { conversations: ConvoSummary[]; agentsOnline?: boolean; impersonating?: boolean };
      if (data.impersonating) setBlockedByImpersonation(true);
      setConvos(data.conversations ?? []);
      if (typeof data.agentsOnline === "boolean") setAgentsOnline(data.agentsOnline);
    } catch {
      /* non-essential */
    }
  }, [visitorId]);

  /** Latest page (replace) or backfill since our newest confirmed message. */
  const sync = useCallback(
    async (mode: "latest" | "after") => {
      if (!visitorId || !activeId) return;
      const last = lastConfirmed(messagesRef.current);
      const q = new URLSearchParams({ visitorId, conversationId: activeId });
      if (mode === "after" && last) q.set("after", last.id);
      try {
        const res = await fetch(`/api/chat?${q}`, { cache: "no-store" });
        if (!res.ok) return;
        const d = (await res.json()) as ServerPage;
        if (mode === "after" && d.hasMore) return void sync("latest");
        applyPage(d, mode === "after" && last ? "merge" : "replace");
      } catch {
        /* transient */
      }
    },
    [visitorId, activeId, applyPage],
  );

  async function loadOlder() {
    if (!activeId || loadingOlder || !hasMore) return;
    const first = messagesRef.current.find((m) => !m.local);
    if (!first) return;
    setLoadingOlder(true);
    prevHeightRef.current = scrollRef.current?.scrollHeight ?? null;
    try {
      const q = new URLSearchParams({ visitorId, conversationId: activeId, before: first.id });
      const res = await fetch(`/api/chat?${q}`, { cache: "no-store" });
      if (res.ok) {
        const d = (await res.json()) as ServerPage;
        setMessages((cur) => mergeMessages(cur, d.messages as Msg[]));
        setHasMore(!!d.hasMore);
      }
    } finally {
      setLoadingOlder(false);
    }
  }

  function startNewChat() {
    setActiveId(null);
    try {
      sessionStorage.removeItem(ACTIVE_KEY);
    } catch {
      /* ignore */
    }
    setMessages([]);
    setHasMore(false);
    setStarted(false);
    setDraft("");
    setError("");
    setBotStep(null);
    setAwaitingSince(0);
    setAgentLastReadAt(null);
    setClosedThread(false);
    clearImage();
    setShowHistory(false);
    setFunnelNode("root");
  }

  const openConvo = useCallback(
    (id: string) => {
      setMessages([]);
      setHasMore(false);
      adopt(id);
      setShowHistory(false);
      setStarted(true);
      setBotStep(null);
      setAwaitingSince(0);
      setFunnelNode(null);
      atBottomRef.current = true;
    },
    [adopt],
  );

  // Visitor typing pings (throttled ~2.5 s), only once a conversation exists.
  const pingTyping = useCallback(() => {
    if (!visitorId || !activeId) return;
    const now = Date.now();
    if (now - lastTypingPingRef.current < 2500) return;
    lastTypingPingRef.current = now;
    fetch("/api/chat/typing", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ visitorId, conversationId: activeId }),
      keepalive: true,
    }).catch(() => {});
  }, [visitorId, activeId]);

  // On open: history list + resume this session's active chat.
  useEffect(() => {
    if (!panelOpen || !visitorId) return;
    void loadConvos();
    let saved: string | null = null;
    try {
      saved = sessionStorage.getItem(ACTIVE_KEY);
    } catch {
      /* ignore */
    }
    if (saved && !activeId) openConvo(saved);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [panelOpen, visitorId]);

  // Load the latest page whenever the active conversation changes.
  useEffect(() => {
    if (!panelOpen || !visitorId || !activeId) return;
    void sync("latest");
  }, [panelOpen, visitorId, activeId, sync]);

  // LIVE STREAM for the active conversation (+ polling fallback).
  useEffect(() => {
    if (!panelOpen || !visitorId || !activeId || blockedByImpersonation) {
      setLive("off");
      return;
    }
    let es: EventSource | null = null;
    let poll: ReturnType<typeof setInterval> | null = null;
    let retry: ReturnType<typeof setTimeout> | null = null;
    let failures = 0;
    let opened = false;
    let stopped = false;
    const startPoll = () => {
      setLive("polling");
      if (!poll) poll = setInterval(() => void sync("after"), POLL_MS);
    };
    const connect = () => {
      if (stopped) return;
      if (typeof EventSource === "undefined") return startPoll();
      es = new EventSource(`/api/chat/stream?visitorId=${encodeURIComponent(visitorId)}&conversationId=${encodeURIComponent(activeId)}`);
      es.onopen = () => {
        failures = 0;
        if (poll) clearInterval(poll);
        poll = null;
        setLive("live");
        if (opened) void sync("after"); // backfill anything missed while disconnected
        opened = true;
      };
      es.onerror = () => {
        failures++;
        if (!es || es.readyState === 2 || failures >= 3) {
          es?.close();
          es = null;
          startPoll();
          if (retry) clearTimeout(retry);
          retry = setTimeout(connect, 30_000);
        }
      };
      es.addEventListener("hello", (ev) => {
        const d = JSON.parse((ev as MessageEvent).data) as { status: string; agentsOnline: boolean; agentTyping: boolean; botStep: string | null; agentLastReadAt: string | null };
        setAgentsOnline(d.agentsOnline);
        setClosedThread(d.status === "CLOSED");
        if (d.agentTyping) setAgentTypingUntil(Date.now() + TYPING_MS);
        setBotStep(d.botStep);
        setAgentLastReadAt(d.agentLastReadAt);
      });
      es.addEventListener("message", (ev) => absorb([JSON.parse((ev as MessageEvent).data) as CustomerChatMessage]));
      es.addEventListener("typing", (ev) => {
        const d = JSON.parse((ev as MessageEvent).data) as { active: boolean; name: string | null };
        setAgentTypingUntil(d.active ? Date.now() + TYPING_MS : 0);
        setAgentTypingName(d.name);
      });
      es.addEventListener("read", (ev) => setAgentLastReadAt((JSON.parse((ev as MessageEvent).data) as { at: string }).at));
      es.addEventListener("botStep", (ev) => setBotStep((JSON.parse((ev as MessageEvent).data) as { step: string | null }).step));
      es.addEventListener("status", (ev) => setClosedThread((JSON.parse((ev as MessageEvent).data) as { status: string }).status === "CLOSED"));
      es.addEventListener("agents", (ev) => setAgentsOnline((JSON.parse((ev as MessageEvent).data) as { online: boolean }).online));
    };
    connect();
    const onVisible = () => {
      if (document.visibilityState === "visible") {
        void sync("after");
        if (!es && !poll) connect();
      }
    };
    document.addEventListener("visibilitychange", onVisible);
    window.addEventListener("online", onVisible);
    return () => {
      stopped = true;
      es?.close();
      if (poll) clearInterval(poll);
      if (retry) clearTimeout(retry);
      document.removeEventListener("visibilitychange", onVisible);
      window.removeEventListener("online", onVisible);
    };
  }, [panelOpen, visitorId, activeId, sync, absorb, blockedByImpersonation]);

  // Re-render so the typing indicator / "thinking" expire on their own.
  useEffect(() => {
    if (!agentTypingUntil && !awaitingSince) return;
    const t = setInterval(() => forceTick((n) => n + 1), 1000);
    return () => clearInterval(t);
  }, [agentTypingUntil, awaitingSince]);

  // Read receipt: the panel is open and visible and a staff/bot message arrived.
  const lastId = messages[messages.length - 1]?.id;
  useEffect(() => {
    if (!panelOpen || !visitorId || !activeId || typeof document === "undefined" || document.visibilityState !== "visible") return;
    const last = messages[messages.length - 1];
    if (!last || last.local || last.sender === "visitor") return;
    fetch("/api/chat/read", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ visitorId, conversationId: activeId }),
      keepalive: true,
    }).catch(() => {});
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [panelOpen, lastId, activeId, visitorId]);

  // Scroll management.
  function handleScroll() {
    const el = scrollRef.current;
    if (!el) return;
    atBottomRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 120;
  }
  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    if (prevHeightRef.current !== null) {
      el.scrollTop += el.scrollHeight - prevHeightRef.current;
      prevHeightRef.current = null;
    } else if (atBottomRef.current) {
      el.scrollTo({ top: el.scrollHeight });
    }
  }, [messages]);
  useEffect(() => {
    if (panelOpen) {
      atBottomRef.current = true;
      scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
      if (!embedded) requestAnimationFrame(() => taRef.current?.focus());
    }
  }, [panelOpen, embedded]);
  // Infinite scroll up.
  useEffect(() => {
    const root = scrollRef.current;
    const top = topRef.current;
    if (!root || !top || !hasMore) return;
    const io = new IntersectionObserver((es) => es.some((e) => e.isIntersecting) && void loadOlder(), { root, rootMargin: "150px 0px 0px 0px" });
    io.observe(top);
    return () => io.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hasMore, activeId, loadingOlder]);

  // Esc closes the floating panel.
  useEffect(() => {
    if (!open || embedded) return;
    const k = (e: KeyboardEvent) => {
      if (e.key === "Escape" && !document.querySelector('[role="dialog"][aria-modal="true"]')) closePanel();
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [open, embedded, closePanel]);

  /* ----------------------------- sending ----------------------------- */

  const deliver = useCallback(
    async (m: Msg, convoId: string | null) => {
      const persist = (fn: (l: Pending[]) => Pending[]) => writePending(fn(readPending()));
      try {
        let res: Response;
        if (m.file) {
          const fd = new FormData();
          fd.append("visitorId", visitorId);
          if (convoId) fd.append("conversationId", convoId);
          fd.append("file", m.file);
          if (m.body) fd.append("body", m.body);
          fd.append("clientId", m.clientId ?? "");
          if (name.trim()) fd.append("name", name.trim());
          if (email.trim()) fd.append("email", email.trim());
          res = await fetch("/api/chat/upload", { method: "POST", body: fd });
        } else {
          persist((l) => [...l.filter((p) => p.clientId !== m.clientId), { conversationId: convoId, clientId: m.clientId!, body: m.body, createdAt: m.createdAt }]);
          res = await fetch("/api/chat", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              visitorId,
              conversationId: convoId ?? undefined,
              body: m.body,
              clientId: m.clientId,
              name: name.trim() || undefined,
              email: email.trim() || undefined,
            }),
          });
        }
        const data = (await res.json().catch(() => ({}))) as ServerPage & { error?: string; message?: CustomerChatMessage | null; impersonating?: boolean };
        if (!res.ok) {
          if (data.impersonating) setBlockedByImpersonation(true);
          // Validation problems (identity, size) won't fix themselves: drop the bubble, show why.
          if (res.status === 400 || res.status === 413 || res.status === 403) {
            setMessages((cur) => dropLocal(cur, m.clientId!));
            persist((l) => l.filter((p) => p.clientId !== m.clientId));
            if (!m.file) setDraft(m.body);
          } else {
            setMessages((cur) => setLocalState(cur, m.clientId!, "failed"));
          }
          setError(data.error ?? "Could not send. Please try again.");
          return;
        }
        persist((l) => l.filter((p) => p.clientId !== m.clientId));
        if (m.previewUrl) URL.revokeObjectURL(m.previewUrl);
        setStarted(true);
        adopt(data.conversation?.id);
        if (data.message) absorb([data.message]);
        setMessages((cur) => mergeMessages(cur, (data.message ? [data.message] : []) as Msg[]));
        void loadConvos();
      } catch {
        setMessages((cur) => setLocalState(cur, m.clientId!, "failed"));
        setError("Network problem — your message will be retried.");
      }
    },
    [visitorId, name, email, adopt, absorb, loadConvos],
  );

  // After a refresh: re-send texts that never got a server ack (idempotent).
  useEffect(() => {
    if (!visitorId || !panelOpen || blockedByImpersonation) return;
    const saved = readPending();
    if (!saved.length) return;
    const mine = saved.filter((p) => p.conversationId === activeId || (!p.conversationId && !activeId));
    if (!mine.length) return;
    const locals: Msg[] = mine.map((p) => ({
      id: `local_${p.clientId}`,
      sender: "visitor",
      body: p.body,
      createdAt: p.createdAt,
      cards: null,
      attachment: null,
      agentName: null,
      clientId: p.clientId,
      local: "sending",
    }));
    setMessages((cur) => [...cur.filter((m) => !locals.some((l) => l.clientId === m.clientId)), ...locals]);
    for (const l of locals) void deliver(l, activeId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [visitorId, panelOpen, activeId]);

  async function send(overrideBody?: string) {
    const isOverride = typeof overrideBody === "string";
    const body = (isOverride ? overrideBody : draft).trim();
    const withImage = !isOverride && !!pendingImage;
    if (!visitorId || blockedByImpersonation) return;
    if (!body && !withImage) return;
    const idErr = identityError();
    if (idErr) return setError(idErr);

    setError("");
    setBotStep(null);
    atBottomRef.current = true;
    const clientId = newClientId();
    const m: Msg = {
      id: `local_${clientId}`,
      sender: "visitor",
      body,
      createdAt: new Date().toISOString(),
      cards: null,
      attachment: null,
      agentName: null,
      clientId,
      local: "sending",
      file: withImage ? pendingImage!.file : null,
      previewUrl: withImage ? pendingImage!.url : null,
    };
    setMessages((cur) => [...cur, m]);
    if (!isOverride) setDraft("");
    if (withImage) {
      setPendingImage(null); // the bubble owns the preview URL now
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
    // Show "Thinking…" while the AI may be answering (never once a human has replied).
    if (!messagesRef.current.some((x) => x.sender === "agent")) setAwaitingSince(Date.now());
    await deliver(m, activeId);
  }

  function retry(clientId: string) {
    const m = messagesRef.current.find((x) => x.local && x.clientId === clientId);
    if (!m) return;
    setError("");
    setMessages((cur) => setLocalState(cur, clientId, "sending"));
    void deliver(m, activeId);
  }
  function discard(clientId: string) {
    const m = messagesRef.current.find((x) => x.local && x.clientId === clientId);
    if (m?.previewUrl) URL.revokeObjectURL(m.previewUrl);
    setMessages((cur) => dropLocal(cur, clientId));
    writePending(readPending().filter((p) => p.clientId !== clientId));
  }

  function onChip(chip: FunnelChip) {
    if (chip.kind === "branch") return setFunnelNode(chip.id);
    const idErr = identityError();
    if (idErr) return setError(idErr);
    setFunnelNode(null);
    void send(chip.seed);
  }

  // Placed after every hook so the hook order is stable.
  if (onAdmin) return null;
  if (staffImpersonating && !embedded) return null;

  const now = Date.now();
  const agentTyping = agentTypingUntil > now;
  const thinking = !agentTyping && (botStep !== null || (awaitingSince > 0 && now - awaitingSince < 25_000));
  const lastVisitorConfirmed = [...messages].reverse().find((m) => m.sender === "visitor" && !m.local);
  const seenUpTo = agentLastReadAt;

  const statusLine =
    agentsOnline === null
      ? `Leave a message — we reply ${SUPPORT_REPLY_WITHIN}`
      : agentsOnline
        ? "Our team is online now"
        : `Team away — the AI assistant can help now, and we reply ${SUPPORT_REPLY_WITHIN}`;

  const panel = (
    <div
      role={embedded ? "region" : "dialog"}
      aria-label="Live chat with Nxeon"
      className={
        "card card-glass relative flex flex-col overflow-hidden p-0 " +
        (embedded
          ? "h-full w-full"
          : "h-[34rem] max-h-[calc(100vh-6rem)] w-[23rem] max-w-[calc(100vw-2rem)] shadow-2xl max-sm:fixed max-sm:inset-0 max-sm:h-[100dvh] max-sm:max-h-none max-sm:w-full max-sm:max-w-none max-sm:rounded-none " +
            (closing ? "motion-safe:animate-panel-out" : "motion-safe:animate-panel-in"))
      }
      style={{ "--tone": "#a05cf0" } as React.CSSProperties}
      onDragOver={(e) => {
        if (Array.from(e.dataTransfer.types).includes("Files")) {
          e.preventDefault();
          setDragging(true);
        }
      }}
      onDragLeave={(e) => e.currentTarget === e.target && setDragging(false)}
      onDrop={onDrop}
      onAnimationEnd={
        embedded
          ? undefined
          : () => {
              if (closing) {
                setOpen(false);
                setClosing(false);
              }
            }
      }
    >
      <span className="sr-only" aria-live="polite">{announce}</span>

      {/* Previous-conversations overlay */}
      {showHistory && (
        <div className="absolute inset-0 z-10 flex flex-col bg-[#0b1120]/97 backdrop-blur">
          <div className="flex items-center gap-2 border-b border-white/10 px-3 py-3">
            <button aria-label="Back" onClick={() => setShowHistory(false)} className="rounded-lg p-1 text-slate-400 hover:bg-white/10 hover:text-slate-200">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M15 18l-6-6 6-6" /></svg>
            </button>
            <p className="text-sm font-semibold text-slate-100">Your conversations</p>
          </div>
          <div className="flex-1 overflow-y-auto px-3 py-3">
            <button onClick={startNewChat} className="btn-secondary mb-3 flex w-full items-center justify-center gap-1.5 text-sm">
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 5v14M5 12h14" /></svg>
              Start a new chat
            </button>
            {convos.length === 0 ? (
              <p className="mt-6 text-center text-xs text-slate-500">No previous conversations yet.</p>
            ) : (
              <ul className="space-y-1.5">
                {convos.map((c) => (
                  <li key={c.id}>
                    <button
                      onClick={() => openConvo(c.id)}
                      className={`w-full rounded-lg border px-3 py-2 text-left transition hover:bg-white/[0.06] ${c.id === activeId ? "border-brand-400/40 bg-brand-500/10" : "border-white/10 bg-white/[0.02]"}`}
                    >
                      <div className="flex items-center justify-between gap-2">
                        <span className="min-w-0 flex-1 truncate text-xs font-medium text-slate-200">{c.title}</span>
                        {c.status === "CLOSED" && <span className="text-[9.5px] uppercase tracking-wide text-slate-500">closed</span>}
                        {c.unread && <span className="h-2 w-2 shrink-0 rounded-full bg-brand-400" aria-label="unread" />}
                      </div>
                      {c.preview && <p className="mt-0.5 truncate text-[11px] text-slate-500">{c.preview}</p>}
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      )}

      {/* Header */}
      <div className="flex items-center justify-between gap-2 border-b border-white/10 bg-gradient-to-r from-brand-500/20 to-accent-blue/20 px-4 py-3">
        <div className="flex min-w-0 items-center gap-2.5">
          <Avatar role={agentsOnline ? "agent" : "bot"} />
          <div className="min-w-0">
            <p className="flex items-center gap-1.5 text-sm font-semibold text-slate-100">
              Live Chat
              {agentsOnline !== null && (
                <span className={`inline-flex items-center gap-1 rounded-full px-1.5 py-[3px] text-[9.5px] font-medium ${agentsOnline ? "bg-emerald-500/15 text-emerald-300" : "bg-white/[0.06] text-slate-300"}`}>
                  <span className={`h-1.5 w-1.5 rounded-full ${agentsOnline ? "bg-emerald-400 motion-safe:animate-pulse" : "bg-slate-400"}`} aria-hidden />
                  {agentsOnline ? "Team online" : "Team away"}
                </span>
              )}
            </p>
            <p className="truncate text-[11px] text-slate-400" title={statusLine}>{statusLine}</p>
          </div>
        </div>
        <div className="flex flex-none items-center gap-0.5">
          <button aria-label="New chat" title="New chat" onClick={startNewChat} className="rounded-lg p-1.5 text-slate-400 hover:bg-white/10 hover:text-slate-200">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 5v14M5 12h14" /></svg>
          </button>
          <button
            aria-label="Previous chats"
            title="Previous chats"
            onClick={() => {
              setShowHistory((v) => !v);
              void loadConvos();
            }}
            className={`rounded-lg p-1.5 hover:bg-white/10 hover:text-slate-200 ${showHistory ? "text-brand-300" : "text-slate-400"}`}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 12a9 9 0 1 0 9-9 9 9 0 0 0-6.36 2.64L3 8M3 3v5h5M12 7v5l3 2" /></svg>
          </button>
          {!embedded && (
            <button aria-label="Close chat" onClick={closePanel} className="rounded-lg p-1.5 text-slate-400 hover:bg-white/10 hover:text-slate-200">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6 6 18M6 6l12 12" /></svg>
            </button>
          )}
        </div>
      </div>
      {live === "polling" && (
        <p className="border-b border-white/5 bg-white/[0.03] px-4 py-1 text-[10.5px] text-slate-400">Reconnecting… messages still arrive every few seconds.</p>
      )}

      {blockedByImpersonation ? (
        <div className="flex flex-1 items-center justify-center p-6 text-center text-sm text-slate-400">
          You&apos;re viewing this account as staff. Chat with this customer from the staff chat dock instead — it replies as you, never as them.
        </div>
      ) : (
        <>
          {/* Transcript */}
          <div ref={scrollRef} onScroll={handleScroll} className="flex-1 space-y-3 overflow-y-auto px-4 py-4">
            <div ref={topRef} />
            {loadingOlder && <p className="text-center text-[11px] text-slate-500">Loading earlier messages…</p>}
            {messages.length === 0 && !funnelNode && <p className="mt-6 text-center text-sm text-slate-400">Hi there! 👋 How can we help you today?</p>}
            {messages.map((m) => {
              const mine = m.sender === "visitor";
              const role = m.sender === "bot" ? "bot" : "agent";
              const seen = mine && !m.local && m === lastVisitorConfirmed && !!seenUpTo && seenUpTo >= m.createdAt;
              return (
                <div key={m.local ? `l-${m.clientId}` : m.id} className={`flex flex-col motion-safe:animate-fade-up ${mine ? "items-end" : "items-start"}`}>
                  {!mine && (
                    <span className="mb-0.5 flex items-center gap-1.5 pl-1 text-[11px] font-medium">
                      <Avatar role={role} name={m.agentName} />
                      <span className={role === "bot" ? "text-brand-300" : "text-cyan-300"}>{senderName(role, m.agentName)}</span>
                    </span>
                  )}
                  <div
                    className={`max-w-[80%] space-y-1.5 whitespace-pre-wrap break-words rounded-2xl px-3.5 py-2 text-sm ${
                      mine
                        ? `bg-brand-500 text-white ${m.local === "sending" ? "opacity-70" : ""}`
                        : m.sender === "bot"
                          ? "border border-brand-400/30 bg-brand-500/10 text-slate-100"
                          : "border border-white/10 bg-white/[0.06] text-slate-200"
                    }`}
                  >
                    {m.attachment && (
                      <LightboxImage
                        src={attachUrl(m.attachment.id, true)}
                        fullSrc={attachUrl(m.attachment.id, false)}
                        width={m.attachment.width}
                        height={m.attachment.height}
                        alt="Image attachment"
                        className="h-auto max-h-44 w-auto max-w-full rounded-lg border border-white/10 object-contain"
                      />
                    )}
                    {!m.attachment && m.previewUrl && (
                      // eslint-disable-next-line @next/next/no-img-element
                      <img src={m.previewUrl} alt="Sending image" className="max-h-44 max-w-full rounded-lg border border-white/10 object-contain" />
                    )}
                    {m.body && <div>{mine ? m.body : renderRich(m.body)}</div>}
                  </div>
                  <span className="mt-0.5 flex items-center gap-1 px-1 text-[10px] text-slate-500">
                    {m.local === "sending" && "Sending…"}
                    {m.local === "failed" && (
                      <span className="flex items-center gap-1.5 text-red-300" role="alert">
                        Not sent.
                        <button type="button" onClick={() => retry(m.clientId!)} className="underline">Retry</button>
                        <button type="button" onClick={() => discard(m.clientId!)} className="underline">Remove</button>
                      </span>
                    )}
                    {!m.local && formatTime(m.createdAt)}
                    {seen && <span className="text-cyan-300">· Seen</span>}
                  </span>
                  {!mine && <ChatCards cards={m.cards} viewer="customer" />}
                </div>
              );
            })}
            {funnelNode && FUNNEL[funnelNode] && (
              <div className="flex flex-col items-start">
                {funnelNode === "root" && messages.length === 0 && (
                  <>
                    <span className="mb-0.5 flex items-center gap-1.5 pl-1 text-[11px] font-medium text-brand-300">
                      <Avatar role="bot" />
                      {senderName("bot")}
                    </span>
                    <div className="max-w-[80%] rounded-2xl border border-brand-400/30 bg-brand-500/10 px-3.5 py-2 text-sm text-slate-100">
                      Hi there! 👋 Got a question? I&apos;m here to help. Pick what you need below — or just type your own message.
                    </div>
                  </>
                )}
                <div key={funnelNode} className="mt-2 flex w-full max-w-[92%] flex-wrap gap-1.5 motion-safe:animate-fade-up" role="group" aria-label="Quick options">
                  {funnelNode !== "root" && (
                    <button
                      type="button"
                      onClick={() => setFunnelNode(FUNNEL_PARENT[funnelNode] ?? "root")}
                      className="rounded-full border border-white/10 bg-white/[0.04] px-3 py-1.5 text-sm text-slate-300 transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400/50"
                    >
                      ← Back
                    </button>
                  )}
                  {FUNNEL[funnelNode].chips.map((chip) => (
                    <button
                      key={chip.id}
                      type="button"
                      onClick={() => onChip(chip)}
                      className="rounded-full border border-brand-400/30 bg-brand-500/10 px-3 py-1.5 text-left text-sm text-slate-100 transition hover:bg-brand-500/20 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400/50"
                    >
                      {chip.label}
                      {chip.kind === "branch" && <span aria-hidden className="ml-1 text-brand-300">›</span>}
                    </button>
                  ))}
                </div>
              </div>
            )}
            {(thinking || agentTyping) && (
              <div className="flex flex-col items-start motion-safe:animate-fade-up">
                <span className={`mb-0.5 flex items-center gap-1.5 pl-1 text-[11px] font-medium ${agentTyping ? "text-cyan-300" : "text-brand-300"}`}>
                  <Avatar role={agentTyping ? "agent" : "bot"} name={agentTypingName} />
                  {senderName(agentTyping ? "agent" : "bot", agentTypingName)}
                </span>
                <div className="flex items-center gap-2 rounded-2xl border border-white/10 bg-white/[0.06] px-3.5 py-2.5">
                  <span className="sr-only">{agentTyping ? "Support is typing" : "Assistant is thinking"}</span>
                  {!agentTyping && (
                    <span key={botStep ?? "__default"} className="text-xs text-slate-300 motion-safe:animate-fade-up">
                      {botStep ?? "Thinking…"}
                    </span>
                  )}
                  <TypingDots />
                </div>
              </div>
            )}
            {closedThread && messages.length > 0 && (
              <p className="pt-1 text-center text-[11px] text-slate-500">This conversation was closed — writing again reopens it.</p>
            )}
          </div>

          {/* Composer */}
          <div className="border-t border-white/10 px-3 py-3" style={{ paddingBottom: embedded ? undefined : "max(0.75rem, env(safe-area-inset-bottom))" }}>
            {!funnelNode && (
              <button
                type="button"
                onClick={() => setFunnelNode("root")}
                className="mb-2 inline-flex items-center gap-1 rounded-full border border-white/10 bg-white/[0.04] px-2.5 py-1 text-[11px] text-slate-300 transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400/50"
              >
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden><path d="M3 6h18M3 12h18M3 18h18" /></svg>
                Menu
              </button>
            )}
            {!started && !isAuthed && (
              <div className="mb-2">
                <div className="flex gap-2">
                  <input className="input py-1.5 text-xs" placeholder="Your name*" aria-label="Your name" value={name} maxLength={120} autoComplete="name" onChange={(e) => setName(e.target.value)} />
                  <input className="input py-1.5 text-xs" type="email" placeholder="Email*" aria-label="Your email" value={email} maxLength={200} autoComplete="email" onChange={(e) => setEmail(e.target.value)} />
                </div>
                <p className="mt-1 text-[10px] text-slate-500">We&apos;ll only use these to follow up on your chat.</p>
              </div>
            )}
            {error && <p className="mb-2 text-xs text-red-400" role="alert">{error}</p>}
            {pendingImage && (
              <div className="mb-2 flex items-center gap-2">
                <div className="relative">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img src={pendingImage.url} alt="Image to send" className="h-14 w-14 rounded-lg border border-white/10 object-cover" />
                  <button type="button" aria-label="Remove image" onClick={clearImage} className="absolute -right-1.5 -top-1.5 flex h-5 w-5 items-center justify-center rounded-full bg-slate-800 text-slate-200 ring-1 ring-white/20 hover:bg-slate-700">
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M18 6 6 18M6 6l12 12" /></svg>
                  </button>
                </div>
                <span className="truncate text-xs text-slate-400">{pendingImage.file.name}</span>
              </div>
            )}
            <input ref={fileInputRef} type="file" accept={ACCEPT_IMAGES} className="hidden" onChange={(e) => pickImage(e.target.files?.[0])} />
            <div className="flex items-end gap-1.5 rounded-[22px] border border-white/10 bg-white/[0.04] py-1.5 pl-1.5 pr-2 focus-within:border-brand-400/40">
              <button type="button" aria-label="Attach image" title="Attach an image (or paste / drop one)" onClick={() => fileInputRef.current?.click()} className="shrink-0 rounded-full p-2 text-slate-400 hover:bg-white/10 hover:text-slate-200">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21.44 11.05 12.25 20.24a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48" /></svg>
              </button>
              <textarea
                ref={taRef}
                className="max-h-32 min-h-[1.75rem] flex-1 resize-none bg-transparent py-1 text-base text-slate-100 outline-none placeholder:text-slate-500 sm:text-sm"
                placeholder="Type a message…"
                aria-label="Message"
                value={draft}
                maxLength={5000}
                rows={1}
                onChange={(e) => {
                  setDraft(e.target.value);
                  if (e.target.value.trim()) pingTyping();
                  e.currentTarget.style.height = "auto";
                  e.currentTarget.style.height = `${Math.min(e.currentTarget.scrollHeight, 128)}px`;
                }}
                onPaste={onPaste}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
                    e.preventDefault();
                    void send();
                  }
                }}
              />
              <button
                aria-label="Send"
                className="grid h-9 w-9 flex-none place-items-center rounded-full bg-gradient-to-br from-brand-500 to-accent-blue text-white transition hover:opacity-90 disabled:opacity-40"
                disabled={!draft.trim() && !pendingImage}
                onClick={() => void send()}
              >
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14M13 6l6 6-6 6" /></svg>
              </button>
            </div>
          </div>
        </>
      )}

      {dragging && (
        <div className="pointer-events-none absolute inset-0 z-20 grid place-items-center border-2 border-dashed border-brand-400/60 bg-brand-500/15 text-sm font-medium text-brand-100">
          Drop an image to attach it
        </div>
      )}
    </div>
  );

  if (embedded) return panel;

  return (
    <div
      /* While the cookie banner is waiting for an answer it owns the bottom of
         the viewport; lift the CLOSED bubble out of its way on small screens. */
      className={`fixed bottom-4 right-4 z-[60] flex flex-col items-end gap-3 ${consentPending && !open ? "max-sm:mb-52" : ""}`}
    >
      {open && panel}
      <div className={`relative ${open ? "max-sm:hidden" : ""}`}>
        {!open && <span aria-hidden className="absolute inset-[-6px] -z-10 rounded-full bg-brand-500/50 blur-lg motion-safe:animate-pulse" />}
        <button
          ref={bubbleRef}
          aria-label={open ? "Close chat" : "Open chat"}
          aria-expanded={open}
          onClick={() => (open ? closePanel() : setOpen(true))}
          className="relative flex h-14 w-14 items-center justify-center rounded-full bg-gradient-to-br from-brand-500 to-accent-blue text-white shadow-xl shadow-brand-500/30 transition hover:scale-105"
        >
          {open ? (
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6 6 18M6 6l12 12" /></svg>
          ) : (
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" /></svg>
          )}
        </button>
      </div>
    </div>
  );
}

