import { PrismaClient } from "@prisma/client";
import bcrypt from "bcryptjs";
import sharp from "sharp";
const db = new PrismaClient();
async function img(w: number, h: number, hue: string) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}"><defs><linearGradient id="g" x1="0" x2="1" y1="0" y2="1"><stop offset="0" stop-color="#3b6be8"/><stop offset="1" stop-color="${hue}"/></linearGradient></defs><rect width="100%" height="100%" fill="url(#g)"/><text x="50%" y="50%" font-size="${Math.round(w/12)}" fill="white" text-anchor="middle" font-family="sans-serif">Error log screenshot</text></svg>`;
  return sharp(Buffer.from(svg)).png().toBuffer();
}
async function main() {
  const pw = await bcrypt.hash("LivechatTest!2026", 10);
  const admin = await db.user.upsert({ where: { email: "admin@lc.test" }, update: {}, create: { email: "admin@lc.test", name: "Sam Rivera", role: "ADMIN", passwordHash: pw, emailVerifiedAt: new Date() } });
  const admin2 = await db.user.upsert({ where: { email: "support@lc.test" }, update: {}, create: { email: "support@lc.test", name: "Alex Chen", role: "SUPPORT", passwordHash: pw, emailVerifiedAt: new Date() } });
  const cust = await db.user.upsert({ where: { email: "jordan@lc.test" }, update: {}, create: { email: "jordan@lc.test", name: "Jordan Blake", role: "CUSTOMER", passwordHash: pw, balanceCents: 1250, emailVerifiedAt: new Date() } });
  const cust2 = await db.user.upsert({ where: { email: "priya@lc.test" }, update: {}, create: { email: "priya@lc.test", name: "Priya Natarajan", role: "CUSTOMER", passwordHash: pw, emailVerifiedAt: new Date() } });
  const mk = async (data: any, msgs: [string, string, number, boolean?][], att?: Buffer) => {
    const c = await db.chatConversation.create({ data });
    const base = Date.now() - 1000 * 60 * 60 * 3;
    let i = 0;
    for (const [sender, body, minsAgo, internal] of msgs) {
      const m = await db.chatMessage.create({ data: { conversationId: c.id, sender, body, internal: !!internal, authorId: sender === "agent" ? admin.id : null, createdAt: new Date(Date.now() - minsAgo * 60_000) } });
      if (att && i === 1) await db.chatAttachment.create({ data: { messageId: m.id, mime: "image/png", sizeBytes: att.length, data: new Uint8Array(att) } });
      i++;
    }
    const last = msgs.filter((x) => !x[3]).sort((a, b) => a[2] - b[2])[0];
    await db.chatConversation.update({ where: { id: c.id }, data: { lastMessageAt: new Date(Date.now() - last[2] * 60_000), lastSender: last[0], lastPreview: last[1].slice(0, 140) } });
    return c;
  };
  const big = await img(2400, 1600, "#7b3fef");
  const c1 = await mk({ visitorId: "v-jordan", userId: cust.id, name: "Jordan Blake", email: cust.email, unreadForAgent: true }, [
    ["visitor", "Hi! My Minecraft server keeps crashing after I added a plugin.", 30],
    ["visitor", "Here's the error I get:", 29],
    ["bot", "Sorry about that! Let me check your server status… It looks like the server restarted 3 times in the last hour.", 28],
    ["visitor", "Can a human look at this? I have players waiting.", 5],
  ], big);
  // long history for pagination
  const long: [string, string, number, boolean?][] = [];
  for (let k = 0; k < 95; k++) long.push([k % 3 === 0 ? "agent" : "visitor", `History message #${k + 1} — checking the DNS record propagation for the domain.`, 600 - k * 5]);
  long.push(["agent", "Customer previously asked about a refund; handled on ticket #1042.", 100, true]);
  long.push(["visitor", "Thanks, that worked! One more question about billing.", 2]);
  const c2 = await mk({ visitorId: "v-priya", userId: cust2.id, name: "Priya Natarajan", email: cust2.email, unreadForAgent: true, assignedToId: admin.id, priority: "HIGH" }, long);
  await mk({ visitorId: "v-guest1", name: "Marco", email: "marco@example.test", unreadForAgent: false, assignedToId: admin2.id }, [
    ["visitor", "Do you have servers in Singapore?", 50],
    ["agent", "Yes — our SGP region is live for VPS and game servers.", 45],
  ]);
  await mk({ visitorId: "v-guest2", name: "Lena", email: "lena@example.test", unreadForAgent: true, pinned: true }, [
    ["visitor", "Is there a discount for yearly billing on VPS?", 12],
  ]);
  await mk({ visitorId: "v-guest3", name: "Tom", email: "tom@example.test", status: "CLOSED", unreadForAgent: false }, [
    ["visitor", "How do I reset my password?", 900],
    ["agent", "Use Forgot password on the login page — the link is valid for 1 hour.", 890],
  ]);
  console.log(JSON.stringify({ admin: admin.id, cust: cust.id, c1: c1.id, c2: c2.id }));
}
main().finally(() => db.$disconnect());
