import { SignJWT } from "jose";
const BASE = "http://localhost:3477";
const secret = new TextEncoder().encode("livechat-dev-secret-0123456789abcdef0123456789");
const ids = JSON.parse(process.argv[2]);
const sess = async (sub) => new SignJWT({ sub, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("1d").sign(secret);
const imp = async (sub, adminId) => new SignJWT({ sub, adminId, typ: "imp" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("2h").sign(secret);
const adminCookie = `lc_session=${await sess(ids.admin)}`;
const impCookie = `${adminCookie}; lc_session_imp=${await imp(ids.cust, ids.admin)}`;
const J = async (path, opts = {}, cookie = adminCookie) => {
  const t = performance.now();
  const r = await fetch(BASE + path, { ...opts, headers: { ...(opts.headers || {}), cookie, ...(opts.body && typeof opts.body === "string" ? { "content-type": "application/json" } : {}) } });
  const txt = await r.text();
  let body; try { body = JSON.parse(txt); } catch { body = txt; }
  return { status: r.status, body, ms: Math.round(performance.now() - t), bytes: txt.length };
};
function stream(path, cookie) {
  const events = [];
  const ctl = new AbortController();
  const ready = (async () => {
    const r = await fetch(BASE + path, { headers: cookie ? { cookie } : {}, signal: ctl.signal });
    const reader = r.body.getReader();
    const dec = new TextDecoder();
    let buf = "";
    (async () => { try { for (;;) { const { value, done } = await reader.read(); if (done) break; buf += dec.decode(value, { stream: true }); let i; while ((i = buf.indexOf("\n\n")) >= 0) { const chunk = buf.slice(0, i); buf = buf.slice(i + 2); const ev = /event: (.*)/.exec(chunk)?.[1]; const data = /data: (.*)/.exec(chunk)?.[1]; if (ev) events.push({ ev, data: data ? JSON.parse(data) : null, at: performance.now() }); } } } catch {} })();
    return r.status;
  })();
  return { events, ready, close: () => ctl.abort() };
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const out = {};
// warm up compile
await J(`/api/admin/chat/conversations?tab=all`);
await J(`/api/admin/chat/conversations/${ids.c1}/messages`);
await J(`/api/chat/stream?visitorId=v-jordan&conversationId=${ids.c1}`, {}, "");
let r = await J(`/api/admin/chat/conversations?tab=all`);
out.list = { status: r.status, ms: r.ms, bytes: r.bytes, n: r.body.rows?.length, counts: r.body.counts };
r = await J(`/api/admin/chat/conversations/${ids.c2}/messages`);
out.page1 = { status: r.status, ms: r.ms, bytes: r.bytes, n: r.body.messages?.length, hasMore: r.body.hasMore, hasNote: r.body.messages?.some((m) => m.internal) };
r = await J(`/api/admin/chat/conversations/${ids.c2}/messages?before=${r.body.messages[0].id}`);
out.page2 = { status: r.status, n: r.body.messages?.length, hasMore: r.body.hasMore };
// realtime: customer stream + staff stream
const cs = stream(`/api/chat/stream?visitorId=v-jordan&conversationId=${ids.c1}`);
const ss = stream(`/api/admin/chat/stream`, adminCookie);
out.streamStatus = [await cs.ready, await ss.ready];
await sleep(500);
const t0 = performance.now();
r = await J(`/api/admin/chat/conversations/${ids.c1}/messages`, { method: "POST", body: JSON.stringify({ body: "Hi Jordan, I'm looking at your server now.", clientId: "ctestreply0001" }) });
out.staffSend = { status: r.status, ms: r.ms, authorName: r.body.message?.authorName, sender: r.body.message?.sender };
r = await J(`/api/admin/chat/conversations/${ids.c1}/messages`, { method: "POST", body: JSON.stringify({ body: "Retry of the same send", clientId: "ctestreply0001" }) });
out.idempotent = { status: r.status, duplicate: r.body.duplicate };
r = await J(`/api/admin/chat/conversations/${ids.c1}/messages`, { method: "POST", body: JSON.stringify({ body: "SECRET internal: customer is on an old plugin", internal: true }) });
out.note = { status: r.status, internal: r.body.message?.internal };
await sleep(800);
const custMsgs = cs.events.filter((e) => e.ev === "message");
out.customerStream = { got: custMsgs.map((e) => e.data.body), latencyMs: custMsgs[0] ? Math.round(custMsgs[0].at - t0) : null, leakedNote: cs.events.some((e) => JSON.stringify(e.data).includes("SECRET")), leakedAuthorId: cs.events.some((e) => JSON.stringify(e.data).includes(ids.admin)) };
// visitor sends -> staff stream
const t1 = performance.now();
r = await J(`/api/chat`, { method: "POST", body: JSON.stringify({ visitorId: "v-jordan", conversationId: ids.c1, body: "Thanks! It crashed again just now.", clientId: "cvisitor00001" }) }, "");
out.visitorSend = { status: r.status, ms: r.ms };
await sleep(600);
const staffMsg = ss.events.find((e) => e.ev === "message" && e.data.message.body.startsWith("Thanks! It crashed"));
out.staffStream = { gotVisitorMsg: !!staffMsg, latencyMs: staffMsg ? Math.round(staffMsg.at - t1) : null, sawNote: ss.events.some((e) => e.ev === "message" && e.data.message.internal) , visitorPresence: ss.events.filter(e=>e.ev==="visitorPresence").map(e=>e.data.online)};
// typing
await J(`/api/chat/typing`, { method: "POST", body: JSON.stringify({ visitorId: "v-jordan", conversationId: ids.c1 }) }, "");
await J(`/api/admin/chat/conversations/${ids.c1}/actions`, { method: "POST", body: JSON.stringify({ action: "typing" }) });
await sleep(400);
out.typing = { staffSawVisitorTyping: ss.events.some((e) => e.ev === "typing" && e.data.who === "visitor"), customerSawAgentTyping: cs.events.some((e) => e.ev === "typing"), agentName: cs.events.find((e) => e.ev === "typing")?.data?.name };
// read receipts
await J(`/api/chat/read`, { method: "POST", body: JSON.stringify({ visitorId: "v-jordan", conversationId: ids.c1 }) }, "");
await J(`/api/admin/chat/conversations/${ids.c1}/actions`, { method: "POST", body: JSON.stringify({ action: "read" }) });
await sleep(400);
out.read = { staffSawVisitorRead: ss.events.some((e) => e.ev === "read" && e.data.who === "visitor"), customerSawAgentRead: cs.events.some((e) => e.ev === "read") };
// customer GET never shows note
r = await J(`/api/chat?visitorId=v-jordan&conversationId=${ids.c1}`, {}, "");
out.customerGetNoNote = !JSON.stringify(r.body).includes("SECRET");
// foreign visitor can't read
r = await J(`/api/chat?visitorId=v-attacker&conversationId=${ids.c1}`, {}, "");
out.foreignVisitor = { conversation: r.body.conversation, n: r.body.messages.length };
r = await J(`/api/chat/stream?visitorId=v-attacker&conversationId=${ids.c1}`, {}, "");
out.foreignStream = r.status;
// customer cannot hit staff routes
const custCookie = `lc_session=${await sess(ids.cust)}`;
r = await J(`/api/admin/chat/conversations?tab=all`, {}, custCookie);
out.customerOnStaffRoute = r.status;
r = await J(`/api/admin/chat/stream`, {}, custCookie);
out.customerOnStaffStream = r.status;
// actions
for (const a of [{ action: "pin", on: true }, { action: "priority", value: "URGENT" }, { action: "snooze", minutes: 30 }, { action: "unsnooze" }, { action: "close" }, { action: "reopen" }, { action: "assign", staffId: null }, { action: "assign" }]) {
  r = await J(`/api/admin/chat/conversations/${ids.c1}/actions`, { method: "POST", body: JSON.stringify(a) });
  out["action_" + a.action + (a.on ?? a.value ?? a.minutes ?? (a.staffId === null ? "_null" : ""))] = r.status;
}
// CSRF
r = await J(`/api/admin/chat/conversations/${ids.c1}/actions`, { method: "POST", body: JSON.stringify({ action: "close" }), headers: { origin: "https://evil.example" } });
out.crossOrigin = r.status;
// impersonation scope
r = await J(`/api/admin/chat/conversations?tab=all`, {}, impCookie);
out.impList = { status: r.status, scoped: r.body.scoped, users: [...new Set(r.body.rows.map((x) => x.userId))] };
r = await J(`/api/admin/chat/conversations/${ids.c2}/messages`, {}, impCookie);
out.impForeignConvo = r.status;
r = await J(`/api/admin/chat/conversations/${ids.c1}/messages`, { method: "POST", body: JSON.stringify({ body: "Reply sent from the dock while impersonating" }) }, impCookie);
out.impSend = { status: r.status, sender: r.body.message?.sender, authorId: r.body.message?.authorId === ids.admin };
r = await J(`/api/chat`, { method: "POST", body: JSON.stringify({ visitorId: "v-admin-browser", conversationId: ids.c1, body: "posting as customer?" }) }, impCookie);
out.impCustomerPost = { status: r.status, impersonating: r.body.impersonating };
const is = stream(`/api/admin/chat/stream`, impCookie);
await is.ready; await sleep(300);
await J(`/api/admin/chat/conversations/${ids.c2}/messages`, { method: "POST", body: JSON.stringify({ body: "message in Priya's chat" }) });
await J(`/api/admin/chat/conversations/${ids.c1}/messages`, { method: "POST", body: JSON.stringify({ body: "message in Jordan's chat" }) });
await sleep(600);
out.impStream = { hello: is.events.find(e=>e.ev==="hello")?.data?.scoped, messages: is.events.filter((e) => e.ev === "message").map((e) => e.data.message.body), convoUsers: [...new Set(is.events.filter((e) => e.ev === "convo").map((e) => e.data.userId))] };
// attachments
const c1msgs = (await J(`/api/admin/chat/conversations/${ids.c1}/messages?limit=100`)).body.messages;
const att = c1msgs.find((m) => m.attachment)?.attachment;
for (const q of ["", "?size=thumb", "?size=thumb"]) {
  const t = performance.now();
  const rr = await fetch(`${BASE}/api/chat/attachment/${att.id}${q}`, { headers: { cookie: adminCookie } });
  const b = await rr.arrayBuffer();
  out["att" + (q || "_full") + "_" + Math.random().toString(36).slice(2,4)] = { status: rr.status, bytes: b.byteLength, type: rr.headers.get("content-type"), cache: rr.headers.get("cache-control"), ms: Math.round(performance.now() - t) };
}
let rr = await fetch(`${BASE}/api/chat/attachment/${att.id}?size=thumb&visitorId=v-attacker`);
out.attForeign = rr.status;
rr = await fetch(`${BASE}/api/chat/attachment/${att.id}?size=thumb&visitorId=v-jordan`);
out.attOwner = rr.status;
cs.close(); ss.close(); is.close();
