import { test } from "node:test";
import assert from "node:assert/strict";
import { mergeMessages, lastConfirmed, setLocalState, dropLocal, applyCannedVars, newClientId } from "../lib/chat/merge.ts";
import { toCustomerMessage, toStaffMessage, previewOf, cleanClientId, parseCards, firstName, isCustomerVisible } from "../lib/chat/visibility.ts";
import { tabWhere, searchWhere } from "../lib/chat/inbox-filters.ts";
import * as hub from "../lib/chat/hub.ts";
import type { StaffChatMessage, SeqEvent } from "../lib/chat/types.ts";

/**
 * Live-chat overhaul (2026-10): pure-logic guarantees.
 *  - merge: no duplicates, server ordering, optimistic reconciliation.
 *  - visibility: internal notes and staff identity never reach a customer.
 *  - inbox filters: tab semantics.
 *  - hub: fan-out, presence, viewing TTL.
 */

const m = (id: string, createdAt: string, extra: Record<string, unknown> = {}) => ({ id, createdAt, clientId: null as string | null, ...extra });

/* ----------------------------- merge ----------------------------- */

test("merge de-duplicates by id and sorts by server time then id", () => {
  const a = [m("b", "2026-10-06T10:00:01Z"), m("a", "2026-10-06T10:00:00Z")];
  const out = mergeMessages(a, [m("b", "2026-10-06T10:00:01Z"), m("c", "2026-10-06T10:00:01Z")]);
  assert.deepEqual(out.map((x) => x.id), ["a", "b", "c"]);
});

test("an optimistic bubble is REPLACED by the server echo with the same clientId", () => {
  const local = { ...m("local_c1", "2026-10-06T12:00:00Z"), clientId: "c1", local: "sending" as const };
  const out = mergeMessages([m("x", "2026-10-06T09:00:00Z"), local], [{ ...m("srv1", "2026-10-06T11:59:59Z"), clientId: "c1" }]);
  assert.deepEqual(out.map((x) => x.id), ["x", "srv1"]);
});

test("pending local bubbles stay after confirmed messages, in typing order", () => {
  const l1 = { ...m("local_1", "2026-10-06T12:00:00Z"), clientId: "c1", local: "sending" as const };
  const l2 = { ...m("local_2", "2026-10-06T12:00:01Z"), clientId: "c2", local: "failed" as const };
  const out = mergeMessages([l1, l2], [m("late", "2026-10-06T12:05:00Z")]);
  assert.deepEqual(out.map((x) => x.id), ["late", "local_1", "local_2"]);
  assert.equal(lastConfirmed(out)?.id, "late");
});

test("the same event delivered twice (stream + response) yields one message", () => {
  const ev = { ...m("s", "2026-10-06T12:00:00Z"), clientId: "c9" };
  const once = mergeMessages([], [ev]);
  const twice = mergeMessages(once, [ev]);
  assert.equal(twice.length, 1);
});

test("local state helpers only touch the matching optimistic entry", () => {
  const list = [{ ...m("local_a", "t"), clientId: "a", local: "sending" as const }, { ...m("srv", "t"), clientId: "a" }];
  const failed = setLocalState(list, "a", "failed");
  assert.equal(failed[0].local, "failed");
  assert.equal((failed[1] as { local?: string }).local, undefined);
  assert.equal(dropLocal(list, "a").length, 1);
});

test("client ids are url-safe and accepted by the server-side cleaner", () => {
  for (let i = 0; i < 20; i++) assert.ok(cleanClientId(newClientId()));
  assert.equal(cleanClientId("short"), null);
  assert.equal(cleanClientId("has spaces in it"), null);
  assert.equal(cleanClientId({}), null);
});

test("canned-reply variables fill from the conversation and agent; unknown tokens survive", () => {
  const out = applyCannedVars("Hi {first_name}, {agent} here — re {email}. {unknown}", { name: "Jordan Blake", email: "j@x.test", agent: "Sam Rivera" });
  assert.equal(out, "Hi Jordan, Sam here — re j@x.test. {unknown}");
  assert.equal(applyCannedVars("Hi {name}", { name: null }), "Hi there");
});

/* ----------------------------- visibility ----------------------------- */

function staffMsg(over: Partial<StaffChatMessage> = {}): StaffChatMessage {
  return {
    id: "m1",
    conversationId: "c1",
    sender: "agent",
    body: "hello",
    createdAt: "2026-10-06T12:00:00Z",
    cards: null,
    attachment: null,
    internal: false,
    authorId: "staff_123",
    authorName: "Sam Rivera",
    clientId: "cstaffclient1",
    ...over,
  };
}

test("an internal note NEVER projects to a customer message", () => {
  assert.equal(toCustomerMessage(staffMsg({ internal: true, body: "secret" })), null);
  assert.equal(isCustomerVisible({ internal: true }), false);
  assert.equal(isCustomerVisible({ internal: false }), true);
});

test("the customer shape carries no staff id, no full name, no internal flag", () => {
  const c = toCustomerMessage(staffMsg())!;
  const json = JSON.stringify(c);
  assert.ok(!json.includes("staff_123"), "author id must not leak");
  assert.ok(!json.includes("Rivera"), "staff surname must not leak");
  assert.ok(!("internal" in c));
  assert.ok(!("authorId" in c));
  assert.equal(c.agentName, "Sam");
  assert.equal(c.clientId, null, "a staff clientId is meaningless to the customer");
});

test("a visitor's own clientId round-trips so their tab can reconcile", () => {
  const c = toCustomerMessage(staffMsg({ sender: "visitor", authorId: null, authorName: null, clientId: "cvisit00001" }))!;
  assert.equal(c.clientId, "cvisit00001");
  assert.equal(c.agentName, null);
});

test("staff projection falls back to the assignee for legacy agent rows", () => {
  const row = { id: "m", conversationId: "c", sender: "agent", body: "x", cardsJson: null, createdAt: new Date("2026-01-01"), internal: false, authorId: null, clientId: null, attachment: null };
  const s = toStaffMessage(row, new Map([["assignee", "Alex Chen"]]), "assignee");
  assert.equal(s.authorName, "Alex Chen");
  assert.equal(toStaffMessage({ ...row, sender: "visitor" }, new Map(), "assignee").authorId, null);
});

test("cards parse defensively; previews never empty for media", () => {
  assert.equal(parseCards("not json"), null);
  assert.equal(parseCards('{"type":"offer"}'), null, "must be an array");
  assert.deepEqual(parseCards('[{"type":"offer","offerId":"o1"}, 3, null]'), [{ type: "offer", offerId: "o1" }]);
  assert.equal(previewOf("", true), "📎 Image");
  assert.equal(previewOf("", false, [{ type: "offer" }]), "📦 Offer");
  assert.equal(previewOf("  a\n\nb  ", false), "a b");
  assert.equal(firstName("  Priya Natarajan "), "Priya");
});

/* ----------------------------- inbox filters ----------------------------- */

test("tab filters: waiting/unassigned/mine exclude snoozed and closed threads", () => {
  const now = new Date("2026-10-06T12:00:00Z");
  const w = JSON.stringify(tabWhere("waiting", "me", now));
  assert.ok(w.includes('"status":"OPEN"') && w.includes("snoozedUntil") && w.includes('"lastSender":"visitor"'));
  assert.ok(JSON.stringify(tabWhere("mine", "me", now)).includes('"assignedToId":"me"'));
  assert.ok(JSON.stringify(tabWhere("unassigned", "me", now)).includes('"assignedToId":null'));
  assert.deepEqual(tabWhere("closed", "me", now), { status: "CLOSED" });
  assert.deepEqual(tabWhere("all", "me", now), {});
  assert.equal(searchWhere("   "), null);
  assert.ok(JSON.stringify(searchWhere("jordan")).includes("insensitive"));
});

/* ----------------------------- hub ----------------------------- */

test("hub fans out with increasing seq and survives a throwing listener", () => {
  hub._resetHub();
  const got: SeqEvent[] = [];
  const off1 = hub.subscribe(() => {
    throw new Error("broken stream");
  });
  const off2 = hub.subscribe((e) => got.push(e));
  hub.publish({ kind: "agentsOnline", count: 1 });
  hub.publish({ kind: "botStep", conversationId: "c", step: "Checking…" });
  assert.equal(got.length, 2);
  assert.ok(got[1].seq > got[0].seq);
  off1();
  off2();
  assert.equal(hub.listenerCount(), 0);
});

test("presence: a conversation is online while any customer stream is open", () => {
  hub._resetHub();
  const a = hub.visitorConnected("c1");
  const b = hub.visitorConnected("c1");
  assert.equal(hub.isVisitorOnline("c1"), true);
  a();
  a(); // idempotent release
  assert.equal(hub.isVisitorOnline("c1"), true);
  b();
  assert.equal(hub.isVisitorOnline("c1"), false);
  const s1 = hub.staffConnected("s1");
  hub.staffConnected("s1");
  assert.equal(hub.agentsOnline(), 1, "counts distinct staff, not tabs");
  s1();
});

test("viewing hints expire without a heartbeat", () => {
  hub._resetHub();
  const t0 = 1_000_000;
  hub.setViewing("c1", "s1", "Sam", true, t0);
  assert.equal(hub.viewersOf("c1", t0 + 1000).length, 1);
  assert.equal(hub.viewersOf("c1", t0 + hub.VIEWING_TTL_MS + 1).length, 0);
});

test("published message ids are remembered for the sweep's de-duplication", () => {
  hub._resetHub();
  hub.publish({ kind: "message", conversationId: "c", message: staffMsg({ id: "msg-42" }) });
  assert.equal(hub.wasPublished("msg-42"), true);
  assert.equal(hub.wasPublished("msg-43"), false);
});
EOF
