    cards: null,
    attachment: null,
    internal: false,
    authorId: "staff_123",
    authorName: "Sam Rivera",
    clientId: "cstaffclient1",
    ...over,
  };
}

test("an internal note NEVER projects to a customer message", () => {
  assert.equal(toCustomerMessage(staffMsg({ internal: true, body: "secret" })), null);
  assert.equal(isCustomerVisible({ internal: true }), false);
  assert.equal(isCustomerVisible({ internal: false }), true);
});

test("the customer shape carries no staff id, no full name, no internal flag", () => {
  const c = toCustomerMessage(staffMsg())!;
  const json = JSON.stringify(c);
  assert.ok(!json.includes("staff_123"), "author id must not leak");
  assert.ok(!json.includes("Rivera"), "staff surname must not leak");
  assert.ok(!("internal" in c));
  assert.ok(!("authorId" in c));
  assert.equal(c.agentName, "Sam");
  assert.equal(c.clientId, null, "a staff clientId is meaningless to the customer");
});

test("a visitor's own clientId round-trips so their tab can reconcile", () => {
  const c = toCustomerMessage(staffMsg({ sender: "visitor", authorId: null, authorName: null, clientId: "cvisit00001" }))!;
  assert.equal(c.clientId, "cvisit00001");
  assert.equal(c.agentName, null);
});

test("staff projection falls back to the assignee for legacy agent rows", () => {
  const row = { id: "m", conversationId: "c", sender: "agent", body: "x", cardsJson: null, createdAt: new Date("2026-01-01"), internal: false, authorId: null, clientId: null, attachment: null };
  const s = toStaffMessage(row, new Map([["assignee", "Alex Chen"]]), "assignee");
  assert.equal(s.authorName, "Alex Chen");
  assert.equal(toStaffMessage({ ...row, sender: "visitor" }, new Map(), "assignee").authorId, null);
});

test("cards parse defensively; previews never empty for media", () => {
  assert.equal(parseCards("not json"), null);
  assert.equal(parseCards('{"type":"offer"}'), null, "must be an array");
