  const off1 = hub.subscribe(() => {
    throw new Error("broken stream");
  });
  const off2 = hub.subscribe((e) => got.push(e));
  hub.publish({ kind: "agentsOnline", count: 1 });
  hub.publish({ kind: "botStep", conversationId: "c", step: "Checking…" });
  assert.equal(got.length, 2);
  assert.ok(got[1].seq > got[0].seq);
  off1();
  off2();
