  hub.setViewing("c1", "s1", "Sam", true, t0);
  assert.equal(hub.viewersOf("c1", t0 + 1000).length, 1);
  assert.equal(hub.viewersOf("c1", t0 + hub.VIEWING_TTL_MS + 1).length, 0);
});

