  hub._resetHub();
  hub.publish({ kind: "message", conversationId: "c", message: staffMsg({ id: "msg-42" }) });
  assert.equal(hub.wasPublished("msg-42"), true);
  assert.equal(hub.wasPublished("msg-43"), false);
});
