import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { join, relative } from "node:path";
import { stripComments } from "./_source-tools.ts";

/**
 * Structural guards for the live-chat HTTP surface (2026-10 overhaul).
 *
 * Route modules import Prisma, so (like test/api-http-surface.test.ts) these
 * assert against comment-stripped SOURCE. They pin the invariants that keep
 * one customer out of another's chat and keep staff-only data staff-only:
 *
 *   1. Every STAFF route authenticates the REAL account via chatStaffContext
 *      (requireGrant("liveChat") on realUser) — never currentUser(), so the
 *      dock can't act as an impersonated customer.
 *   2. Every staff route that takes a conversation id runs convoInScope (the
 *      impersonation scope + existence check) before touching it.
 *   3. Every state-changing staff route checks Origin (CSRF backstop).
 *   4. Every CUSTOMER route resolves the caller through customerCaller (which
 *      refuses impersonation) and ownership through findOwnedConversation /
 *      ownershipOr — and never imports the staff projection.
 *   5. Customer-facing paging ANDs the internal-note filter; the AI context,
 *      the ticket transfer and the Discord mirror exclude internal notes.
 */

const ROOT = join(import.meta.dirname, "..");
const code = (p: string) => stripComments(readFileSync(join(ROOT, p), "utf8"));

function routes(dir: string): string[] {
  const out: string[] = [];
  const walk = (d: string) => {
    for (const f of readdirSync(d)) {
      const p = join(d, f);
      if (statSync(p).isDirectory()) walk(p);
      else if (f === "route.ts") out.push(relative(ROOT, p));
    }
  };
  walk(join(ROOT, dir));
  return out.sort();
}

const STAFF = routes("app/api/admin/chat");
const CUSTOMER = routes("app/api/chat");

test("the expected live-chat routes exist", () => {
  for (const r of [
    "app/api/admin/chat/stream/route.ts",
    "app/api/admin/chat/conversations/route.ts",
    "app/api/admin/chat/conversations/[id]/messages/route.ts",
    "app/api/admin/chat/conversations/[id]/actions/route.ts",
    "app/api/admin/chat/conversations/[id]/context/route.ts",
    "app/api/chat/stream/route.ts",
    "app/api/chat/read/route.ts",
  ]) assert.ok(existsSync(join(ROOT, r)), `${r} missing`);
});

test("every staff chat route authenticates through chatStaffContext, never currentUser", () => {
  for (const r of STAFF) {
    const src = code(r);
    assert.ok(src.includes("chatStaffContext("), `${r} must call chatStaffContext()`);
    assert.ok(!/\bcurrentUser\(/.test(src), `${r} must not resolve identity with currentUser()`);
  }
});

test("every staff route under conversations/[id] checks the impersonation scope", () => {
  for (const r of STAFF.filter((x) => x.includes("[id]"))) {
    assert.ok(code(r).includes("convoInScope("), `${r} must call convoInScope() before using the id`);
  }
});

test("every state-changing staff route checks Origin", () => {
  for (const r of STAFF) {
    const src = code(r);
    if (/export\s+async\s+function\s+POST/.test(src)) assert.ok(src.includes("assertSameOrigin("), `${r} POST must assertSameOrigin()`);
  }
});

test("the staff stream filters every per-conversation event through the scope", () => {
  const src = code("app/api/admin/chat/stream/route.ts");
  assert.ok(src.includes("allowed(e.conversationId)"));
  assert.ok(/e\.conversation\.userId\s*!==\s*scope/.test(src), "convo rows outside the impersonated customer are dropped");
});

test("customer chat routes refuse impersonation and scope by visitor/owner", () => {
  for (const r of CUSTOMER.filter((x) => !x.includes("attachment"))) {
    const src = code(r);
    assert.ok(src.includes("customerCaller("), `${r} must resolve the caller with customerCaller()`);
    assert.ok(/findOwnedConversation\(|ownershipOr\(|findLatestOpenConversation\(/.test(src), `${r} must scope by ownership`);
    assert.ok(!src.includes("chatStaffContext"), `${r} must not use staff auth`);
    assert.ok(!/pageStaffMessages|toStaffMessage\(/.test(src), `${r} must never build the staff projection`);
  }
});

test("customer streams project messages through toCustomerMessage", () => {
  const src = code("app/api/chat/stream/route.ts");
  assert.ok(src.includes("toCustomerMessage(e.message)"));
  assert.ok(!src.includes('"viewing"') || /default:\s*\n?\s*return/.test(src));
  assert.ok(src.includes("e.conversationId !== cid"), "events for other conversations are dropped");
});

test("customer paging and previews exclude internal notes", () => {
  const server = code("lib/chat/server.ts");
  assert.ok(/customer\s*\?\s*CUSTOMER_VISIBLE_WHERE/.test(server), "pageRows must AND the visibility filter for customers");
  assert.ok(server.includes("AND m.internal = false"), "DISTINCT ON preview fallback must skip notes");
  assert.ok(code("app/api/chat/list/route.ts").includes("m.internal = false"));
});

test("internal notes never reach the AI, a transferred ticket, or Discord", () => {
  assert.ok(/messages:\s*\{\s*where:\s*\{\s*internal:\s*false\s*\}/.test(code("lib/kb-run.ts")), "assistant history must exclude notes");
  assert.ok(/where:\s*\{\s*internal:\s*false\s*\}/.test(code("lib/actions-chat.ts")), "ticket transfer must exclude notes");
  const send = code("app/api/admin/chat/conversations/[id]/messages/route.ts");
  assert.ok(/if\s*\(\s*!internal\s*&&\s*!res\.duplicate\s*\)\s*\{[\s\S]*mirrorChatMessageToDiscord/.test(send), "Discord mirror only for non-internal");
});

test("internal-note attachments are staff-only", () => {
  const src = code("app/api/chat/attachment/[id]/route.ts");
  assert.ok(/else if\s*\(\s*!meta\.message\.internal\s*\)/.test(src));
  assert.ok(src.includes("private, max-age=31536000, immutable"), "attachments stay out of shared caches");
});

test("customer sends no longer block on the AI or Discord", () => {
  for (const r of ["app/api/chat/route.ts", "app/api/chat/upload/route.ts"]) {
    const src = code(r);
    assert.ok(/after\(async/.test(src), `${r} must defer the assistant/Discord work with after()`);
    const beforeAfter = src.slice(0, src.indexOf("after(async"));
    assert.ok(!/await\s+runAssistant/.test(beforeAfter) && !/await\s+mirrorChatMessageToDiscord/.test(beforeAfter), `${r} awaits slow work before responding`);
  }
});

test("staff writes are attributed to the real staff member", () => {
  const send = code("app/api/admin/chat/conversations/[id]/messages/route.ts");
  assert.ok(/staffId:\s*ctx\.staff\.id/.test(send));
  assert.ok(code("lib/chat/staff-auth.ts").includes('requireGrant("liveChat")'));
});

test("the inbox never selects attachment bytes", () => {
  const sel = code("lib/chat/visibility.ts");
  const m = /MESSAGE_SELECT\s*=\s*\{([\s\S]*?)\}\s*as const/.exec(sel);
  assert.ok(m && !/\bdata:\s*true/.test(m[1]));
  assert.ok(!/include:\s*\{\s*attachment:\s*true/.test(code("lib/chat/server.ts")));
  assert.ok(!/include:\s*\{\s*attachment:\s*true/.test(code("app/api/chat/route.ts")));
});
EOF
