cd /tank/nxeon-wt-livechat && cat > scratch-thumbs.mjs <<'EOF'
import pg from "@prisma/client";
import sharp from "sharp";
const db = new pg.PrismaClient();
const rows = await db.$queryRawUnsafe(`select id, data from "ChatAttachment"`);
let o = 0, t = 0, maxMs = 0;
for (const r of rows) { const s = Date.now(); const b = await sharp(Buffer.from(r.data), { failOn: "none", animated: false }).rotate().resize({ width: 480, height: 480, fit: "inside", withoutEnlargement: true }).webp({ quality: 78 }).toBuffer(); maxMs = Math.max(maxMs, Date.now() - s); o += r.data.length; t += b.length; }
console.log({ n: rows.length, originalMB: (o / 1e6).toFixed(2), thumbsKB: (t / 1e3).toFixed(0), avgThumbKB: (t / rows.length / 1e3).toFixed(1), maxGenMs: maxMs });
await db.$disconnect();
EOF
set -a; . /opt/nxeon/.env 2>/dev/null; set +a; DATABASE_URL="${DATABASE_URL}" node scratch-thumbs.mjs; rm scratch-thumbs.mjs

